		string executablePath = Application.ExecutablePath;
		string userName = Environment.UserName;
		if (!Functions.FileExist(folderPath + "\\", productName + ".lnk") && ((Operators.CompareString(MyProject.Forms.MachineSetup.ComputerNameSet.Text, "JMFMicro", TextCompare: false) != 0) & (Operators.CompareString(userName, "JMF Micro", TextCompare: false) != 0)))
