			Functions.CreateShortCut(executablePath, folderPath, productName);
		}
	}

	public void Version()
	{
		Assembly entryAssembly = Assembly.GetEntryAssembly();
		AssemblyName name = entryAssembly.GetName();
		AppPath = new FileInfo(Application.ExecutablePath).DirectoryName;
		VersionNo = name.Version;
		VersionNumber = VersionNo.ToString();
		VersionName = name.Name;
		Array array = Strings.Split(VersionNo.ToString(), ".");
		ControlAChange("InformationInd", "JMFMicro", "Text", "JMF Micro Software v" + Conversions.ToString(array.GetValue(0)) + "." + Conversions.ToString(array.GetValue(1)) + "." + Conversions.ToString(array.GetValue(2)) + "." + Conversions.ToString(array.GetValue(3)));
		try
		{
			FileVersionInfo versionInfo = FileVersionInfo.GetVersionInfo(AppPath + "\\Restart.exe");
			Version versionNoRestart = new Version(versionInfo.FileVersion);
			VersionNoRestart = versionNoRestart;
		}
		catch (Exception ex)
		{
			ProjectData.SetProjectError(ex);
			Exception ex2 = ex;
			ProjectData.ClearProjectError();
		}
	}

	public string VerBatchSerialNo(string Drive)
	{
		string text = "";
		string text2 = "";
		string setting = Interaction.GetSetting("Dtread", "Aqua", "SerialNo", "0");
		FileVersionInfo versionInfo = FileVersionInfo.GetVersionInfo(Drive + "\\Batch.jmf");
		Version version = new Version(versionInfo.FileVersion);
		text = version.ToString();
		Array array = Strings.Split(text.ToString(), ".");
		int num = Microsoft.VisualBasic.Information.UBound(array);
		string right = default(string);
		for (int i = 0; i <= num; i = checked(i + 1))
		{
			switch (i)
			{
			case 0:
				right = Conversions.ToString(array.GetValue(i));
				break;
			case 1:
				text2 = Conversions.ToString(array.GetValue(i));
				break;
			default:
				text2 = text2 + "." + Conversions.ToString(array.GetValue(i));
				break;
			}
		}
		if (Operators.CompareString(setting, right, TextCompare: false) == 0)
		{
			return text2;
		}
		return "";
	}

