	private void PDFSharpMove(string Drive)
	{
		if (Functions.FileExist(AppPath + "\\", "PdfSharp.dll"))
		{
			if (Functions.FileExist(Drive, "\\PdfSharp.jmf") && Functions.CopyFiles(Drive, "\\PdfSharp.jmf", AppPath) && Functions.FileRename(AppPath + "\\", "PdfSharp.jmf", "PdfSharp.dll"))
			{
				Interaction.SaveSetting("DTread", "Display", "Test", "Q");
			}
		}
		else
		{
			Functions.DeleteFile(Drive, "\\PdfSharp.jmf");
		}
	}

	public bool NewVersion(string Drive, string FileName)
	{
		bool result = false;
		Interaction.SaveSetting("DTread", "Display", "Test", Drive);
		AppPath = new FileInfo(Application.ExecutablePath).DirectoryName;
		Interaction.SaveSetting("DTread", "Display", "Test", Drive + "\\" + FileName + ".jmf " + AppPath);
		try
		{
			if (Operators.CompareString(FileName, VersionName, TextCompare: false) == 0)
			{
				if (Functions.CopyFiles(Drive, "\\" + VersionName + ".jmf", AppPath))
				{
					Interaction.SaveSetting("DTread", "Display", "Test", "P");
					if (Functions.CopyFiles(Drive, "\\Restart.jmf", AppPath))
					{
						Interaction.SaveSetting("DTread", "Display", "Test", "1");
						if (Functions.FileExist(AppPath + "\\", "Restart.exe"))
						{
							Interaction.SaveSetting("DTread", "Display", "Test", "2");
							File.Delete(AppPath + "\\Restart.exe");
							Interaction.SaveSetting("DTread", "Display", "Test", "3");
						}
						if (Functions.FileRename(AppPath + "\\", "Restart.jmf", "Restart.exe"))
						{
							Interaction.SaveSetting("DTread", "Display", "Test", "4");
						}
					}
					if (Functions.FileExist(AppPath + "\\", "Restart.exe"))
					{
						Interaction.SaveSetting("DTread", "Display", "Test", "5");
						Process.Start(AppPath + "\\Restart.exe");
						result = true;
					}
				}
			}
			else if (Operators.CompareString(FileName, "Batch", TextCompare: false) == 0)
			{
				if (Functions.FileRename(Drive + "\\", "Batch.jmf", "Batch.exe"))
				{
					Process.Start(Drive + "\\Batch.exe");
					while (Functions.CheckIfRunning(Drive + "\\Batch.exe"))
					{
					}
					Functions.FileRename(Drive + "\\", "Batch.exe", "Batch.bak");
					result = true;
				}
			}
			else if (Operators.CompareString(FileName, "Version", TextCompare: false) == 0)
			{
				if (Functions.FileRename(Drive + "\\", "Version.jmf", "Version.exe"))
				{
					if (!Functions.CheckIfRunning(Drive + "\\Version.exe") && !ProcessStart)
					{
						ProcessStart = true;
						Process.Start(Drive + "\\Version.exe");
						ProcessDrive = Drive;
					}
				}
				else if (ProcessStart & !Functions.CheckIfRunning(Drive + "\\Version.exe"))
				{
					if (!ProcessStarted)
					{
						ProcessStarted = true;
						MyProject.Forms.MachineSetup.UpdateSettings();
						result = true;
					}
					else if (!ProcessEnd)
					{
						if (Functions.FileRename(ProcessDrive + "\\", "Version.exe", "Version.bak"))
						{
							ProcessEnd = true;
						}
					}
					else if (ProcessEnd && !Functions.FileExist(ProcessDrive + "\\", "Version.*"))
					{
						if (Conversion.Val(SerialNo) >= 1350.0)
						{
							ProgramAtth = Conversions.ToBoolean(Functions.LicenceSet());
							Functions.CheckLicence();
						}
						ProcessStart = false;
						ProcessStarted = false;
						ProcessEnd = false;
						RestartRequired = true;
					}
				}
			}
		}
		catch (Exception ex)
		{
			ProjectData.SetProjectError(ex);
			Exception ex2 = ex;
			Interaction.SaveSetting("DTread", "Display", "Test", " Error:  " + ex2.Message);
			Interaction.SaveSetting("DTread", "Display", "Restart", AppPath + " Error: " + ex2.Message);
			ProjectData.ClearProjectError();
		}
		return result;
	}

	private void NewVersionCheck(string Drive, string FileName)
	{
		int infoHeight = Info.Height;
		string text = "";
		ProgramControlDataTMOff();
		try
		{
			if (Operators.CompareString(Drive, "", TextCompare: false) == 0)
			{
				return;
			}
			if (!ProcessStart)
			{
				FileVersionInfo versionInfo = FileVersionInfo.GetVersionInfo(Drive + "\\" + FileName + ".jmf");
				if (Operators.CompareString(FileName, VersionName, TextCompare: false) == 0)
				{
					Version version = new Version(versionInfo.FileVersion);
					switch (version.CompareTo(VersionNo))
					{
					case 1:
						CloseVersion.SetValue("VersionI", "0");
						VersionDisplay();
						UpdateVersionProgram = true;
						while (!((Operators.CompareString(InfoYesNo, "Yes", TextCompare: false) == 0) | (Operators.CompareString(InfoYesNo, "No", TextCompare: false) == 0) | (ControlLevel == 1)))
						{
							Application.DoEvents();
						}
						if (Operators.CompareString(InfoYesNo, "Yes", TextCompare: false) == 0)
						{
							ProgramControlDataTMOff();
							UpdateVersionBatch = NewVersion(Drive, FileName);
						}
						else if (Operators.CompareString(InfoYesNo, "No", TextCompare: false) == 0)
						{
							PCDCounter = 720;
						}
						InfoYesNo = "";
						VersionDisplayOff(infoHeight);
						break;
					case -1:
					case 0:
						if (Re_Install | (CloseVersion.GetValue("VersionI", "0") == "IV"))
						{
							Re_Install = false;
							ControlAChange("DateTimeInd", "TimeInd", "Color", "Standard");
							CloseVersion.SetValue("VersionI", "0");
							VersionDisplay();
							UpdateVersionProgram = true;
							while (!((Operators.CompareString(InfoYesNo, "Yes", TextCompare: false) == 0) | (Operators.CompareString(InfoYesNo, "No", TextCompare: false) == 0) | (ControlLevel == 1)))
							{
								Application.DoEvents();
							}
							if (Operators.CompareString(InfoYesNo, "Yes", TextCompare: false) == 0)
							{
								UpdateVersionBatch = NewVersion(Drive, FileName);
								ProgramControlDataTMOff();
							}
							else if (Operators.CompareString(InfoYesNo, "No", TextCompare: false) == 0)
							{
								PCDCounter = 720;
							}
							InfoYesNo = "";
							VersionDisplayOff(infoHeight);
						}
						break;
					}
					return;
				}
				switch (FileName)
				{
				case "Batch":
				{
					text = VerBatchSerialNo(Drive);
					int num2 = text.CompareTo(VersionNoBatch);
					if (num2 != 1)
					{
						break;
					}
					VersionDisplay();
					UpdateVersionProgram = true;
					while (!((Operators.CompareString(InfoYesNo, "Yes", TextCompare: false) == 0) | (Operators.CompareString(InfoYesNo, "No", TextCompare: false) == 0) | (ControlLevel == 1)))
					{
					}
					if (Operators.CompareString(InfoYesNo, "Yes", TextCompare: false) == 0)
					{
						if (NewVersion(Drive, FileName))
						{
							ProgramControlDataTMOff();
							Interaction.SaveSetting("Treadmill", "Health", "Version", text);
						}
					}
					else if (Operators.CompareString(InfoYesNo, "No", TextCompare: false) == 0)
					{
						PCDCounter = 720;
					}
					UpdateVersionProgram = false;
					InfoYesNo = "";
					VersionDisplayOff(infoHeight);
					break;
				}
				case "PdfSharp":
					PDFSharpMove(Drive);
					break;
				case "Version":
				{
					text = VerVersionSerialNo(Drive);
					int num = text.CompareTo(VersionNoRun);
					if (num == 1)
					{
						if (NewVersion(Drive, FileName))
						{
							Interaction.SaveSetting("Treadmill", "Health", "VersionRun", text);
						}
					}
					else if ((Operators.CompareString(SerialNo, "0", TextCompare: false) == 0) | ProcessStart)
					{
						NewVersion(Drive, FileName);
					}
					break;
				}
				}
			}
			else
			{
				NewVersion(Drive, FileName);
			}
		}
		catch (Exception ex)
		{
			ProjectData.SetProjectError(ex);
			Exception ex2 = ex;
			ProjectData.ClearProjectError();
		}
	}

	private void VersionDisplay()
	{
		HoldInfo = Info.Text;
		ControlChange("Info", "Text", "");
		ControlChange("Info", "Text", DYWU);
		ControlChange("Info", "Height", Conversions.ToString((double)Info.Height / 2.0));
		ControlChange("btnYes", "Text", YEStxt);
		ControlChange("btnYes", "Visible", "True");
		ControlChange("btnNo", "Text", NOtxt);
		ControlChange("btnNo", "Visible", "True");
		ControlChange("Info", "Visible", "True");
		InfoHold = true;
	}

	private void VersionDisplayOff(int InfoHeight)
	{
		ControlChange("btnYes", "Visible", "False");
		ControlChange("btnNo", "Visible", "False");
		ControlChange("Info", "Height", Conversions.ToString(InfoHeight));
		ControlChange("Info", "Text", HoldInfo);
		InfoHold = false;
	}

