	private void Program_KeyDown(object sender, KeyEventArgs e)
	{
		switch ((int)e.KeyCode)
		{
		case 16:
			ShiftSet = true;
			break;
		case 91:
			ShiftSet = false;
			break;
		case 112:
			if (ShiftSet & !WaterDepthSwChange)
			{
				WaterDepthSwChange = true;
				DoBoxChange("WaterDepthSw");
			}
			break;
		case 113:
			if (ShiftSet)
			{
				DoBoxChange("RemoteWaterDepthUp");
			}
			break;
		case 114:
			if (ShiftSet)
			{
				DoBoxChange("RemoteWaterDepthDown");
			}
			break;
		case 115:
			if (ShiftSet)
			{
				DoBoxChange("RemoteProgramStart");
			}
			break;
		case 116:
			if (ShiftSet)
			{
				DoBoxChange("RemoteSpeedUp");
			}
			break;
		case 117:
			if (ShiftSet)
			{
				DoBoxChange("RemoteSpeedDown");
			}
			break;
		case 119:
			if (ShiftSet)
			{
				DoBoxChange("RemoteGradientUp");
			}
			break;
		case 120:
			if (ShiftSet)
			{
				DoBoxChange("RemoteGradientDown");
			}
			break;
		case 121:
			if (ShiftSet)
			{
				DoBox2Change("RemoteProgramEdit0");
			}
			break;
		case 122:
			if (ShiftSet)
			{
				DoBoxChange("CleanOnOffRemote");
			}
			break;
		case 123:
			if (ShiftSet && (EmergencyEmptyRemoteOne & EmergencyEmptyRemoteTwo))
			{
				RLY88.RemoteEmergencyEmpty();
			}
			break;
		}
		e.Handled = true;
	}

