	public void Mypmc(object sender, PowerModeChangedEventArgs e)
	{
		if (e.Mode == PowerModes.StatusChange)
		{
		}
		if (e.Mode == PowerModes.Suspend)
		{
			Interaction.MsgBox("Suspending");
		}
		if (e.Mode == PowerModes.Resume)
		{
			Interaction.MsgBox("Resuming");
		}
	}

	private bool CheckIfAppRunning(string sProcessName)
	{
		bool result = false;
		try
		{
			Process[] processesByName = Process.GetProcessesByName(sProcessName);
			Interaction.SaveSetting("Health", "Setup", "Progress", Conversions.ToString(processesByName.Length));
			Interaction.SaveSetting("Dtread", "Display", "Close", "No");
			if (processesByName.Length > 1)
			{
				Interaction.SaveSetting("Dtread", "Display", "Close", "Yes");
				EndProgram();
			}
		}
		catch (Exception ex)
		{
			ProjectData.SetProjectError(ex);
			Exception ex2 = ex;
			ProjectData.ClearProjectError();
		}
		Interaction.SaveSetting("Health", "Setup", "Progress", "E");
		return result;
	}

	private void Display_Load(object sender, EventArgs e)
	{
		SystemEvents.PowerModeChanged += Mypmc;
		SetupThreadTimerOperations();
		No_Sleep();
		string path = Environment.GetCommandLineArgs()[0];
		string fileName = Path.GetFileName(path);
		Interaction.SaveSetting("Dtread", "Display", "OldTime", Interaction.GetSetting("Dtread", "Display", "Time", "00:00"));
		Interaction.SaveSetting("Dtread", "Display", "OldDate", Interaction.GetSetting("Dtread", "Display", "Date", "00:00:00"));
		Startup = true;
		checked
		{
			fileName = Strings.Mid(fileName, 1, Strings.Len(fileName) - 4);
			Interaction.SaveSetting("Health", "Setup", "Progress", "0");
			CheckIfAppRunning(fileName);
			SerialNo = Interaction.GetSetting("Dtread", "Aqua", "SerialNo", "0");
			Version();
			LanguageLock = "False";
			base.WindowState = FormWindowState.Normal;
			if (Operators.CompareString(LanguageLock, "False", TextCompare: false) == 0)
			{
				string str = CultureInfo.CurrentCulture.ToString();
				switch (Strings.Mid(str, 1, 2))
				{
				case "en":
					Language = "English";
					break;
				case "nl":
					Language = "Dutch";
					break;
				case "zh":
					Language = "Chinese";
					break;
				case "ru":
					Language = "Russian";
					break;
				default:
					Language = "English";
					break;
				}
			}
			else
			{
				Language = Interaction.GetSetting("DTread", "Aqua", "Language", "English");
			}
			LanguageSet();
			ControlChange("CompanyLogo", "Tag", Interaction.GetSetting("Machine", "Company", "LOGO", "JMF"));
			LOGO(Change: false);
			SpeedProgramHeight = SpeedProgram.Height;
			GradientProgramHeight = GradientProgram.Height;
			OpenSequence();
			Interaction.SaveSetting("Dtread", "Display", "Stage", "0");
			ProgramAtth = Functions.CheckLicence();
			Interaction.SaveSetting("Dtread", "Display", "Stage", "00");
			if (ProgramAtth)
			{
				MyProject.Forms.Speaker.Show();
			}
			Interaction.SaveSetting("Dtread", "Display", "Stage", "1");
			StartupTMon();
			Interaction.SaveSetting("Dtread", "Display", "Stage", "2");
			MyProject.Forms.MachineSetup.UpdateSettings();
			Interaction.SaveSetting("Dtread", "Display", "Stage", "3");
			ScreenResSetup();
			MyProject.Forms.SetupDepth.UpdateSettings();
			try
			{
				EngPassTime = DateTime.ParseExact(Interaction.GetSetting("DTread", "File", "SerialFileEng", "21/02/2000"), "dd/MM/yyyy", DateTimeFormatInfo.InvariantInfo);
				EngineerPass(Pass: true);
			}
			catch (Exception ex)
			{
				ProjectData.SetProjectError(ex);
				Exception ex2 = ex;
				Interaction.SaveSetting("Dtread", "Display", "EngPass", ex2.Message);
				ProjectData.ClearProjectError();
			}
			Interaction.SaveSetting("Dtread", "Display", "Stage", "4");
			Interaction.SaveSetting("Dtread", "Display", "Stage", "5");
			try
			{
				if ((Conversion.Val(Interaction.GetSetting("Health", "Setup", "PortUSBRLY08", "0")) > 0.0) | (Conversions.ToInteger(Interaction.GetSetting("Health", "Setup", "PortUSBRLY08B", "0")) > 0))
				{
					TOTDP_CLIP = "RLY08";
				}
				Interaction.SaveSetting("Dtread", "Display", "Stage", "6");
				Interaction.SaveSetting("Dtread", "Display", "RLY82Startup", "True");
				if (Conversion.Val(Interaction.GetSetting("Health", "Setup", "PortRLY82", "0")) > 0.0)
				{
					TOTDP_CLIP = "RLY82";
				}
				if (Conversion.Val(Interaction.GetSetting("Health", "Setup", "PortUSBOPTORLY88", "0")) > 0.0)
				{
					TOTDP_CLIP = "RLY88";
				}
				if (Conversion.Val(Interaction.GetSetting("Health", "Setup", "PortUSBOPTORLY816", "0")) > 0.0)
				{
					TOTDP_CLIP = "RLY816";
				}
				if (Conversion.Val(Interaction.GetSetting("Health", "Setup", "PortUSBRLY04", "0")) > 0.0)
				{
					TOTDP_CLIP = "RLY04";
				}
				Interaction.SaveSetting("Dtread", "Display", "Stage", "7");
				TOTDP_CLIP = "IOPOT";
				if (Conversion.Val(Interaction.GetSetting("Health", "Setup", "PortUSBISS", "0")) > 0.0)
				{
					TOTDP_CLIP = "USBISS";
				}
				else if (Conversion.Val(Interaction.GetSetting("Health", "Setup", "PortI2CPot", "0")) > 0.0)
				{
					TOTDP_CLIP = "I2CPOT";
				}
				else if (Conversion.Val(Interaction.GetSetting("Health", "Setup", "PortUPOT8PROXR", "0")) > 0.0)
				{
					TOTDP_CLIP = "POT8";
				}
				Interaction.SaveSetting("Dtread", "Display", "Stage", "8");
			}
			catch (Exception ex3)
			{
				ProjectData.SetProjectError(ex3);
				Exception ex4 = ex3;
				ProjectData.ClearProjectError();
			}
			MyProject.Forms.NameListSort.Show();
			Interaction.SaveSetting("Dtread", "Display", "Stage", "9");
			StartProgramPic = "Estop1";
			if (Operators.CompareString(SerialNo, "1443", TextCompare: false) == 0)
			{
				MaxNoSpeedProgramExtra = 0;
				MaxNoGradientProgramExtra = 0;
			}
			if (Operators.CompareString(MachineSetup.Type, "Person", TextCompare: false) == 0)
			{
				MaxSpeedProgramSet = (short)(MaxSpeedProgramSetPerson + MaxNoSpeedProgramExtra);
				MaxGradientProgramSet = (short)(MaxGradientProgramSetPerson + MaxNoGradientProgramExtra);
			}
			else
			{
				MaxSpeedProgramSet = (short)(MaxSpeedProgramSetAnimal + MaxNoSpeedProgramExtra);
				MaxGradientProgramSet = (short)(MaxGradientProgramSetAnimal + MaxNoGradientProgramExtra);
			}
			Interaction.SaveSetting("Dtread", "Display", "Stage", "10");
			if ((Operators.CompareString(Interaction.GetSetting("Machine", "Passed", "MpgOrMm", MilesPerHour), MilesPerHour, TextCompare: false) == 0) & (Operators.CompareString(MachineSetup.Type, "Canine", TextCompare: false) == 0))
			{
				MphOrMm(MilesPerHour);
			}
			else if (Operators.CompareString(Interaction.GetSetting("Machine", "Passed", "MpgOrMm", MilesPerHour), MetersPerMin, TextCompare: false) == 0)
			{
				MphOrMm(MetersPerMin);
			}
			else if (Operators.CompareString(Interaction.GetSetting("Machine", "Passed", "MpgOrMm", MilesPerHour), MetersPerSec, TextCompare: false) == 0)
			{
				MphOrMm(MetersPerSec);
			}
			Interaction.SaveSetting("Dtread", "Display", "Stage", "11");
			if ((Operators.CompareString(Interaction.GetSetting("DTread", "File", "SerialFile1", "0"), "93C72B10FF93A", TextCompare: false) == 0) | (Operators.CompareString(Interaction.GetSetting("DTread", "File", "SerialFile1", "0"), "C74A63F92AA83", TextCompare: false) == 0))
			{
				MyProject.Forms.WIFI.Show();
			}
			Interaction.SaveSetting("Dtread", "Display", "Stage", "12");
			try
			{
				EngDebug = Conversions.ToBoolean(Interaction.GetSetting("Treadmill", "Health", "Debug", "False"));
				if (EngDebug)
				{
					DebugEng.Visible = true;
				}
				else
				{
					DebugEng.Visible = false;
				}
				KeyLock = Conversions.ToBoolean(Interaction.GetSetting("Treadmill", "Health", "Lock", "False"));
				PassKey = Conversions.ToBoolean(Interaction.GetSetting("Treadmill", "Health", "PassKey", "False"));
				if (Operators.CompareString(Interaction.GetSetting("DTread", "File", "SerialFile1", "0"), "93C72B10FF93A", TextCompare: false) == 0)
				{
					RemoteControl = "REMOTE";
					if (Operators.CompareString(SerialNo, "1440", TextCompare: false) == 0)
					{
						MyProject.Forms.MachineSetup.SetRemoteName();
					}
					SetRemote();
				}
				else if (Operators.CompareString(Interaction.GetSetting("DTread", "File", "SerialFile1", "0"), "C74A63F92AA83", TextCompare: false) == 0)
				{
					RemoteControl = "MAIN";
					if (Operators.CompareString(SerialNo, "1440", TextCompare: false) == 0)
					{
						MyProject.Forms.MachineSetup.SetRemoteName();
						DWSManLogo();
					}
				}
				else
				{
					RemoteControl = "OFF";
				}
				SetLocal();
				SetMemorystick();
			}
			catch (Exception ex5)
			{
				ProjectData.SetProjectError(ex5);
				Exception ex6 = ex5;
				ProjectData.ClearProjectError();
			}
			Interaction.SaveSetting("Dtread", "Display", "Stage", "13");
			Decp = Conversions.ToInteger(Interaction.GetSetting("DTread", "Aqua", "Decp", "1"));
			SetupDecp();
			CreateShortcutInStartUp();
			ZeroIndicators();
			Interaction.SaveSetting("DTread", "Display", "CleanOn", "False");
			Interaction.SaveSetting("DTread", "RLY88", "HeaterInput", "False");
			Interaction.SaveSetting("DTread", "RLY88", "CirculationInput", "False");
			Interaction.SaveSetting("DTread", "RLY816", "CirculationPumpError", "False");
			Interaction.SaveSetting("DTread", "RLY816", "Circulation", "False");
			RemoteRead.Enabled = true;
			ComputerName = Functions.GetComputerName();
			Interaction.SaveSetting("Dtread", "Display", "Stage", "14");
		}
	}

