	private void ScreenResSetup()
	{
		FocusTM.Interval = 1000;
		FocusTM.Enabled = true;
		AppPath = new FileInfo(Application.ExecutablePath).DirectoryName;
		MyProject.Forms.SetupDepth.UpdateSettings();
		OriginScreenResW = 1366;
		OriginScreenResH = 768;
		ScreenResH = Screen.PrimaryScreen.Bounds.Height;
		ScreenResW = Screen.PrimaryScreen.Bounds.Width;
		ScreenType = false;
		if ((double)ScreenResH / (double)ScreenResW >= 0.75)
		{
			ScreenType = true;
		}
		ResMultiW = (float)((double)ScreenResW / (double)OriginScreenResW);
		ResMultiH = (float)((double)ScreenResH / (double)OriginScreenResH);
		CompanyLogoH = CompanyLogo.Height;
		CompanyLogoW = CompanyLogo.Width;
		CompanyLogoT = CompanyLogo.Top;
		CompanyLogoL = CompanyLogo.Left;
		checked
		{
			CompanyLogoF = (int)Math.Round(CompanyLogo.Font.Size);
			MyProject.Forms.Information.Top = (int)Math.Round((float)(ProgramStart.Top + ProgramStart.Height) * ResMultiH);
			MyProject.Forms.Information.Left = (int)Math.Round((double)(OriginScreenResW - MyProject.Forms.Information.Width) / 2.0 * (double)ResMultiW);
			MyProject.Forms.Information.Height = (int)Math.Round((float)(SpeedProgram.Height + GradientProgram.Height + (GradientProgram.Top - (SpeedProgram.Top + SpeedProgram.Height))) * ResMultiH);
			MyProject.Forms.Information.Width = (int)Math.Round((float)MyProject.Forms.Information.Width * ResMultiW);
			int num = (int)Math.Round(172f * ResMultiH);
			ControlChange("CompanyLogo", "Height", Conversions.ToString(Math.Round(397f * ResMultiH, 0)));
			ControlChange("CompanyLogo", "Width", Conversions.ToString(Math.Round(1097f * ResMultiW, 0)));
			ControlChange("CompanyLogo", "Top", Conversions.ToString(Math.Round(168f * ResMultiH, 0)));
			ControlChange("CompanyLogo", "Left", Conversions.ToString(Math.Round(120f * ResMultiW, 0)));
			ControlChange("CompanyLogo", "Font", Conversions.ToString(Math.Round(142f * ResMultiH, 0)));
