	private void CloseSequence()
	{
		if ((Operators.CompareString(MachineSetup.Type, "Type", TextCompare: false) != 0) & ProgramAtth)
		{
			if (Operators.CompareString(RemoteControl, "REMOTE", TextCompare: false) == 0)
			{
				ControlAChange("DateTimeInd", "RemoteInd", "Visible", "True");
			}
			else
			{
				ControlAChange("DateTimeInd", "RemoteInd", "Visible", "False");
			}
			GetPersonInfo(NewProgram: false);
			ControlChange("ProgramStart", "Visible", "True");
			MyProject.Forms.Information.PersonHealthCheck();
			VisibleCheck();
		}
		ControlChange("Info", "Visible", "False");
		if (CompanyLogoF > 0)
		{
			ControlChange("CompanyLogo", "Font", CompanyLogoF.ToString());
			ControlChange("CompanyLogo", "Height", CompanyLogoH.ToString());
			ControlChange("CompanyLogo", "Width", CompanyLogoW.ToString());
			ControlChange("CompanyLogo", "Top", CompanyLogoT.ToString());
			ControlChange("CompanyLogo", "Left", CompanyLogoL.ToString());
		}
		ControlChange("TrainingDuration", "Visible", "True");
		ControlChange("Info", "Visible", "True");
		ControlChange("InfoError", "Visible", "True");
		ControlChange("WelcomeBox", "Visible", "True");
		ControlChange("CompanyLogo", "Visible", "False");
		ControlChange("DateTimeInd", "Visible", "True");
		ControlAChange("DateTimeInd", "TimeInd", "Visible", "True");
		ControlAChange("DateTimeInd", "DateInd", "Visible", "True");
		ControlAChange("SpeedProgram", "MaxSpeed", "Visible", "True");
		ControlAChange("InformationInd", "JMFMicro", "Visible", Interaction.GetSetting("Dtread", "Aqua", "SoftwareInd", "True"));
		ControlChange("InformationInd", "Text", "Serial No." + Interaction.GetSetting("Dtread", "Aqua", "SerialNo", "0") + "   ");
		ControlChange("SpeedProgram", "Visible", "True");
		ControlChange("SpeedInd", "Visible", "True");
		ControlChange("DistanceInd", "Visible", "True");
		ControlChange("InformationInd", "Visible", "True");
		if (Conversions.ToBoolean(Interaction.GetSetting("DTread", "Aqua", "DepthAdjustOnOff", "False")))
		{
