	public void GetInfoOffRam(string File, string PersonFile)
	{
		short driveType = 1;
		string text = "\\CustomerData.txt";
		if (MyProject.Forms.Information.Visible)
		{
			return;
		}
		string expression = Functions.CheckForDrives(driveType);
		string[] array = Strings.Split(expression, ",");
		int num = Conversions.ToInteger(array[Microsoft.VisualBasic.Information.LBound(array)]);
		Key = false;
		USB = false;
		if (num == 0)
		{
			int num2 = Microsoft.VisualBasic.Information.UBound(array);
			for (int i = 1; i <= num2; i = checked(i + 2))
			{
				USB = true;
				string driveLetter = array[i];
				string text2 = array[checked(i + 1)];
				string serialNumberFromDriveLetter = Functions.GetSerialNumberFromDriveLetter(driveLetter);
				bool flag = Conversions.ToBoolean(Functions.KeyCheck(serialNumberFromDriveLetter));
				if (flag | !KeyLock)
				{
					Interaction.SaveSetting("Recording", "Running", "RAM", KeyNo + Conversions.ToString((int)KeyNumber));
					Key = true;
					KeyError = false;
				}
				else if (!Key)
				{
					Interaction.SaveSetting("Recording", "Running", "RAM", InvalidKey);
					if (KeyUpdate)
					{
						KeyUpdate = false;
						Functions.KeySet(serialNumberFromDriveLetter);
					}
					else if (!KeyError)
					{
						WriteMachineHistory();
						KeyError = true;
					}
				}
			}
		}
		if (num > 0)
		{
			MyProject.Forms.NameListSort.NameListClear();
			switch (num)
			{
			case 1:
				Interaction.SaveSetting("Recording", "Running", "RAM", NoStick);
				KeyError = false;
				break;
			case 2:
				Interaction.SaveSetting("Recording", "Running", "RAM", StickProblem);
				if (!KeyError)
				{
					WriteMachineHistory();
					KeyError = true;
				}
				break;
			case 3:
				Interaction.SaveSetting("Recording", "Running", "RAM", UnknownProblem);
				if (!KeyError)
				{
					WriteMachineHistory();
					KeyError = true;
				}
				break;
			}
			ProgramRead = false;
			USB = false;
		}
		if ((Operators.CompareString(MyProject.Forms.Information.PersonName.Text, "", TextCompare: false) != 0) & !USB & !ProgramRun & !MyProject.Forms.Information.Visible & !KeyLock)
		{
			ResetDataTM.Enabled = true;
		}
		else
		{
			ResetDataTM.Dispose();
		}
	}

	public string ReadInformationFileA(string Drive, string File)
	{
		string path = Drive + File;
		string text = "";
		string text2 = "";
		if (!ProgramRun)
		{
			try
			{
				StreamReader streamReader = new StreamReader(path);
				string text3 = "";
				do
				{
					text3 = streamReader.ReadLine();
					text2 = text2 + text3 + ",";
				}
				while (text3 != null);
				streamReader.Close();
			}
			catch (Exception ex)
			{
				ProjectData.SetProjectError(ex);
				Exception ex2 = ex;
				string text4 = "NoFile";
				ProjectData.ClearProjectError();
			}
		}
		return text2;
	}

