			text += MyProject.Forms.Information.Trainer.Text;
			if ((Operators.CompareString(MachineSetup.Type, "Animal", TextCompare: false) == 0) | (Operators.CompareString(MachineSetup.Type, "Canine", TextCompare: false) == 0))
			{
				if (Operators.CompareString(MyProject.Forms.Information.AnimalName.Text, "", TextCompare: false) > 0)
				{
					text = text + " " + Andtxt + "\r\n" + MyProject.Forms.Information.AnimalName.Text;
				}
			}
			else if (((Operators.CompareString(MyProject.Forms.Information.PersonName.Text, "", TextCompare: false) > 0) & (Operators.CompareString(MachineSetup.Type, "Person", TextCompare: false) == 0)) && Operators.CompareString(MyProject.Forms.Information.PersonName.Text, "", TextCompare: false) > 0)
			{
				string[] array = Strings.Split(MyProject.Forms.Information.PersonName.Text);
				text = text + " " + Andtxt + "\r\n" + array[0];
			}
		}
		else if ((Operators.CompareString(MachineSetup.Type, "Animal", TextCompare: false) == 0) | (Operators.CompareString(MachineSetup.Type, "Canine", TextCompare: false) == 0))
		{
			if (Operators.CompareString(MyProject.Forms.Information.AnimalName.Text, "", TextCompare: false) > 0)
			{
				text = text + " " + Andtxt + "\r\n" + MyProject.Forms.Information.AnimalName.Text;
