		else if (Operators.CompareString(MachineSetup.Type, "Person", TextCompare: false) == 0 && Operators.CompareString(MyProject.Forms.Information.PersonName.Text, "", TextCompare: false) > 0)
		{
			text = text + " \r\n" + MyProject.Forms.Information.PersonName.Text;
		}
		ControlChange("WelcomeBox", "Text", text);
	}

	private void WritePersonInfoOfRam()
	{
		short driveType = 1;
		string expression = Functions.CheckForDrives(driveType);
		string[] array = Strings.Split(expression, ",");
		int num = Conversions.ToInteger(array[Microsoft.VisualBasic.Information.LBound(array)]);
		if (num == 0)
		{
			int num2 = Microsoft.VisualBasic.Information.UBound(array);
			for (int i = 1; i <= num2; i = checked(i + 2))
			{
				USB = true;
				string drive = array[i];
				string left = array[checked(i + 1)];
				if (Key)
				{
					Interaction.SaveSetting("Recording", "Running", "RAM", NoStick);
					MyProject.Forms.Information.ControlAChange("Person", "RAM", "Text", KeyNo + Conversions.ToString((int)KeyNumber));
					string left2 = AssembleFileText();
					if (Operators.CompareString(left2, "Good", TextCompare: false) == 0)
					{
						WritePersonInfoToDWSList(drive, "", "");
					}
				}
				else if (Operators.CompareString(left, "", TextCompare: false) > 0)
				{
					MyProject.Forms.Information.ControlAChange("Person", "RAM", "Text", InvalidKey);
				}
				ProgramRead = false;
			}
		}
		if (num > 0)
		{
			switch (num)
			{
			case 1:
				MyProject.Forms.Information.ControlAChange("Person", "RAM", "Text", NoStick);
				break;
			case 2:
				MyProject.Forms.Information.ControlAChange("Person", "RAM", "Text", StickProblem);
				break;
			case 3:
				MyProject.Forms.Information.ControlAChange("Person", "RAM", "Text", UnknownProblem);
				break;
			}
			USB = false;
		}
	}

