		}
		Path += Direct;
		if (Operators.CompareString(Functions.DirCreate(Drive, Path), "Failed", TextCompare: false) != 0)
		{
			Path += "\\DWS";
			if (Operators.CompareString(Functions.DirCreate(Drive, Path), "Failed", TextCompare: false) != 0)
			{
				AssembleFileTextSort();
				Functions.WriteInformationFile(Drive, Path, "\\CustomerData.txt", FileTextString, newfile: true);
				ProgramRead = false;
			}
		}
	}

