	private void KeyCloseProgram()
	{
		string left = "0";
		if (CloseVersion == null)
		{
			CloseVersion = Registry.CurrentUser.CreateSubKey("Control\\\\Windows\\\\Panel\\\\");
			CloseVersion.SetValue("Open", "0");
		}
		try
		{
			CloseVersion.SetValue("OpenName", VersionName);
			CloseVersion.SetValue("OpenNo", VersionNo);
			CloseVersion.SetValue("PathName", AppPath);
		}
		catch (Exception ex)
		{
			ProjectData.SetProjectError(ex);
			Exception ex2 = ex;
			ProjectData.ClearProjectError();
		}
		try
		{
			left = CloseVersion.GetValue("Open", "0").ToString();
		}
		catch (Exception ex3)
		{
			ProjectData.SetProjectError(ex3);
			Exception ex4 = ex3;
			ProjectData.ClearProjectError();
		}
		if (Operators.CompareString(left, "EXIT", TextCompare: false) == 0)
		{
			base.TopMost = false;
			CloseVersion.SetValue("Open", "Closing");
			EndProgram();
		}
	}

	private void SetProgramRunIntervalTM(string SetIntervalTimeMin, string SetIntervalTimeSec)
	{
		HoldDurationTimeSec = SetIntervalTimeSec;
		HoldDurationTimeMin = SetIntervalTimeMin;
		checked
		{
			ProgramRunSeconds = Conversions.ToInteger(SetIntervalTimeMin) * 60 + Conversions.ToInteger(SetIntervalTimeSec);
			float num = (float)ProgramRunSeconds / 60f;
			int num2 = 1;
			do
			{
				ProgramRunIntervals[num2] = num * (float)num2;
				num2++;
			}
			while (num2 <= 60);
			HoldDurationTimeSeconds = ProgramRunSeconds;
			SetDurationChange(SetIntervalTimeMin + ":" + SetIntervalTimeSec);
		}
	}

	public void TimeDateTMSet()
	{
		TimeDateTM = new System.Threading.Timer(TimeDateTM_Tick, null, 1000, 1000);
	}

	private void TimeDateTM_Tick(object eventSender)
	{
		Interaction.SaveSetting("Dtread", "Display", "Stage20", "200");
		if (EngPass & HandleCounter)
		{
			NumberOfHandles = Process.GetCurrentProcess().HandleCount;
			RemoteIndChange(Conversions.ToString(NumberOfHandles));
			RemoteIndColourChange("Control");
			ControlAChange("DateTimeInd", "RemoteInd", "Visible", "True");
		}
		else if (Operators.CompareString(RemoteControl, "REMOTE", TextCompare: false) == 0)
		{
			ControlAChange("DateTimeInd", "RemoteInd", "Visible", "True");
			RemoteIndColourChange("Red");
			RemoteIndChange("REMOTE");
		}
		else
		{
			ControlAChange("DateTimeInd", "RemoteInd", "Visible", "False");
		}
		if (Lift)
		{
			ControlAChange("WaterDepth", "MoveCountInd", "Visible", Conversions.ToString(EngPass));
		}
		Interaction.SaveSetting("Dtread", "Display", "Stage20", "210");
		checked
		{
			TimeDatemsec++;
			if ((DateAndTime.Now.Second != SecondMem) | ((DateAndTime.Now.Second == 0) & (SecondMem == 59)))
			{
				SecondMem = DateAndTime.Now.Second;
				TimeDateChange();
				UpdateRunProgram();
				TimeDatemsecArray[TimeDatemsecIndex] = TimeDatemsec;
				TimeDatemsec = 0;
				DurationmsecCount = 0;
				TimeDatemsecIndex++;
				if (TimeDatemsecIndex == 20)
				{
					TimeDatemsecIndex = 0;
				}
				TimeDatemsecAve = TimeDatemsecArrayAve();
			}
			Interaction.SaveSetting("Dtread", "Display", "Stage20", "220");
			ProgramRunInterval = Math.Round((double)ProgramRunSeconds * TimeDatemsecAve, 3);
			if (((ConveyorActive & MotorRun) | TestEStop) && ((ProgramRun & !EmergencyEmpty & !ProgramHold) | (ProgramRun & !EmergencyEmpty & ProgramHold & (Conversions.ToInteger(Speed_kmh.Text) > 0))))
			{
				if (ProgramHold & (Conversions.ToInteger(Speed_kmh.Text) > 0) & (ProgramMark == 0))
				{
					ProgramMark = IndexProgram1;
				}
				if (TimeDatemsecAve * (double)DurationmsecCount + 1.0 < 1.0)
				{
					DurationmsecCount++;
				}
			}
			Interaction.SaveSetting("Dtread", "Display", "Stage20", "230");
			if (((double)DurationSec + TimeDatemsecAve * (double)DurationmsecCount >= (double)ProgramRunIntervals[DisplayCount]) & (DisplayCount > 0))
			{
				UpdateDisplay();
				ProgramMark = 0;
				if (DisplayCount <= 60)
				{
					DisplayCount++;
				}
			}
			Interaction.SaveSetting("Dtread", "Display", "Stage20", "231");
			DemandRemote();
			Interaction.SaveSetting("Dtread", "Display", "Stage20", "240");
		}
	}

	public string SecondsToText(double Seconds)
	{
		TimeSpan timeSpan = TimeSpan.FromSeconds(Seconds);
		int hours = timeSpan.Hours;
		int minutes = timeSpan.Minutes;
		int seconds = timeSpan.Seconds;
		int milliseconds = timeSpan.Milliseconds;
		string text = $"{minutes:D2}";
		string text2 = $"{seconds:D2}";
		string text3 = $"{milliseconds:D3}";
		return text + ":" + text2 + "." + text3;
	}

	private double TimeDatemsecArrayAve()
	{
		int num = 0;
		checked
		{
			int num2 = default(int);
			do
			{
				if (TimeDatemsecArray[num] == 0)
				{
					TimeDatemsecArray[num] = 21;
				}
				num2 += TimeDatemsecArray[num];
				num++;
			}
			while (num <= 19);
			return Math.Round(1.0 / ((double)num2 / 20.0), 3);
		}
	}

	private void TimeDateChange()
	{
		if (RestartRequired)
		{
			RestartRequired = false;
			Restarting = true;
			if (EngPass)
			{
				switch (Interaction.MsgBox("Do you want to restart computer?", MsgBoxStyle.YesNoCancel, "Computer Restart"))
				{
				case MsgBoxResult.Yes:
					Restart();
					break;
				case MsgBoxResult.No:
					EndProgram();
					break;
				}
			}
			else
			{
				Restart();
			}
		}
		KeyCloseProgram();
		if (!Flash)
		{
			Flash = true;
		}
		else
		{
			Flash = false;
		}
		if (!WaterTooDeep)
		{
			WDActualColourChange("Control");
		}
		else if (!Flash)
		{
			WDActualColourChange("Red");
		}
		else
		{
			WDActualColourChange("Control");
