						ControlAChange("TimerBox", "ShortTimerStopCycle", "Text", (Conversions.ToInteger(ShortTimerStopCycle.Text) + 1).ToString());
						if ((Conversion.Val(ShortTimerStopStartCyclesSet.Text) > 0.0) & (Conversion.Val(ShortTimerStopCycle.Text) >= Conversion.Val(ShortTimerStopStartCyclesSet.Text)))
						{
							RemoteProgramStart();
