	private void WeeklyReportCheck()
	{
		DateTime dateTime = FindMonday();
		if (Operators.CompareString(CloseVersion.GetValue("REPORTWEEK", "").ToString(), "", TextCompare: false) != 0)
		{
			try
			{
				DateTime date = Conversions.ToDate(CloseVersion.GetValue("REPORTWEEK", "0"));
				string value = Conversions.ToString(DateAndTime.DateDiff(DateInterval.Day, date, DateAndTime.Now));
				if (Conversions.ToInteger(value) >= 7)
				{
					WeeklyReport();
					dateTime = FindMonday();
					CloseVersion.SetValue("REPORTWEEK", dateTime.ToString("d"));
				}
				return;
			}
			catch (Exception ex)
			{
				ProjectData.SetProjectError(ex);
				Exception ex2 = ex;
				ProjectData.ClearProjectError();
				return;
			}
		}
		CloseVersion.SetValue("REPORTWEEK", dateTime.ToString("d"));
	}

