	public double PowerFromTime(float Seconds, float KW)
	{
		double num = Math.Round(Seconds / 3600f, 0);
		Seconds %= 3600f;
		double num2 = Math.Round(Seconds / 60f, 0);
		Seconds %= 60f;
		double num3 = 1.0 / 60.0 * num2;
		double num4 = 1.0 / 600.0 * (double)Seconds;
		return num + num3 + num4 * (double)KW;
	}

	public string SecondsToHourandMinutes(float Seconds)
	{
		double num = Math.Round(Seconds / 3600f, 0);
		Seconds %= 3600f;
		double num2 = Math.Round(Seconds / 60f, 0);
		Seconds %= 60f;
		string text = num.ToString().PadLeft(2, '0');
		string text2 = num2.ToString().PadLeft(2, '0');
		string text3 = Seconds.ToString().PadLeft(2, '0');
		return num.ToString().PadLeft(2, '0') + ":" + num2.ToString().PadLeft(2, '0') + ":" + Seconds.ToString().PadLeft(2, '0');
	}

