	public DateTime FindMonday()
	{
		DateTime today = DateTime.Today;
		int num = (int)today.DayOfWeek;
		checked
		{
			if (num < 1)
			{
				num += 7;
			}
			int num2 = num - 1;
			return today.AddDays(-num2);
		}
	}

	private void DayReportCheck()
	{
		if (Operators.CompareString(CloseVersion.GetValue("REPORTDAY", "").ToString(), "", TextCompare: false) != 0)
		{
			try
			{
				DateTime date = Conversions.ToDate(CloseVersion.GetValue("REPORTDAY", "0"));
				double num = DateAndTime.DateDiff(DateInterval.Day, date, DateAndTime.Now);
				if (num >= 1.0)
				{
					DayReport();
					CloseVersion.SetValue("REPORTDAY", DateTime.Today.ToString("d"));
				}
				return;
			}
			catch (Exception ex)
			{
				ProjectData.SetProjectError(ex);
				Exception ex2 = ex;
				ProjectData.ClearProjectError();
				return;
			}
		}
		CloseVersion.SetValue("REPORTDAY", DateTime.Today.ToString("d"));
	}

	private void PayLockCheck()
	{
		if (Conversion.Val(CloseVersion.GetValue("TMLK", "0").ToString()) > 0.0)
		{
			Locked = true;
		}
		else
		{
			Locked = false;
		}
		if (Conversion.Val(CloseVersion.GetValue("OFFSETNUM", "0").ToString()) > 0.0)
		{
			try
			{
				Day day = (Day)Conversions.ToInteger(CloseVersion.GetValue("OFFSETNUM", "0"));
				DateTime date = Conversions.ToDate(CloseVersion.GetValue("OFFSET", "")).AddDays((double)checked(day + 1));
				string text = Conversions.ToString(DateAndTime.DateDiff(DateInterval.Day, DateAndTime.Now, date));
				if (Conversions.ToInteger(text) <= 0)
				{
					ProgramLock = true;
					if (Operators.CompareString(InformationInd.Text, "Locked Serial No." + Interaction.GetSetting("Dtread", "Aqua", "SerialNo", "0") + "   ", TextCompare: false) != 0)
					{
						ControlChange("InformationInd", "Text", "Locked Serial No." + Interaction.GetSetting("Dtread", "Aqua", "SerialNo", "0") + "   ");
					}
				}
				else if (Operators.CompareString(InformationInd.Text, "Locked in " + text + " Days. Serial No." + Interaction.GetSetting("Dtread", "Aqua", "SerialNo", "0") + "   ", TextCompare: false) != 0)
				{
					ControlChange("InformationInd", "Text", "Locked in " + text + " Days. Serial No." + Interaction.GetSetting("Dtread", "Aqua", "SerialNo", "0") + "   ");
				}
				return;
			}
			catch (Exception ex)
			{
				ProjectData.SetProjectError(ex);
				Exception ex2 = ex;
				ProgramLock = true;
				if (Operators.CompareString(InformationInd.Text, "Locked Serial No." + Interaction.GetSetting("Dtread", "Aqua", "SerialNo", "0") + "   ", TextCompare: false) != 0)
				{
					ControlChange("InformationInd", "Text", "Locked Serial No." + Interaction.GetSetting("Dtread", "Aqua", "SerialNo", "0") + "   ");
				}
				ProjectData.ClearProjectError();
				return;
			}
		}
		if (Operators.CompareString(InformationInd.Text, "Serial No." + Interaction.GetSetting("Dtread", "Aqua", "SerialNo", "0") + "   ", TextCompare: false) != 0)
		{
			ControlChange("InformationInd", "Text", "Serial No." + Interaction.GetSetting("Dtread", "Aqua", "SerialNo", "0") + "   ");
		}
	}

	private void PayLockSet(int DaysGiven)
	{
		CloseVersion.SetValue("OFFSET", DateAndTime.Now);
		CloseVersion.SetValue("OFFSETNUM", DaysGiven.ToString());
	}

	private void PayLockClear()
	{
		CloseVersion.SetValue("OFFSET", DateAndTime.Now);
		CloseVersion.SetValue("OFFSETNUM", "0");
		ProgramLock = false;
	}

	private void WDActualColourChange(string SetColor)
	{
		try
		{
			if (WaterDepthActual.InvokeRequired)
			{
				SetControlCallback method = WDActualColourChange;
				Invoke(method, SetColor);
				return;
			}
			switch (SetColor)
			{
			case "Transparent":
				WaterDepthActual.ForeColor = Color.Transparent;
				break;
			case "Red":
				WaterDepthActual.ForeColor = Color.Red;
				break;
			case "Control":
				WaterDepthActual.ForeColor = Color.FromArgb(128, 255, 255);
				break;
			}
		}
		catch (Exception ex)
		{
			ProjectData.SetProjectError(ex);
			Exception ex2 = ex;
			ProjectData.ClearProjectError();
		}
	}

	private void UpdateHeating()
	{
		if (EmergencyStop)
		{
			if ((Operators.CompareString(Interaction.GetSetting("DTread", "RLY88", "HeaterInput", "False"), "False", TextCompare: false) == 0) | USBOPTORLY816.SandBoxOnOff)
			{
				ControlAChange("WaterTemp", "WaterTempInd", "BringToFront", "True");
				if ((Operators.CompareString(Interaction.GetSetting("DTread", "RLY816", "CirculationPumpError", "False"), "False", TextCompare: false) == 0) & (Operators.CompareString(Interaction.GetSetting("DTread", "RLY816", "Circulation", "False"), "True", TextCompare: false) == 0))
				{
					ControlAChange("WaterTemp", "WaterTempInd", "Text", "");
					ImageControlChange("WaterTemp", "WaterTempInd", "WaterTempInd", "symOn");
					Interaction.SaveSetting("Dtread", "Treadmill", "Heater", "On");
					if (!USBOPTORLY816.SandBoxOnOff & (Operators.CompareString(Interaction.GetSetting("DTread", "RLY88", "CirculationInput", "False"), "True", TextCompare: false) == 0))
					{
						if (CirculationAnimate == 1)
						{
							CirculationAnimate = 2;
							ImageControlChange("WaterTemp", "HeaterInd", "HeaterInd", "HeaterOff2");
						}
						else if (CirculationAnimate == 2)
						{
							CirculationAnimate = 3;
							ImageControlChange("WaterTemp", "HeaterInd", "HeaterInd", "HeaterOff3");
						}
						else if (CirculationAnimate == 3)
						{
							CirculationAnimate = 4;
							ImageControlChange("WaterTemp", "HeaterInd", "HeaterInd", "HeaterOff4");
						}
						else if ((CirculationAnimate == 4) | (CirculationAnimate == 0))
						{
							CirculationAnimate = 1;
							ImageControlChange("WaterTemp", "HeaterInd", "HeaterInd", "HeaterOff1");
						}
						HeatingError = false;
					}
					else
					{
						if (CirculationAnimate == 1)
						{
							CirculationAnimate = 2;
							ImageControlChange("WaterTemp", "HeaterInd", "HeaterInd", "CircHeaterOff2");
						}
						else if (CirculationAnimate == 2)
						{
							CirculationAnimate = 3;
							ImageControlChange("WaterTemp", "HeaterInd", "HeaterInd", "CircHeaterOff3");
						}
						else if (CirculationAnimate == 3)
						{
							CirculationAnimate = 4;
							ImageControlChange("WaterTemp", "HeaterInd", "HeaterInd", "CircHeaterOff4");
						}
						else if ((CirculationAnimate == 4) | (CirculationAnimate == 0))
						{
							CirculationAnimate = 1;
							ImageControlChange("WaterTemp", "HeaterInd", "HeaterInd", "CircHeaterOff1");
						}
						HeatingError = false;
					}
				}
				else if (Operators.CompareString(Interaction.GetSetting("DTread", "RLY816", "CirculationPumpError", "False"), "True", TextCompare: false) == 0)
				{
					ControlAChange("WaterTemp", "WaterTempInd", "Text", "");
					if (Operators.CompareString(Interaction.GetSetting("DTread", "RLY816", "Circulation", "False"), "True", TextCompare: false) == 0)
					{
						ImageControlChange("WaterTemp", "WaterTempInd", "WaterTempInd", "symOn");
					}
					else
					{
						ImageControlChange("WaterTemp", "WaterTempInd", "WaterTempInd", "SymErrOff");
					}
					if (Operators.CompareString(Interaction.GetSetting("Dtread", "Treadmill", "Heater", "Off"), "Error", TextCompare: false) != 0)
					{
						Interaction.SaveSetting("Dtread", "Treadmill", "Heater", "Error");
						WriteMachineHistory();
					}
					ImageControlChange("WaterTemp", "HeaterInd", "HeaterInd", "CircHeater");
					HeatingError = true;
				}
				else
				{
					if (USBOPTORLY816.SandBoxOnOff & (Operators.CompareString(Interaction.GetSetting("DTread", "RLY88", "HeaterInput", "False"), "True", TextCompare: false) == 0))
					{
						ImageControlChange("WaterTemp", "WaterTempInd", "WaterTempInd", "SymOff");
						Interaction.SaveSetting("Dtread", "Treadmill", "Heater", "Off");
						ImageControlChange("WaterTemp", "HeaterInd", "HeaterInd", "CircHeater");
					}
					else
					{
						ImageControlChange("WaterTemp", "WaterTempInd", "WaterTempInd", "SymOff");
						Interaction.SaveSetting("Dtread", "Treadmill", "Heater", "Off");
						ImageControlChange("WaterTemp", "HeaterInd", "HeaterInd", "CircHeaterWarm1");
					}
					ControlAChange("WaterTemp", "WaterTempInd", "Text", "");
					HeatingError = false;
				}
			}
			else if ((Operators.CompareString(Interaction.GetSetting("DTread", "RLY816", "CirculationPumpError", "False"), "False", TextCompare: false) == 0) & (Operators.CompareString(Interaction.GetSetting("DTread", "RLY816", "Circulation", "False"), "True", TextCompare: false) == 0))
			{
				ControlAChange("WaterTemp", "WaterTempInd", "BringToFront", "True");
				if (((Operators.CompareString(Interaction.GetSetting("DTread", "RLY88", "CirculationInput", "False"), "True", TextCompare: false) == 0) & (Operators.CompareString(Interaction.GetSetting("DTread", "RLY816", "Heater", "True"), "True", TextCompare: false) == 0) & (Operators.CompareString(Interaction.GetSetting("DTread", "Aqua", "TankTempGauge", "False"), "True", TextCompare: false) == 0) & (Operators.CompareString(Interaction.GetSetting("Dtread", "WaterTemp", "TankTempHeater", "False"), "True", TextCompare: false) == 0)) | ((Operators.CompareString(Interaction.GetSetting("DTread", "RLY88", "CirculationInput", "False"), "True", TextCompare: false) == 0) & (Operators.CompareString(Interaction.GetSetting("DTread", "RLY816", "Heater", "True"), "True", TextCompare: false) == 0) & (Operators.CompareString(Interaction.GetSetting("DTread", "Aqua", "TankTempGauge", "False"), "False", TextCompare: false) == 0)))
				{
					ControlAChange("WaterTemp", "WaterTempInd", "Text", "");
					ImageControlChange("WaterTemp", "WaterTempInd", "WaterTempInd", "symOn");
					Interaction.SaveSetting("Dtread", "Treadmill", "Heater", "On");
					if (CirculationAnimate == 1)
					{
						CirculationAnimate = 2;
						ImageControlChange("WaterTemp", "HeaterInd", "HeaterInd", "HeaterOn2");
					}
					else if (CirculationAnimate == 2)
					{
						CirculationAnimate = 3;
						ImageControlChange("WaterTemp", "HeaterInd", "HeaterInd", "HeaterOn3");
					}
					else if (CirculationAnimate == 3)
					{
						CirculationAnimate = 4;
						ImageControlChange("WaterTemp", "HeaterInd", "HeaterInd", "HeaterOn4");
					}
					else if ((CirculationAnimate == 4) | (CirculationAnimate == 0))
					{
						CirculationAnimate = 1;
						ImageControlChange("WaterTemp", "HeaterInd", "HeaterInd", "HeaterOn1");
					}
					HeatingError = false;
				}
				else if (Operators.CompareString(Interaction.GetSetting("DTread", "RLY816", "CirculationErrorPump", "False"), "True", TextCompare: false) == 0)
				{
					ControlAChange("WaterTemp", "WaterTempInd", "Text", "");
					ImageControlChange("WaterTemp", "WaterTempInd", "WaterTempInd", "SymErrOff");
					ImageControlChange("WaterTemp", "HeaterInd", "HeaterInd", "CircHeater");
					HeatingError = true;
				}
				else
				{
					ControlAChange("WaterTemp", "WaterTempInd", "Text", "");
					ImageControlChange("WaterTemp", "WaterTempInd", "WaterTempInd", "SymOff");
					ImageControlChange("WaterTemp", "HeaterInd", "HeaterInd", "CircHeater");
					HeatingError = false;
				}
			}
		}
		else
		{
			ImageControlChange("WaterTemp", "HeaterInd", "HeaterInd", "CircHeater");
			ImageControlChange("WaterTemp", "WaterTempInd", "WaterTempInd", "SymOff");
		}
		if ((HeatingError & !ErrorHeating) | (!HeatingError & ErrorHeating))
		{
			WriteMachineHistory();
			ErrorHeating = HeatingError;
		}
	}

	private void UpdateWaterDepth()
	{
		if (EmergencyStop)
		{
			if (Operators.CompareString(Interaction.GetSetting("DTread", "RLY816", "EmptyPump", "False"), "True", TextCompare: false) == 0)
			{
				if (Lift)
				{
					if (EmptyAnimate == 1)
					{
						EmptyAnimate = 2;
						ImageControlChange("WaterDepth", "WaterDepthLabel", "WaterDepthLabel", "Raise2");
					}
					else if (EmptyAnimate == 2)
					{
						EmptyAnimate = 3;
						ImageControlChange("WaterDepth", "WaterDepthLabel", "WaterDepthLabel", "Raise3");
					}
					else if (EmptyAnimate == 3)
					{
						EmptyAnimate = 4;
						ImageControlChange("WaterDepth", "WaterDepthLabel", "WaterDepthLabel", "Raise4");
					}
					else if ((EmptyAnimate == 4) | (EmptyAnimate == 0))
					{
						EmptyAnimate = 1;
						ImageControlChange("WaterDepth", "WaterDepthLabel", "WaterDepthLabel", "Raise1");
					}
				}
				else if (EmptyAnimate == 1)
				{
					EmptyAnimate = 2;
					ImageControlChange("WaterDepth", "WaterDepthLabel", "WaterDepthLabel", "Empty2");
				}
				else if (EmptyAnimate == 2)
				{
					EmptyAnimate = 3;
					ImageControlChange("WaterDepth", "WaterDepthLabel", "WaterDepthLabel", "Empty3");
				}
				else if (EmptyAnimate == 3)
				{
					EmptyAnimate = 4;
					ImageControlChange("WaterDepth", "WaterDepthLabel", "WaterDepthLabel", "Empty4");
				}
				else if ((EmptyAnimate == 4) | (EmptyAnimate == 0))
				{
					EmptyAnimate = 1;
					ImageControlChange("WaterDepth", "WaterDepthLabel", "WaterDepthLabel", "Empty1");
				}
			}
			else if (Operators.CompareString(Interaction.GetSetting("DTread", "RLY816", "FillPump", "False"), "True", TextCompare: false) == 0)
