					{
						FillAnimate = 3;
						ImageControlChange("WaterDepth", "WaterDepthLabel", "WaterDepthLabel", "Lower3");
					}
					else if (FillAnimate == 3)
					{
						FillAnimate = 4;
						ImageControlChange("WaterDepth", "WaterDepthLabel", "WaterDepthLabel", "Lower4");
					}
					else if ((FillAnimate == 4) | (FillAnimate == 0))
					{
						FillAnimate = 1;
						ImageControlChange("WaterDepth", "WaterDepthLabel", "WaterDepthLabel", "Lower1");
					}
				}
				else if (FillAnimate == 1)
				{
					FillAnimate = 2;
					ImageControlChange("WaterDepth", "WaterDepthLabel", "WaterDepthLabel", "Fill2");
				}
				else if (FillAnimate == 2)
				{
					FillAnimate = 3;
					ImageControlChange("WaterDepth", "WaterDepthLabel", "WaterDepthLabel", "Fill3");
				}
				else if (FillAnimate == 3)
				{
					FillAnimate = 4;
					ImageControlChange("WaterDepth", "WaterDepthLabel", "WaterDepthLabel", "Fill4");
				}
				else if ((FillAnimate == 4) | (FillAnimate == 0))
				{
					FillAnimate = 1;
					ImageControlChange("WaterDepth", "WaterDepthLabel", "WaterDepthLabel", "Fill1");
				}
			}
			else
			{
				ImageControlChange("WaterDepth", "WaterDepthLabel", "WaterDepthLabel", "FillEmptyOff");
