	private void EstopCheck()
	{
		string text = "";
		bool flag = false;
		if (ProgramAtth)
		{
			if (!TestEStop)
			{
				if (POT8.BoardError & !UPOT8Startup)
				{
					flag = true;
					if (Operators.CompareString(text, "", TextCompare: false) > 0)
					{
						text += ";";
					}
					text += "23";
				}
				if (USBISS.USBISSError & !USBISSStartup)
				{
					flag = true;
					if (Operators.CompareString(text, "", TextCompare: false) > 0)
					{
						text += ";";
					}
					text += "36";
				}
				if (USBISS.I2CPotError & !USBISSStartup)
				{
					flag = true;
					if (Operators.CompareString(text, "", TextCompare: false) > 0)
					{
						text += ";";
					}
					text += "37";
				}
				if (RLY04.BoardError & !RLY04Startup)
				{
					flag = true;
					if (Operators.CompareString(text, "", TextCompare: false) > 0)
					{
						text += ";";
					}
					text += "24";
				}
				if (!RLY08Startup && (RLY08.BoardError & !RLY08Startup))
				{
					flag = true;
					if (Operators.CompareString(text, "", TextCompare: false) > 0)
					{
						text += ";";
					}
					text += "26";
				}
				if ((RLY88.BoardError & !RLY88Startup) | (!RLY88.BoardError & (RLY88.TypeCheck == 2) & !USBOPTORLY88.VoltageOK))
				{
					flag = true;
					if (Operators.CompareString(text, "", TextCompare: false) > 0)
					{
						text += ";";
					}
					text = ((RLY88.TypeCheck != 2) ? (text + "10") : (text + "8"));
				}
				if (((Operators.CompareString(Interaction.GetSetting("Dtread", "RLY82", "BoardError", "False"), "True", TextCompare: false) == 0) & !RLY82Startup) | ((Operators.CompareString(Interaction.GetSetting("Dtread", "RLY82", "BoardError", "False"), "True", TextCompare: false) == 0) & RLY82.BoardError))
				{
					flag = true;
					if (Operators.CompareString(text, "", TextCompare: false) > 0)
					{
						text += ";";
					}
					text += "40";
				}
				if (!RLY816Startup && (RLY816.BoardError | (!RLY816.BoardError & (RLY816.TypeCheck == 2) & !USBOPTORLY816.VoltageOK)))
				{
					flag = true;
					if (Operators.CompareString(text, "", TextCompare: false) > 0)
					{
						text += ";";
					}
					text = ((RLY816.TypeCheck != 2) ? (text + "11") : (text + "9"));
				}
			}
			if (flag | TestEStop)
			{
				CommsDelayTM.Enabled = true;
			}
			else
			{
				CommsDelayTM.Dispose();
				RLY88.EmergencyStopActive = false;
				RLY816.EmergencyStopActive = false;
			}
			if ((!flag & WaterDepth.Visible) | (TestEStop & WaterDepth.Visible))
			{
				if (!DoorClosedIn & MachineSetup.DoorSensorsOnOff)
				{
					text += ";14";
				}
				if (!DoorClosedOut & MachineSetup.DoorSensorsOnOff)
				{
					text += ";15";
				}
				if (PumpCheck & !Lift)
				{
					text += ";17";
				}
				else if (PumpCheck)
				{
					text += ";52";
				}
				if (RLY82.ErrorInput)
				{
					text += ";52";
				}
				if (RLY82.DirectionError)
				{
					text += ";53";
				}
				if (USBOPTORLY816.LiftMaxHeight)
				{
					text += ";50";
				}
				if (USBOPTORLY816.LiftLowHeight)
				{
					text += ";49";
				}
				if (USBOPTORLY88.LowerGroundDoorOpen)
				{
					text += ";48";
				}
				if (USBOPTORLY88.MainRightDoorOpen)
				{
					text += ";47";
				}
				if (USBOPTORLY88.MainLeftDoorOpen)
				{
					text += ";46";
				}
			}
			if (InclineFault & !TestEStop)
			{
				text += ";18";
			}
		}
		else
		{
			SerialNo = Interaction.GetSetting("Dtread", "Aqua", "SerialNo", "0");
			text += ";22";
			if (Operators.CompareString(SerialNo, "1350", TextCompare: false) < 0)
			{
				text += ";25";
			}
		}
		if (RefError)
		{
			text += ";33";
		}
		if (MemError)
		{
			text += ";34";
		}
		if (Operators.CompareString(Interaction.GetSetting("DTread", "RLY816", "CirculationPumpError", "False"), "True", TextCompare: false) == 0)
		{
			text += ";35";
		}
		if (ComputerNameError)
		{
			text += ";43";
		}
		if (ProgramEnd)
		{
			return;
		}
		if (Operators.CompareString(text, "", TextCompare: false) > 0)
		{
			ControlChange("InfoError", "Text", Conversions.ToString(Functions.InformationPrint(text)));
			RemoteInfoError = text;
		}
		else
		{
			ControlChange("InfoError", "Text", "");
			RemoteInfoError = "";
		}
		if ((flag & !ErrorComms) | (!flag & ErrorComms))
		{
			ErrorComms = flag;
			if (flag)
			{
				WriteMachineHistory();
			}
		}
	}

	public void StartupTMSet()
	{
		StartupTM = new System.Threading.Timer(StartupTM_Tick, null, -1, -1);
	}

	public void StartupTMOff()
	{
		StartupTM.Change(-1, -1);
	}

	public void StartupTMon()
	{
		StartupTM.Change(3000, 3000);
	}

	private void StartupTM_Tick(object sender)
	{
		StartupTMOff();
		CloseSequence();
	}

	private void PersonEdit_Click(object sender, EventArgs e)
	{
		if (ControlLevel == 0)
		{
			DoBox2Change("RemoteProgramEdit0");
		}
	}

	public void RemoteProgramEdit(int WhereFrom)
	{
		if (!ProgramAtth)
		{
			return;
		}
		if (!NoChanges & !LevelZero)
		{
			DisplayOn = true;
			if ((Operators.CompareString(RemoteControl, "REMOTE", TextCompare: false) == 0 && WhereFrom == 1) | (Operators.CompareString(RemoteControl, "REMOTE", TextCompare: false) != 0))
			{
				if (ProgramReset)
				{
					return;
				}
				if (!ProgramRun)
				{
					if (MyProject.Forms.InfoEnter.Visible)
					{
						return;
					}
					if (MyProject.Forms.Information.Visible)
					{
						if (Operators.CompareString(RemoteControl, "MAIN", TextCompare: false) == 0)
						{
							RemoteEditOnOff = "False";
						}
						MyProject.Forms.Information.Hide();
						ControlChange("SpeedProgram", "Visible", "True");
						MyProject.Forms.Information.ClearDayMonthYearDOBCollection();
						MyProject.Forms.Information.ClearDayMonthYearRefCollection();
						ControlChange("GradientProgram", "Visible", Interaction.GetSetting("DTread", "Aqua", "Incline", "False"));
						ProgramRemoteImage("EditDep1");
						ControlChange("ProgramStart", "Enabled", "True");
						if (!EmergencyStop)
						{
							StartProgramPic = "Estop1";
						}
						else if (ProgramHold)
						{
							StartProgramPic = "ReStartSW";
							UpdateVoiceImage();
						}
						else if (USBOPTORLY816.SandBoxOnOff)
						{
							StartProgramPic = "SandBox";
						}
						else
						{
							StartProgramPic = "StartSW";
							UpdateVoiceImage();
						}
						FinishEditTM.Interval = 500;
						FinishEditTM.Enabled = true;
						GetPersonInfo(NewProgram: false);
						MyProject.Forms.Information.PersonHealthCheck();
						RecordChanges();
						WelcomeText();
					}
					else
					{
						if (Operators.CompareString(RemoteControl, "MAIN", TextCompare: false) == 0)
						{
							RemoteEditOnOff = "True";
						}
						MyProject.Forms.Information.DOBYearCollection();
						MyProject.Forms.Information.RefYearCollection();
						MyProject.Forms.Information.Show();
						MyProject.Forms.Information.ControlChange("Person", "Text", TimeOfDayInd);
						ControlChange("SpeedProgram", "Visible", "False");
						ControlChange("GradientProgram", "Visible", "False");
						if (!EmergencyStop)
						{
							StartProgramPic = "Estop1";
						}
						else
						{
							ControlChange("ProgramStart", "Enabled", "False");
							StartProgramPic = "StartSWDe";
							UpdateVoiceImage();
						}
						ProgramRemoteImage("FinishEditdepSw");
						EditPressTM.Interval = 500;
						EditPressTM.Enabled = true;
						MyProject.Forms.Information.ControlAChange("Person", "PersonName", "Visible", "True");
						MyProject.Forms.Information.ControlAChange("Person", "PersonNameLabel", "Visible", "True");
					}
				}
				else if (ProgramHold)
				{
					ControlChange("PersonEdit", "Enabled", "False");
					if (Operators.CompareString(RemoteControl, "REMOTE", TextCompare: false) != 0)
					{
						GetPersonInfo(NewProgram: false);
					}
					RemoteGradientSelectG8(0);
					ResetProgram();
				}
				return;
			}
			if (Operators.CompareString(RemoteControl, "REMOTE", TextCompare: false) == 0)
			{
				Functions.RegUpdate("Dtread", "Treadmill", "SendC", Functions.RegUpdate("Dtread", "Treadmill", "SendC", "", "Get") + ",EDIT", "Save");
				if (Operators.CompareString(RemoteEditImage, "Edit1", TextCompare: false) == 0)
				{
					ProgramRemoteImage("EditDep1");
				}
				else if (Operators.CompareString(RemoteEditImage, "FinishEditSw", TextCompare: false) == 0)
				{
					ProgramRemoteImage("FinishEditdepSw");
				}
				else if (Operators.CompareString(RemoteEditImage, "ResetSw1", TextCompare: false) == 0)
				{
					ProgramRemoteImage("ResetDeSw1");
				}
			}
			EditSwTM.Enabled = true;
			ProgramRemoteImage("EditDep1");
		}
		else if (!NoChangesTM.Enabled)
		{
			NoChangesTM.Enabled = true;
		}
	}

	public void RecordChanges()
	{
		string drive = "C:";
		string path = "\\Users\\Public";
		string direct = "\\Open";
		if (Operators.CompareString(MachineSetup.Type, "Person", TextCompare: false) == 0)
		{
			direct = "\\OpenP";
		}
		UpdateCustomerList();
		if (CustomerListUpdateRequired)
		{
			if (MachineSetup.USBSave)
			{
				WritePersonInfoOfRam();
			}
			WritePersonInfoToDWS();
			WritePersonInfoToDWSList(drive, path, direct);
			path = "\\DWS-History";
			OneDrivePath = Functions.OneDriveCheck();
			if (Operators.CompareString(OneDrivePath, "Failed", TextCompare: false) != 0)
			{
				WritePersonInfoToDWSList(OneDrivePath, path, "");
			}
			GooglePath = Functions.GoogleDriveCheck();
			if (Operators.CompareString(GooglePath, "Failed", TextCompare: false) != 0)
			{
				WritePersonInfoToDWSList(GooglePath, path, "");
			}
			try
			{
				MyProject.Forms.NameListSort.NameLoad(NameArrayMax);
			}
			catch (Exception ex)
			{
				ProjectData.SetProjectError(ex);
				Exception ex2 = ex;
				ProjectData.ClearProjectError();
			}
		}
		CustomerListUpdateRequired = false;
	}

	private void GetPersonInfo(bool NewProgram)
	{
		string file = "\\Information.txt";
		string text = "\\CustomerData.txt";
		string text2 = "C:\\Users\\Public";
		string text3 = "\\Open";
		if (Operators.CompareString(MachineSetup.Type, "Person", TextCompare: false) == 0)
		{
			text3 = "\\OpenP";
		}
		OneDrivePath = Functions.OneDriveCheck();
		if (Operators.CompareString(RemoteControl, "REMOTE", TextCompare: false) != 0)
		{
			if (Operators.CompareString(OneDrivePath, "Failed", TextCompare: false) != 0)
			{
				if (Operators.CompareString(Functions.DirExist(OneDrivePath, "\\DWS-History\\DWS"), "Failed", TextCompare: false) != 0)
				{
					ReadInformationList(OneDrivePath + "\\DWS-History\\DWS", text, "False");
				}
				else
				{
					ReadInformationList(text2 + text3 + "\\DWS", text, "False");
				}
				ReadInformation(text2 + text3 + "\\DWS", file, NewProgram);
			}
			else if (Operators.CompareString(GooglePath, "Failed", TextCompare: false) != 0)
			{
				if (Operators.CompareString(Functions.DirExist(GooglePath, "\\DWS-History\\DWS"), "Failed", TextCompare: false) != 0)
				{
					ReadInformationList(GooglePath + "\\DWS-History\\DWS", text, "False");
				}
				else
				{
					ReadInformationList(text2 + text3 + "\\DWS", text, "False");
				}
				ReadInformation(text2 + text3 + "\\DWS", file, NewProgram);
			}
			else
			{
				ReadInformationList(text2 + text3 + "\\DWS", text, "False");
				ReadInformation(text2 + text3 + "\\DWS", file, NewProgram);
			}
		}
		else if (Operators.CompareString(RemoteControl, "REMOTE", TextCompare: false) == 0)
		{
			ReadInformationList(LanMapDrive, ":\\" + text3 + "\\DWS" + text, "False");
		}
	}

