	private void UpdateRunProgram()
	{
		string text = "0";
		string text2 = "0";
		checked
		{
			if (EmergencyStop)
			{
				if ((Operators.CompareString(StartProgramPicHold, "Estop1", TextCompare: false) == 0) | (Operators.CompareString(StartProgramPicHold, null, TextCompare: false) == 0))
				{
					if (!ProgramHold)
					{
						StartProgramPic = "StartSW";
					}
					else
					{
						StartProgramPic = "ReStartSW";
					}
				}
				UpdateVoiceImage();
				if ((ProgramRun & !EmergencyEmpty & !ProgramHold & (Conversion.Val(Speed_kmh.Text) > 0.0)) | (ProgramRun & !EmergencyEmpty & ProgramHold & (Conversion.Val(Speed_kmh.Text) > 0.0)) | (ProgramRun & !EmergencyEmpty & ProgramHold & (Conversion.Val(Speed_kmh.Text) == 0.0) & (ProgramMark > 0)))
				{
					if (DisplayCount == 0)
					{
						DisplayCount++;
					}
					SecondsInt++;
					if (SecondsInt >= 60)
					{
						SecondsInt = 0;
						MinutesInt++;
						if (MinutesInt > 60)
						{
							MinutesInt = 0;
						}
					}
					text2 = ((SecondsInt <= 9) ? ("0" + Conversions.ToString(SecondsInt)) : Conversions.ToString(SecondsInt));
					text = ((MinutesInt <= 9) ? ("0" + Conversions.ToString(MinutesInt)) : Conversions.ToString(MinutesInt));
					if ((DurationSec < HoldDurationTimeSeconds) & EmergencyStop)
					{
						DurationIndChange(text + ":" + text2);
						DurationSec++;
						DurationmsecCount = 0;
						if (Conversion.Val(Speed_kmh.Text) == 0.0)
						{
							SecondsRest++;
							if (SecondsRest >= 60)
							{
								SecondsRest = 0;
								MinutesRest++;
								if (MinutesRest > 60)
								{
									MinutesRest = 0;
								}
							}
							string text3 = ((SecondsRest <= 9) ? ("0" + Conversions.ToString(SecondsRest)) : Conversions.ToString(SecondsRest));
							string text4 = ((MinutesInt <= 9) ? ("0" + Conversions.ToString(MinutesRest)) : Conversions.ToString(MinutesRest));
							DurationRestChange(text4 + ":" + text3);
						}
					}
				}
				else if (ProgramRun & !EmergencyEmpty & (Conversion.Val(Speed_kmh.Text) == 0.0))
				{
					SecondsRest++;
					if (SecondsRest >= 60)
					{
						SecondsRest = 0;
						MinutesRest++;
						if (MinutesRest > 60)
						{
							MinutesRest = 0;
						}
					}
					string text3 = ((SecondsRest <= 9) ? ("0" + Conversions.ToString(SecondsRest)) : Conversions.ToString(SecondsRest));
					string text4 = ((MinutesInt <= 9) ? ("0" + Conversions.ToString(MinutesRest)) : Conversions.ToString(MinutesRest));
					DurationRestChange(text4 + ":" + text3);
				}
				if (Operators.CompareString(StartProgramPicDe, "", TextCompare: false) > 0)
				{
					StartProgramPic = StartProgramPicDe;
					StartProgramPicDe = "";
				}
				if (EmergencyEmpty & ProgramRun)
				{
					UpdateDisplay();
					ResetProgram();
				}
				if (Operators.CompareString(RemoteControl, "REMOTE", TextCompare: false) != 0)
				{
					UpdateSpeedAndDistance();
				}
			}
			else
			{
				AllOff();
			}
			if ((object)StartProgramPicHold != StartProgramPic)
			{
				UpdateVoiceImage();
			}
		}
	}

	private void UpdateDisplay()
	{
		checked
		{
			if (DurationSec <= HoldDurationTimeSeconds)
			{
				if (DurationSec == HoldDurationTimeSeconds)
				{
					DurationSec++;
				}
				if (IndexProgram1 >= 60 || !((EmergencyStop & !ProgramHold) | (EmergencyStop & ProgramRun & (Conversion.Val(Speed_kmh.Text) > 0.0)) | (ProgramMark > 0)))
				{
					return;
				}
				IndexProgram1++;
				int num = 121 - IndexProgram1;
				if (IOPOTCommsActive | TestEStop)
				{
					IOPOT.UpdateSpeed(IndexProgram1 + 1, ProgramHold, ProgramReset);
					ButtonColourChange("SpeedProgram", "Button" + Conversions.ToString(IndexProgram1), "Coral");
					if (MachineSetup.InclineDisplayOnOff & !ProgramHold)
					{
						IOPOT.UpdateGradient(IndexProgram1 + 1, ProgramHold, ProgramReset);
						ButtonColourChange("GradientProgram", "Button" + Conversions.ToString(num), "Coral");
					}
				}
				Thread.Sleep(5);
				Functions.RegUpdate("Dtread", "Treadmill", "SendB", WriteDisplayButtons(), "Save");
				HistoryProgramIndex = IndexProgram1;
				HistoryProgramSpeed[IndexProgram1] = Speed_kmh.Text;
				if (MachineSetup.InclineDisplayOnOff)
				{
					HistoryProgramGradient[IndexProgram1] = InclineActual.Text;
				}
				HistoryProgramWater[IndexProgram1] = WaterDepthActual.Text;
				HistoryProgramTemperature[IndexProgram1] = ChamberTemp.Text;
				HistoryProgramTime[IndexProgram1] = SecondsToText(ProgramRunIntervals[IndexProgram1]);
				HistoryProgramRestTime[IndexProgram1] = DurationRest.Text;
				HistoryProgramDistance[IndexProgram1] = Distance_km.Text;
				HistoryProgramCalorieDry[IndexProgram1] = Calorie_Dry.Text;
				HistoryProgramCalorieWet[IndexProgram1] = Calorie_Wet.Text;
				if (ProgramHold & (Conversion.Val(Speed_kmh.Text) > 0.0))
				{
					ProgramRunning = true;
					HistoryProgramRest[IndexProgram1] = "0";
					if (!MachineSetup.JetDisplayOnOff)
					{
						HistoryProgramJet[IndexProgram1] = "0";
					}
					else if (!JetOn)
					{
						HistoryProgramJet[IndexProgram1] = "0";
					}
					else
					{
						HistoryProgramJet[IndexProgram1] = "6";
					}
				}
				else
				{
					if (ProgramRunning & ProgramHold)
					{
						HistoryProgramRest[IndexProgram1] = "5";
					}
					else
					{
						HistoryProgramRest[IndexProgram1] = "0";
					}
					HistoryProgramJet[IndexProgram1] = "0";
				}
			}
			else
			{
				if (IndexProgram1 <= 0)
				{
					return;
				}
				if (IndexProgram1 < 60)
				{
					int num2 = 59 - IndexProgram1;
					for (int i = 0; i <= num2; i++)
					{
						IndexProgram1++;
						HistoryProgramIndex = IndexProgram1;
						HistoryProgramSpeed[IndexProgram1] = Speed_kmh.Text;
						if (MachineSetup.InclineDisplayOnOff)
						{
							HistoryProgramGradient[IndexProgram1] = InclineActual.Text;
						}
						HistoryProgramWater[IndexProgram1] = WaterDepthActual.Text;
						HistoryProgramTemperature[IndexProgram1] = ChamberTemp.Text;
						HistoryProgramTime[IndexProgram1] = SecondsToText(ProgramRunIntervals[IndexProgram1]);
						HistoryProgramRestTime[IndexProgram1] = DurationRest.Text;
						HistoryProgramDistance[IndexProgram1] = Distance_km.Text;
						HistoryProgramCalorieDry[IndexProgram1] = Calorie_Dry.Text;
						HistoryProgramCalorieWet[IndexProgram1] = Calorie_Wet.Text;
						if (ProgramHold & (Conversion.Val(Speed_kmh.Text) > 0.0))
						{
							ProgramRunning = true;
							HistoryProgramRest[IndexProgram1] = "0";
							if (!MachineSetup.JetDisplayOnOff)
							{
								HistoryProgramJet[IndexProgram1] = "0";
							}
							else if (!JetOn)
							{
								HistoryProgramJet[IndexProgram1] = "0";
							}
							else
							{
								HistoryProgramJet[IndexProgram1] = "6";
							}
						}
						else
						{
							if (ProgramRunning & ProgramHold)
							{
								HistoryProgramRest[IndexProgram1] = "5";
							}
							else
							{
								HistoryProgramRest[IndexProgram1] = "0";
							}
							HistoryProgramJet[IndexProgram1] = "0";
						}
					}
				}
				ResetProgram();
			}
		}
	}

	private void UpdateSpeedAndDistance()
	{
		if (IOPOTCommsActive | TestEStop)
		{
			if (TestEStop & !IOPOTCommsActive)
			{
				Speed_kmhChange(Functions.NumberToString((float)Math.Round(Conversion.Val(IOPOT.SpeedIndkmh), Decp), Decp));
			}
			else
			{
				Speed_kmhChange(Functions.NumberToString((float)Math.Round(Conversion.Val(IOPOT.SpeedIndkmh), Decp), Decp));
			}
		}
		else if (ControlLevel == 0)
		{
			Speed_kmhChange(DecpV);
		}
		if (IOPOTCommsActive | TestEStop)
		{
			if (Operators.CompareString(mphLabel.Text, "mph", TextCompare: false) == 0)
			{
				Speed_mphChange(Functions.NumberToString((float)Math.Round(Conversion.Val(IOPOT.SpeedIndmph), Decp), Decp));
			}
			else if (Operators.CompareString(mphLabel.Text, "M/m", TextCompare: false) == 0)
			{
				Speed_mphChange(Functions.NumberToString((float)Math.Round(Conversion.Val(IOPOT.SpeedIndkmph * 1000.0 / 60.0), Decp2), Decp2));
			}
			else if (Operators.CompareString(mphLabel.Text, "M/s", TextCompare: false) == 0)
			{
				Speed_mphChange(Functions.NumberToString((float)Math.Round(Conversion.Val(IOPOT.SpeedIndkmph * 1000.0 / 60.0 / 60.0), Decp2), Decp2));
			}
		}
		else if (Operators.CompareString(mphLabel.Text, "mph", TextCompare: false) == 0)
		{
			Speed_mphChange(DecpV);
		}
		else if (Operators.CompareString(mphLabel.Text, "M/m", TextCompare: false) == 0)
		{
			Speed_mphChange(DecpV);
		}
		else
		{
			Speed_mphChange(DecpV2);
		}
		if (IOPOTCommsActive | TestEStop)
		{
			Distance_kmChange(Functions.NumberToString((float)Math.Round(Conversion.Val(IOPOT.Distancekm), 3), 3));
		}
		else
		{
			Distance_kmChange("0.000");
		}
		if (IOPOTCommsActive | TestEStop)
		{
			if (Operators.CompareString(mphLabel.Text, "mph", TextCompare: false) == 0)
			{
				Distance_miChange(Functions.NumberToString((float)Math.Round(Conversion.Val(IOPOT.Distancemi), 3), 3));
			}
			else
			{
				Distance_miChange(Functions.NumberToString((float)Math.Round(Conversion.Val(IOPOT.Distancekm * 1000.0), Decp), Decp));
			}
		}
		else if (Operators.CompareString(mphLabel.Text, "mph", TextCompare: false) == 0)
		{
			Distance_miChange("0.000");
		}
		ControlAChange("CalorieIndDry", "Calorie_Dry", "Text", Functions.NumberToString((float)Math.Round(CalorieDry, 2), 2));
		ControlAChange("CalorieIndWet", "Calorie_Wet", "Text", Functions.NumberToString((float)Math.Round(CalorieWet, 2), 2));
		if (Operators.CompareString(RemoteControl, "MAIN", TextCompare: false) == 0)
		{
			Functions.RegUpdate("Dtread", "Treadmill", "SendD", WriteDisplayPara(), "Save");
		}
	}

