	private void WordPassOff_Click(object sender, EventArgs e)
	{
		WordPass = false;
		ResetWordPassTMOff();
		ControlChange("WordPassOff", "Visible", "False");
	}

	public void ResetProgramIndicatorTMSet()
	{
		ResetProgramIndicatorTM = new System.Threading.Timer(ResetProgramIndicatorTM_Tick, null, -1, -1);
	}

	public void ResetProgramIndicatorTMOff()
	{
		ResetProgramIndicatorTM.Change(-1, -1);
	}

	public void ResetProgramIndicatorTMon()
	{
		ResetProgramIndicatorTM.Change(100, 100);
	}

	private void ResetProgramIndicatorTM_Tick(object sender)
	{
		ProgramReset = true;
		ProgramRun = false;
		MotorRun = false;
		DisplayCount = 0;
		checked
		{
			IndexProgramReset1++;
			int num = IndexProgramReset1 + 60;
			if (IndexProgramReset1 < 61)
			{
				if ((SpeedProgram.Controls["Button" + Conversions.ToString(IndexProgramReset1)].BackColor == Color.Coral) | (GradientProgram.Controls["Button" + Conversions.ToString(num)].BackColor == Color.Coral))
				{
					ButtonColourChange("SpeedProgram", "Button" + Conversions.ToString(IndexProgramReset1), "Control");
					ButtonColourChange("GradientProgram", "Button" + Conversions.ToString(num), "Control");
				}
				else
				{
					ButtonColourChange("SpeedProgram", "Button" + Conversions.ToString(IndexProgramReset1), "Coral");
					ButtonColourChange("GradientProgram", "Button" + Conversions.ToString(num), "Coral");
					IndexProgramReset1--;
				}
				Functions.RegUpdate("Dtread", "Treadmill", "SendB", WriteDisplayButtons(), "Save");
			}
			else
			{
				if (!((MachineSetup.InclineDisplayOnOff & !Actuator & IOPOTCommsActive & !Conveyor & !EmergencyEmpty & !CleanOn) | (MachineSetup.InclineDisplayOnOff & !Actuator & IOPOTCommsActive & !Conveyor & !WDOnOff & EmergencyEmpty) | (MachineSetup.InclineDisplayOnOff & !Actuator & IOPOTCommsActive & !Conveyor & !TreadmillFloatSw & CleanOn) | (!MachineSetup.InclineDisplayOnOff & !Conveyor & IOPOTCommsActive & !EmergencyEmpty & !CleanOn) | (!MachineSetup.InclineDisplayOnOff & !Conveyor & IOPOTCommsActive & !WDOnOff & EmergencyEmpty) | (!MachineSetup.InclineDisplayOnOff & !Conveyor & IOPOTCommsActive & !TreadmillFloatSw & CleanOn) | (!Actuator & !Conveyor & !EmergencyStop) | (TestEStop & !MachineSetup.InclineDisplayOnOff & !Conveyor & !WDOnOff) | (TestEStop & MachineSetup.InclineDisplayOnOff & !Actuator & !Conveyor & !WDOnOff)))
				{
					return;
				}
				if (!CleanOn)
				{
					if ((Operators.CompareString(MyProject.Forms.Information.PersonName.Text, "", TextCompare: false) > 0) & (Operators.CompareString(MyProject.Forms.Information.ID.Text, "", TextCompare: false) > 0))
					{
						string drive = "C:";
						string path = "\\Users\\Public";
						string direct = "\\Open";
						if (Operators.CompareString(MachineSetup.Type, "Person", TextCompare: false) == 0)
						{
							direct = "\\OpenP";
						}
						WritePersonHistory(drive, path, direct);
						WritePersonInfoToDWS();
						if (MachineSetup.USBSave)
						{
							WritePersonInfoOfRam();
						}
					}
				}
				else
				{
					if (CleanWorkIndex == 4)
					{
						CleanWorkChange(Done);
					}
					CleaningOff();
					CloseVersion.SetValue("WPCDT", Conversions.ToString(CloseVersion.GetValue("WPCDT", "0")) + "," + DateTimeRecord);
					CloseVersion.SetValue("WPC", Conversions.ToString(Conversions.ToInteger(CloseVersion.GetValue("WPC", "0")) + 1));
					CloseVersion.SetValue("DPCDT", Conversions.ToString(CloseVersion.GetValue("DPCDT", "0")) + "," + DateTimeRecord);
					CloseVersion.SetValue("DPC", Conversions.ToString(Conversions.ToInteger(CloseVersion.GetValue("DPC", "0")) + 1));
				}
				HistoryProgramIndex = 0;
				ResetShortTimerControl();
				ResetProgramIndicatorTMOff();
				ControlChange("PersonEdit", "Enabled", "True");
				IndexProgramReset1 = 0;
				if (EmergencyStop)
				{
					StartProgramPic = "StartSW";
					UpdateVoiceImage();
				}
				ControlChange("ProgramStart", "Enabled", "True");
				SSLLabelChange(Selecttxt);
				GSLLabelChange(Selecttxt);
				ProgramHold = false;
				ProgramRemoteImage("Edit1");
				RemoteEditImage = "Edit1";
				DurationInt = 0.0;
				DurationSec = 0;
				SecondsInt = 0;
				MinutesInt = 0;
				SecondsRest = 0;
				MinutesRest = 0;
				IndexProgram1 = 0;
				DurationTimeSet(DurationTime);
				FlashIndicator = false;
				ProgramReset = false;
				if (!USBOPTORLY816.SandBoxOnOff)
				{
					RLY816.CleanCirculationOn();
				}
				ControlAChange("Clean", "CleanOnOff", "Enabled", "True");
				CleanOnOffTM.Interval = 800;
				CleanOnOffTM.Enabled = true;
				if (EmergencyEmpty)
				{
					EmergencyEmpty = false;
					ControlAChange("WaterDepth", "WaterDepthInd", "Text", "0");
					Interaction.SaveSetting("Health", "Person", "WaterDepthInd", "0");
					Interaction.SaveSetting("Health", "Person", "WaterDepthHold", "0");
				}
			}
		}
	}

