					ControlChange("WordPassOff", "Visible", "True");
					ResetWordPassTMon();
				}
				else
				{
					WordPass = false;
					ControlChange("WordPassOff", "Visible", "False");
				}
				break;
			case "WaterDepth":
				DoBoxChange("RemoteWaterDepthSetting");
				CustomerListUpdateRequired = true;
				break;
			case "Speedkmh":
				DoBoxChange("RemoteSpeedkmh");
				CustomerListUpdateRequired = true;
				Speed_kmh.TextAlign = ContentAlignment.MiddleCenter;
				break;
			case "SpeedMetersPerMin":
				DoBoxChange("RemoteSpeedMetersPerMin");
				CustomerListUpdateRequired = true;
				Speed_mph.TextAlign = ContentAlignment.MiddleCenter;
				break;
			case "ShortTimerStop":
				DoBoxChange("TimerBoxCycleControl");
				ShortTimerStop.TextAlign = ContentAlignment.MiddleCenter;
				Interaction.SaveSetting("DTread", "Display", "ShortTimerStop", ShortTimerStop.Text);
				break;
			case "ShortTimerStart":
				DoBoxChange("TimerBoxCycleControl");
				ShortTimerStart.TextAlign = ContentAlignment.MiddleCenter;
				Interaction.SaveSetting("DTread", "Display", "ShortTimerStart", ShortTimerStart.Text);
				break;
			case "ShortTimerStopStartCycles":
				DoBoxChange("TimerBoxCycleControl");
				ShortTimerStopStartCyclesSet.TextAlign = ContentAlignment.MiddleCenter;
				Interaction.SaveSetting("DTread", "Display", "ShortTimerStopStartCycles", ShortTimerStopStartCyclesSet.Text);
				break;
			}
			MyProject.Forms.InfoEnter.Preload = "";
			InfoEnter.PasswordSet = "";
			InfoEnterTM.Dispose();
			ControlLevel = 0;
			SerialDone = false;
		}
	}

