	private void TimerBoxCycleControl()
	{
		if (!(ShortTimerStopStartCyclesSet.Visible & ((object)ShortTimerStopStartCyclesSet.Text != "0") & !ProgramRun))
		{
			return;
		}
		int num = Conversions.ToInteger(ShortTimerStopStartCyclesSet.Text);
		int num2 = Conversions.ToInteger(ShortTimerStop.Text);
		int num3 = Conversions.ToInteger(ShortTimerStart.Text);
		checked
		{
			int num4 = num * (num2 + num3);
			if (num4 > 59)
			{
				int num5 = (int)Math.Ceiling((double)num4 / 60.0);
				if (num5 * 60 > num4)
				{
					num5--;
				}
				int num6 = num4 - num5 * 60;
				DurationTime = num5 + ":" + num6;
			}
			else
			{
				DurationTime = "0" + num4;
			}
			DurationTimeSet(DurationTime);
		}
	}

