	public void DurationTimeSet(string Duration)
	{
		string text = "0";
		string text2 = "0";
		Array array = Strings.Split(Duration, ":");
		int num = 0;
		int num2 = 0;
		checked
		{
			if (Microsoft.VisualBasic.Information.UBound(array) >= 1)
			{
				int num3 = Microsoft.VisualBasic.Information.UBound(array);
				for (int i = 1; i <= num3; i++)
				{
					text = Conversions.ToString(num2) ?? "";
					num2 += Conversions.ToInteger(array.GetValue(i));
					text2 = Conversions.ToString(array.GetValue(0));
					text = num2.ToString();
				}
			}
			else if (Strings.Len(Duration) > 2)
			{
				text = Strings.Mid(Duration, Strings.Len(Duration) - 1, 2);
				text2 = Strings.Mid(Duration, 1, Strings.Len(Duration) - 2);
			}
			else
			{
				text = "0";
				text2 = Duration;
			}
			if (((Conversion.Val(text) <= 0.0) & (Conversion.Val(text2) <= 0.0)) | (Conversion.Val(text2) > 40.0) | ProgramRun | ((Conversion.Val(text2) == 0.0) & (Conversion.Val(text) < 20.0)))
			{
				text = HoldDurationTimeSec;
				text2 = HoldDurationTimeMin;
			}
			if (Strings.Len(text) < 2)
			{
				text = "0" + text;
			}
			if (Operators.CompareString(RemoteControl, "REMOTE", TextCompare: false) == 0)
			{
				Functions.RegUpdate("Dtread", "Treadmill", "SendC", Functions.RegUpdate("Dtread", "Treadmill", "SendC", "", "Get") + ",RDTS" + Duration, "Save");
			}
			else
			{
				SetProgramRunIntervalTM(text2, text);
				Interaction.SaveSetting("Health", "Person", "Duration", SetDuration.Text);
			}
			DurationTime = Duration;
		}
	}

	private void LOGO(bool Change)
