			{
				ControlChange("CompanyLogo", "Tag", "AquaInspire");
			}
			else if (CompanyLogo.Tag == "AquaInspire")
			{
				ControlChange("CompanyLogo", "Tag", "JMFMicro");
			}
			else
			{
				ControlChange("CompanyLogo", "Tag", "JMFMicro");
			}
			Interaction.SaveSetting("Machine", "Company", "LOGO", Conversions.ToString(CompanyLogo.Tag));
		}
		switch (Conversions.ToString(CompanyLogo.Tag))
