	public string SavedProgram()
	{
		string text = "";
		string text2 = "";
		string text3 = "";
		OneDrivePath = Functions.OneDriveCheck();
		checked
		{
			if (Operators.CompareString(OneDrivePath, "Failed", TextCompare: false) != 0 && Operators.CompareString(Functions.DirCreate(OneDrivePath, "\\Program"), "Failed", TextCompare: false) != 0 && Operators.CompareString(Functions.DirCreate(OneDrivePath, "\\Program\\" + MyProject.Forms.Information.ID.Text), "Failed", TextCompare: false) != 0)
			{
				text = OneDrivePath + "\\Program\\" + MyProject.Forms.Information.ID.Text + "\\Program.txt";
				try
				{
					StreamReader streamReader = new StreamReader(text);
					string text4;
					do
					{
						text4 = streamReader.ReadLine();
						text2 += text4;
					}
					while (text4 != null);
					streamReader.Close();
					Array array = Strings.Split(text2, ",");
					int num = Microsoft.VisualBasic.Information.UBound(array) - 2;
					for (int i = 0; i <= num; i++)
					{
						text3 = text3 + Math.Round((double)Conversions.ToInteger(array.GetValue(i)) / 100.0 * 64.0, 0) + ",";
					}
					DurationTime = Conversions.ToString(array.GetValue(Microsoft.VisualBasic.Information.UBound(array) - 2));
					SpeedMax = Conversions.ToInteger(array.GetValue(Microsoft.VisualBasic.Information.UBound(array) - 1));
				}
				catch (Exception ex)
				{
					ProjectData.SetProjectError(ex);
					Exception ex2 = ex;
					ProjectData.ClearProjectError();
				}
			}
			return text3;
		}
	}

	private void SpeedProgramManual()
	{
		if (!NoChanges)
		{
			DisplayOn = true;
			if (Operators.CompareString(RemoteControl, "REMOTE", TextCompare: false) != 0)
			{
				if (!ProgramRun & !CleanOn)
				{
					SpeedProgramSet = 0;
					NewSpeed(SpeedProgramSet, NewProgram: true);
					ZeroIndicators();
				}
			}
			else
			{
				ImageControlAChange("SpeedProgram", "SpeedSelect", "SpeedProgramUp", "SpeedProgram", "ArrowUpDe");
				ResetButtonsTMon();
				if (Operators.CompareString(RemoteControl, "REMOTE", TextCompare: false) == 0)
				{
					Functions.RegUpdate("Dtread", "Treadmill", "SendC", Functions.RegUpdate("Dtread", "Treadmill", "SendC", "", "Get") + ",SPU", "Save");
				}
			}
			Functions.RegUpdate("Dtread", "Treadmill", "SendB", WriteDisplayButtons(), "Save");
		}
		else if (!NoChangesTM.Enabled)
		{
			NoChangesTM.Enabled = true;
		}
	}

	private void SpeedProgramUp_Control()
	{
		checked
		{
			if (!NoChanges & (ControlLevel == 0))
			{
				DisplayOn = true;
				if (Operators.CompareString(RemoteControl, "REMOTE", TextCompare: false) != 0)
				{
					if (!ProgramRun & !CleanOn)
					{
						ImageControlAChange("SpeedProgram", "SpeedSelect", "SpeedProgramUp", "SpeedProgram", "ArrowUpDe");
						ResetButtonsTMon();
						SpeedProgramSet++;
						if (SpeedProgramSet > MaxSpeedProgramSet)
						{
							if (Operators.CompareString(SavedProgram(), "", TextCompare: false) == 0)
							{
								SpeedProgramSet = 0;
							}
							else if (SpeedProgramSet > MaxSpeedProgramSet + 1)
							{
								SpeedProgramSet = 0;
							}
						}
						NewSpeed(SpeedProgramSet, NewProgram: true);
						ZeroIndicators();
					}
					else if (ProgramRun & !CleanOn & (ProgramNumSpeed == 0))
					{
						ImageControlAChange("SpeedProgram", "SpeedSelect", "SpeedProgramUp", "SpeedProgram", "ArrowUpDe");
						ResetButtonsTMon();
						if (IOPOTCommsActive | TestEStop)
						{
							Display_Speed = Conversions.ToInteger(Interaction.GetSetting("Treadmill", "Speed", Conversions.ToString(IndexProgram1 + 1), "0"));
							if (Display_Speed < DisplayLevels)
							{
								Display_Speed++;
							}
							int num = IndexProgram1 + 1;
							for (int i = num; i <= 60; i++)
							{
								Interaction.SaveSetting("Treadmill", "Speed", Conversions.ToString(i), Conversions.ToString(Display_Speed));
							}
							SpeedSelectG8ColourCheck(Display_Speed);
							NewSpeed(SpeedProgramSet, NewProgram: false);
							IOPOT.UpdateSpeed(IndexProgram1 + 1, ProgramHold, ProgramReset);
						}
					}
				}
				else
				{
					ImageControlAChange("SpeedProgram", "SpeedSelect", "SpeedProgramUp", "SpeedProgram", "ArrowUpDe");
					ResetButtonsTMon();
					if (Operators.CompareString(RemoteControl, "REMOTE", TextCompare: false) == 0)
					{
						Functions.RegUpdate("Dtread", "Treadmill", "SendC", Functions.RegUpdate("Dtread", "Treadmill", "SendC", "", "Get") + ",SPU", "Save");
					}
				}
				Functions.RegUpdate("Dtread", "Treadmill", "SendB", WriteDisplayButtons(), "Save");
			}
			else if (!NoChangesTM.Enabled)
			{
				NoChangesTM.Enabled = true;
			}
		}
	}

