	public string ControlReturn(string ControlAPosition, string ControlPosition, string ControlName, string Setting)
	{
		if (base.Controls[ControlAPosition].Controls[ControlPosition].Controls[ControlName].InvokeRequired)
		{
			SetControl3Callback method = [SpecialName] [DebuggerHidden] (string a0, string a1, string a2, string a3) =>
			{
				ControlReturn(a0, a1, a2, a3);
			};
			Invoke(method, ControlAPosition, ControlPosition, ControlName, Setting);
		}
		else if (Operators.CompareString(Setting, "Visible", TextCompare: false) == 0)
		{
			if (base.Controls[ControlAPosition].Controls[ControlPosition].Controls[ControlName].Visible)
			{
				return base.Controls[ControlAPosition].Controls[ControlPosition].Controls[ControlName].Text;
			}
		}
		else if (Operators.CompareString(Setting, "Data", TextCompare: false) == 0)
		{
			return base.Controls[ControlAPosition].Controls[ControlPosition].Controls[ControlName].Text;
		}
		string result = default(string);
		return result;
	}

	public void GradientProgramDN_Control()
	{
		checked
		{
			if (!NoChanges & !LevelZero)
			{
				DisplayOn = true;
				if (Operators.CompareString(RemoteControl, "REMOTE", TextCompare: false) != 0)
				{
					if (!ProgramRun & !CleanOn)
					{
						ImageControlAChange("GradientProgram", "GradientSelect", "GradientProgramDown", "GradientProgram", "ArrowDnDe");
						ResetButtonsTMon();
						GradientProgramSet--;
						if ((GradientProgramSet < 0) | (GradientProgramSet > MaxGradientProgramSet))
						{
							GradientProgramSet = MaxGradientProgramSet;
						}
						NewGradient(GradientProgramSet, NewProgram: true);
					}
					else if (ProgramRun & !CleanOn & (ProgramNumGradient == 0))
					{
						ImageControlAChange("GradientProgram", "GradientSelect", "GradientProgramDown", "GradientProgram", "ArrowDnDe");
						ResetButtonsTMon();
						Display_Incline = Conversions.ToInteger(Interaction.GetSetting("Treadmill", "GradientPlus", Conversions.ToString(IndexProgram1 + 1), "0"));
						if (IOPOTCommsActive | TestEStop)
						{
							if (((double)Display_Incline < MaxInclineDeg * 10.0) | (Jump == 1))
							{
								if (Display_Incline - Jump >= 0)
								{
									Display_Incline -= Jump;
								}
								else
								{
									Display_Incline = 0;
								}
							}
							else
							{
								int num = 10;
								do
								{
									float num2 = Conversions.ToSingle(ControlReturn("GradientProgram", "GradientSelectG8", "GradientSelect" + Conversions.ToString(num), "Visible")) * 10f;
									if (num2 > 0f)
									{
										if ((double)(num2 - (float)Jump) > Conversion.Val(ControlReturn("GradientProgram", "GradientSelectG8", "GradientSelect" + Conversions.ToString(num - 1), "Data")) * 10.0)
										{
											Display_Incline = Conversions.ToInteger(ControlReturn("GradientProgram", "GradientSelectG8", "GradientSelect" + Conversions.ToString(num - 1), "Data")) * 10 + Jump;
										}
										else
										{
											Display_Incline = Conversions.ToInteger(ControlReturn("GradientProgram", "GradientSelectG8", "GradientSelect" + Conversions.ToString(num - 1), "Data")) * 10;
										}
										break;
									}
									num += -1;
								}
								while (num >= 2);
							}
							int num3 = IndexProgram1 + 1;
							for (int i = num3; i <= 60; i++)
							{
								Interaction.SaveSetting("Treadmill", "GradientPlus", i.ToString(), Conversions.ToString(Display_Incline));
							}
							GradientSelectG8ColourCheck(Display_Incline);
							NewGradient(GradientProgramSet, NewProgram: false);
							IOPOT.UpdateGradient(IndexProgram1 + 1, ProgramHold, ProgramReset);
						}
					}
				}
				else
				{
					ImageControlAChange("GradientProgram", "GradientSelect", "GradientProgramDown", "GradientProgram", "ArrowDnDe");
					ResetButtonsTMon();
					if (Operators.CompareString(RemoteControl, "REMOTE", TextCompare: false) == 0)
					{
						Functions.RegUpdate("Dtread", "Treadmill", "SendC", Functions.RegUpdate("Dtread", "Treadmill", "SendC", "", "Get") + ",GPD", "Save");
					}
				}
				Functions.RegUpdate("Dtread", "Treadmill", "SendB", WriteDisplayButtons(), "Save");
			}
			else if (!NoChangesTM.Enabled)
			{
				NoChangesTM.Enabled = true;
			}
		}
	}

