			else if (ProgramNumSpeed == 0)
			{
				MaxSpeedSet = 16f;
				MinMaxSpeedSet = MaxSpeedSet;
			}
			string[] array = Strings.Split(text, ",");
			TitleSpeedProgram(Item);
			ProgramMaxSpeed = DisplayLevels;
			SpeedBaseHeight = (float)Math.Round(ResMultiH * (float)num, 0);
			SpeedMaxHeightCal = (float)Math.Round(ResMultiH * (float)num2, 0);
			SpeedNewAdjust = SpeedProgram.Height - (int)Math.Round(SpeedBaseHeight);
