			{
				int num4 = ((Item < 1) ? (Conversions.ToInteger(array[num3 - 1]) * 100) : ((int)Math.Round((float)(Conversions.ToInteger(array[num3 - 1]) * 100) * DisplayRangeAdjust)));
				num4 = (int)Math.Round((double)num4 / 16.0) * (int)Math.Round(MaxSpeedSet);
				int num5 = (unchecked(num4 < 100 && num4 > 0) ? 1 : ((num4 > 0) ? ((int)Math.Round((double)num4 / 100.0)) : 0));
				Interaction.SaveSetting("Treadmill", "Speed", num3.ToString(), num5.ToString());
				if (num6 < num5)
				{
					num6 = num5;
				}
