	private void TitleSpeedProgram(int Item)
	{
		if (CleanOn && Item == 20)
		{
			SpeedTitleLChange("");
			SpeedTitleRChange("");
			ProgramRemoteImage("CleaningSpeed");
			SpeedSelectG8VisibleChange("False");
		}
		else if (Item == 0)
		{
			if (MachineSetup.ReverseOnOff)
			{
				if (!SpeedProgramReverse)
				{
					ProgramRemoteImage("Forward");
					SpeedTitleLChange("");
					SpeedTitleRChange("");
				}
				else
				{
					ProgramRemoteImage("Reverse");
					SpeedTitleLChange("");
					SpeedTitleRChange("");
				}
			}
			else
			{
				ProgramRemoteImage("Forward");
			}
			SpeedSelectG8VisibleChange("True");
		}
		else if (Item > MaxSpeedProgramSet)
		{
			SpeedTitleLChange("P");
			SpeedTitleRChange("P");
			ProgramRemoteImage("Forward");
			SpeedSelectG8VisibleChange("False");
			SpeedProgramReverse = false;
		}
		else
		{
			ProgramRemoteImage("Forward");
			SpeedTitleLChange(Item.ToString());
			SpeedTitleRChange(Item.ToString());
			SpeedSelectG8VisibleChange("False");
			SpeedProgramReverse = false;
		}
	}

