	public void InclineAngle(string Type)
	{
		if (Operators.CompareString(Interaction.GetSetting("DTread", "Aqua", "Incline", "False"), "False", TextCompare: false) == 0)
		{
			MaxRise = 0.0;
		}
		else
		{
			MaxRise = Conversions.ToDouble(Interaction.GetSetting("DTread", "Aqua", "BedMaxHeight", "210"));
		}
		BedLength = Conversions.ToDouble(Interaction.GetSetting("DTread", "Aqua", "Bedlength", "1915"));
		switch (Type)
		{
		case "L":
		case "H":
		case "N":
		{
			double num = Math.Sqrt(BedLength * BedLength - MaxRise * MaxRise);
			IOPOT.MaxGradient = Math.Round(MaxRise / num * 100.0 / 16.0 * 15.0, 0);
			InclinePercentageChange(Functions.NumberToString((float)Math.Round(MaxRise / num * 100.0 / 16.0 * (double)MaxGradientSet, Decp), Decp));
			double num2 = Math.Atan(MaxRise / num);
			MaxInclineDeg = Math.Round(num2 * 180.0 / Math.PI * 10.0, 0) / 10.0;
			Interaction.SaveSetting("Treadmill", "GradientPlus", "MaxInclineDeg", MaxInclineDeg.ToString());
			InclineDegChange(Functions.NumberToString(Conversions.ToSingle(Math.Round(MaxInclineDeg / 16.0 * (double)MaxGradientSet, 1).ToString()), 1));
			InclineMax = Functions.NumberToString((float)Math.Round(MaxRise / num * 100.0 / 16.0 * 16.0, Decp), Decp);
			ICLabelChange(MaxInclinetxt + " " + InclineMax + " %");
			break;
		}
		case "A":
		{
			MaxInclineDeg = Conversions.ToDouble(Interaction.GetSetting("Treadmill", "GradientPlus", "MaxInclineDeg", "5"));
			double a = MaxInclineDeg * (Math.PI / 180.0);
			MaxRise = Math.Round(Math.Sin(a) * BedLength, 0);
			Interaction.SaveSetting("DTread", "Aqua", "BedMaxHeight", MaxRise.ToString());
			break;
		}
		}
	}

