	private void FlashTM_Tick(object sender, EventArgs e)
	{
		checked
		{
			int num = IndexProgram1 + 1;
			if ((num <= 60) & ProgramRun)
			{
				int num2 = 121 - num;
				if ((SpeedProgram.Controls["Button" + Conversions.ToString(num)].BackColor == Color.Yellow) | (SpeedProgram.Controls["Button" + Conversions.ToString(num)].BackColor == Color.Red))
				{
					ButtonColourChange("SpeedProgram", "Button" + Conversions.ToString(num), "Coral");
					ButtonColourChange("GradientProgram", "Button" + Conversions.ToString(num2), "Coral");
				}
				else
				{
					if (!ProgramHold)
					{
						ButtonColourChange("SpeedProgram", "Button" + Conversions.ToString(num), "Yellow");
					}
					else
					{
						ButtonColourChange("SpeedProgram", "Button" + Conversions.ToString(num), "Red");
					}
					if (IOPOTCommsActive)
					{
						GetInclinePositionOK();
						if (!InclinePositionOK)
						{
							ButtonColourChange("GradientProgram", "Button" + Conversions.ToString(num2), "Yellow");
						}
					}
				}
				Functions.RegUpdate("Dtread", "Treadmill", "SendB", WriteDisplayButtons(), "Save");
			}
			else
			{
				FlashTM.Dispose();
			}
		}
	}

