	private void ButtonColourChange(string ControlContainer, string ControlName, string SetColor)
	{
		try
		{
			if (base.Controls[ControlContainer].Controls[ControlName].InvokeRequired)
			{
				SetControl2Callback method = ButtonColourChange;
				Invoke(method, ControlContainer, ControlName, SetColor);
				return;
			}
			switch (SetColor)
			{
			case "Yellow":
				base.Controls[ControlContainer].Controls[ControlName].BackColor = Color.Yellow;
				break;
			case "Red":
				base.Controls[ControlContainer].Controls[ControlName].BackColor = Color.Red;
				break;
			case "Coral":
				base.Controls[ControlContainer].Controls[ControlName].BackColor = Color.Coral;
				break;
			case "Control":
				base.Controls[ControlContainer].Controls[ControlName].BackColor = Color.FromArgb(128, 255, 255);
				break;
			}
		}
		catch (Exception ex)
		{
			ProjectData.SetProjectError(ex);
			Exception ex2 = ex;
			ProjectData.ClearProjectError();
		}
	}

	private void SpeedUp_Click(object sender, EventArgs e)
	{
		DoBoxChange("RemoteSpeedUp");
	}

	public void RemoteSpeedUp()
	{
		if (!NoChanges & (ControlLevel == 0))
		{
			DisplayOn = true;
			if (Operators.CompareString(RemoteControl, "REMOTE", TextCompare: false) != 0)
			{
				if (!CleanOn && SpeedProgramSet > 0)
				{
					ImageControlAChange("SpeedProgram", "MaxSpeed", "SpeedUp", "Speed", "ArrowUpDe");
					ResetButtonsTMon();
					if (MaxSpeedSet < 16f)
					{
						MaxSpeedSet += 1f;
					}
					NewSpeed(SpeedProgramSet, NewProgram: false);
					if (ProgramRun)
					{
						IOPOT.UpdateSpeed(checked(IndexProgram1 + 1), ProgramHold, ProgramReset);
					}
				}
			}
			else
			{
				ImageControlAChange("SpeedProgram", "MaxSpeed", "SpeedUp", "Speed", "ArrowUpDe");
				ResetButtonsTMon();
				if (Operators.CompareString(RemoteControl, "REMOTE", TextCompare: false) == 0)
				{
					Functions.RegUpdate("Dtread", "Treadmill", "SendC", Functions.RegUpdate("Dtread", "Treadmill", "SendC", "", "Get") + ",RSU", "Save");
				}
			}
		}
		else if (!NoChangesTM.Enabled)
		{
			NoChangesTM.Enabled = true;
		}
	}

