	}

	public void SetProgramStartImage()
	{
		if (!(!ResetStartTM.Enabled & !Actuator))
		{
			return;
		}
		if (EmergencyStop)
		{
			GetInclinePositionOK();
			if (InclinePositionOK | ProgramRun | ProgramReset | TestEStop)
			{
				if (!ProgramRun & !ProgramReset)
				{
					StartProgramPic = "StartSW";
				}
				else if (ProgramHold)
				{
					StartProgramPic = "ReStartSW";
				}
				else
				{
					StartProgramPic = "HoldSW1";
				}
			}
			else
			{
				ProgramRemoteImage("ResetSw1");
			}
		}
		else
		{
			StartProgramPic = "Estop1";
		}
	}

