						num3 = 18 * (int)Math.Round(ResMultiH);
					}
				}
				else
				{
					num = 16 * (int)Math.Round(ResMultiW);
					num2 = 40 * (int)Math.Round(ResMultiH);
					num3 = 14 * (int)Math.Round(ResMultiH);
				}
				graphics.DrawString(Holdtxt, new Font("Arial", num3), Brushes.White, num, num2);
				break;
			}
			case "HoldDeSW1Not":
			{
				string language = Language;
				if (Operators.CompareString(language, "Dutch", TextCompare: false) != 0)
				{
					if (Operators.CompareString(language, "Chinese", TextCompare: false) == 0)
					{
						num = 28 * (int)Math.Round(ResMultiW);
						num2 = 40 * (int)Math.Round(ResMultiH);
						num3 = 14 * (int)Math.Round(ResMultiH);
					}
					else
					{
						num = 22 * (int)Math.Round(ResMultiW);
						num2 = 38 * (int)Math.Round(ResMultiH);
						num3 = 18 * (int)Math.Round(ResMultiH);
					}
				}
				else
				{
					num = 16 * (int)Math.Round(ResMultiW);
					num2 = 40 * (int)Math.Round(ResMultiH);
					num3 = 14 * (int)Math.Round(ResMultiH);
				}
				graphics.DrawString(Holdtxt, new Font("Arial", num3), Brushes.LightBlue, num, num2);
