	public void ImageControlAChange(string ControlB, string ControlA, string Control, string Setting, string Image)
	{
		try
		{
			if (base.Controls[ControlB].Controls[ControlA].Controls[Control].InvokeRequired)
			{
				SetControl4Callback method = ImageControlAChange;
				Invoke(method, ControlB, ControlA, Control, Setting, Image);
				return;
			}
			switch (Setting)
			{
			case "WaterDepth":
				switch (Image)
				{
				case "ArrowDnOp":
					WaterDepthDN.Image = Resources.ArrowDnOp;
					break;
				case "ArrowUpOp":
					WaterDepthUP.Image = Resources.ArrowUpOP;
					break;
				case "ArrowDnDe":
					WaterDepthDN.Image = Resources.ArrowDnDe;
					break;
				case "ArrowUpDe":
					WaterDepthUP.Image = Resources.ArrowUpDe;
					break;
				}
				break;
			case "SpeedProgram":
				switch (Image)
				{
				case "ArrowDnOp":
					SpeedProgramDown.Image = Resources.ArrowDnOp;
					break;
				case "ArrowUpOp":
					SpeedProgramUp.Image = Resources.ArrowUpOP;
					break;
				case "ArrowDnDe":
					SpeedProgramDown.Image = Resources.ArrowDnDe;
					break;
				case "ArrowUpDe":
					SpeedProgramUp.Image = Resources.ArrowUpDe;
					break;
				}
				break;
			case "Speed":
				switch (Image)
				{
				case "ArrowDnOp":
					SpeedDown.Image = Resources.ArrowDnOp;
					break;
				case "ArrowUpOp":
					SpeedUp.Image = Resources.ArrowUpOP;
					break;
				case "ArrowDnDe":
					SpeedDown.Image = Resources.ArrowDnDe;
					break;
				case "ArrowUpDe":
					SpeedUp.Image = Resources.ArrowUpDe;
					break;
				}
				break;
			case "GradientProgram":
				switch (Image)
				{
				case "ArrowDnOp":
					GradientProgramDown.Image = Resources.ArrowDnOp;
