	private void WallPaperStyle(string Style)
	{
		RegistryKey registryKey = Registry.CurrentUser.OpenSubKey("Control Panel\\Desktop", writable: true);
		switch (Style)
		{
		case "Tile":
			registryKey.SetValue("WallpaperStyle", "0");
			registryKey.SetValue("TileWallpaper", "1");
			break;
		case "Center":
			registryKey.SetValue("WallpaperStyle", "0");
			registryKey.SetValue("TileWallpaper", "0");
			break;
		case "Stretch":
			registryKey.SetValue("WallpaperStyle", "2");
			registryKey.SetValue("TileWallpaper", "0");
			break;
		case "Fit":
			registryKey.SetValue("WallpaperStyle", "6");
			registryKey.SetValue("TileWallpaper", "0");
			break;
		case "Fill":
			registryKey.SetValue("WallpaperStyle", "10");
			registryKey.SetValue("TileWallpaper", "0");
			break;
		}
		registryKey.Close();
	}

