	public bool WriteDisplayButtonsOld()
	{
		bool flag = false;
		checked
		{
			if (ProgramNumSpeed >= 0)
			{
				DisplayButtons = SerialNo + ",";
				DisplayButtons = DisplayButtons + ProgramMaxSpeed + ",";
				DisplayButtons = DisplayButtons + MaxSpeedSet + ",";
				DisplayButtons = DisplayButtons + ProgramNumSpeed + ",";
				DisplayButtons = DisplayButtons + ProgramMaxGradient + ",";
				DisplayButtons = DisplayButtons + MaxGradientSet + ",";
				DisplayButtons = DisplayButtons + ProgramNumGradient + ",";
				int num = 1;
				do
				{
					if (SpeedProgram.Controls["Button" + num].BackColor == Color.Coral)
					{
						DisplayButtons += "Coral,";
					}
					else if (SpeedProgram.Controls["Button" + num].BackColor == Color.Yellow)
					{
						DisplayButtons += "Yellow,";
					}
					else
					{
						DisplayButtons += "Control,";
					}
					DisplayButtons = DisplayButtons + Interaction.GetSetting("Treadmill", "Speed", num.ToString(), "0") + ",";
					num++;
				}
				while (num <= 60);
				num = 121;
				int num2 = 61;
				do
				{
					num--;
					if (GradientProgram.Controls["Button" + num2].BackColor == Color.Coral)
					{
						DisplayButtons += "Coral,";
					}
					else if (GradientProgram.Controls["Button" + num2].BackColor == Color.Yellow)
					{
						DisplayButtons += "Yellow,";
					}
					else
					{
						DisplayButtons += "Control,";
					}
					DisplayButtons = DisplayButtons + Interaction.GetSetting("Treadmill", "GradientPlus", (num - 60).ToString(), "0") + ",";
					num2++;
				}
				while (num2 <= 120);
				return true;
			}
			return false;
		}
	}

