	public void ButtonProgramStart()
	{
		PreStart = true;
		DoBoxChange("RemoteProgramStart");
	}

	private void ProgramStartSet()
	{
		if (!ProgramStartSwTM.Enabled & (ControlLevel == 0))
		{
			ProgramStartSwTM.Enabled = true;
			PreStart = true;
			DoBoxChange("RemoteProgramStart");
		}
	}

	public void RemoteProgramStart()
	{
		if (!NoChanges)
		{
			DisplayOn = true;
			if (!ProgramAtth)
			{
				return;
			}
			if (Operators.CompareString(RemoteControl, "REMOTE", TextCompare: false) != 0)
			{
				if (EmergencyStop)
				{
					if ((!USBOPTORLY816.SandBoxOnOff & !LevelZero & !MachineSetup.InclineDisplayOnOff & IOPOTCommsActive) | (!USBOPTORLY816.SandBoxOnOff & !LevelZero & !IOPOT.LearnAcc & IOPOTCommsActive) | (TestEStop & !LevelZero))
					{
						if ((!ProgramReset & !MyProject.Forms.Information.Visible & Key) | (!ProgramReset & !MyProject.Forms.Information.Visible & WordPass) | (!ProgramReset & !MyProject.Forms.Information.Visible & !KeyLock & !PassKey) | (!ProgramReset & !MyProject.Forms.Information.Visible & !PassKey) | (PassKey & WordPass) | (ProgramRun & !ProgramReset))
						{
							if (!ProgramHold & !ProgramRun & !Locked & !ProgramLock)
							{
								MyProject.Forms.Information.PersonHealthCheck();
								StartProgram();
								UpdateDisplayHold = false;
								StartProgramPic = "HoldDeSW1";
								UpdateVoiceImage();
								ControlAChange("TimerBox", "ShortTimerStopCycle", "Text", "0");
								ControlAChange("TimerBox", "ShortTimerStartCycle", "Text", "0");
							}
							else
							{
								PreStart = false;
								if (!ProgramHold)
								{
									HoldProgram();
									return;
								}
								RestartProgram();
								UpdateDisplayHold = false;
								StartProgramPic = "HoldDeSW1";
								UpdateVoiceImage();
							}
						}
						else
						{
							WordPassSet();
						}
					}
					else
					{
						PreStart = false;
						if (USBOPTORLY816.SandBoxOnOff)
						{
							StartProgramPic = "SandBox";
						}
					}
				}
				else
				{
					PreStart = false;
					EStopReset();
				}
				return;
			}
			PreStart = false;
			if (Operators.CompareString(RemoteControl, "REMOTE", TextCompare: false) == 0)
			{
				if (Operators.CompareString(RemoteStartImage, "HoldSw1", TextCompare: false) == 0)
				{
					StartProgramPic = "HoldDeSW1";
				}
				else if (Operators.CompareString(RemoteStartImage, "Estop", TextCompare: false) == 0)
				{
					StartProgramPic = "Estop1De";
				}
				else if (Operators.CompareString(RemoteStartImage, "StartSW", TextCompare: false) == 0)
				{
					StartProgramPic = "StartSWDe";
				}
				else if (Operators.CompareString(RemoteStartImage, "ReStartSW", TextCompare: false) == 0)
				{
					StartProgramPic = "ReStartDeSW1";
				}
				Functions.RegUpdate("Dtread", "Treadmill", "SendC", Functions.RegUpdate("Dtread", "Treadmill", "SendC", "", "Get") + ",PS", "Save");
			}
		}
		else
		{
			PreStart = false;
			if (!NoChangesTM.Enabled)
			{
				NoChangesTM.Enabled = true;
			}
		}
	}

	private void WordPassSet()
	{
