	private void StartProgram()
	{
		ProgramRun = true;
		ProgramHold = false;
		Conveyor = true;
		IOPOT.ConveyorControllerOnOff();
		MotorRun = false;
		DisplayCount = 0;
		IOPOT.ConveyorOffTM.Enabled = false;
		ZeroIndicators();
		Interaction.SaveSetting("Machine", "Other", "Clock", "0");
		PreStart = false;
		ProgramRemoteImage("ResetDeSw1");
		ControlChange("PersonEdit", "Enabled", "False");
		if (ProgramNumSpeed >= 1)
		{
			SSLLabelChange("");
			ControlBChange("SpeedProgram", "SpeedSelect", "SpeedProgramUp", "Enabled", "False");
			ControlBChange("SpeedProgram", "SpeedSelect", "SpeedProgramDowm", "Enabled", "False");
			ImageControlAChange("SpeedProgram", "SpeedSelect", "SpeedProgramUp", "SpeedProgram", "ArrowUpDe");
			ImageControlAChange("SpeedProgram", "SpeedSelect", "SpeedProgramDown", "SpeedProgram", "ArrowDnDe");
		}
		else
		{
			SSLLabelChange("0.0 " + kmhLabelSP.Text);
		}
		if (ProgramNumGradient >= 1)
		{
			GSLLabelChange("");
			ControlBChange("GradientProgram", "GradientSelect", "GradientProgramUp", "Enabled", "False");
			ControlBChange("GradientProgram", "GradientSelect", "GradientProgramDowm", "Enabled", "False");
			ImageControlAChange("GradientProgram", "GradientSelect", "GradientProgramUp", "GradientProgram", "ArrowUpDe");
			ImageControlAChange("GradientProgram", "GradientSelect", "GradientProgramDown", "GradientProgram", "ArrowDnDe");
		}
		else
		{
			GSLLabelChange(Gradient);
		}
		if (!RLY816Startup)
		{
			RLY816.CirculationOff();
			RLY816.CirculationDelayTMOff();
		}
		ResetWordPassTMOff();
		checked
		{
			if (IOPOTCommsActive | TestEStop)
			{
				IOPOT.UpdateSpeed(IndexProgram1 + 1, ProgramHold, ProgramReset);
			}
			if (MachineSetup.InclineDisplayOnOff)
			{
				if (IOPOTCommsActive | TestEStop)
				{
					IOPOT.UpdateGradient(IndexProgram1 + 1, ProgramHold, ProgramReset);
				}
				else
				{
					MessageBox.Show("IOPOT CommsActive = False");
				}
			}
			FlashTM.Enabled = true;
			ClearRunningInfo();
			PauseDisplayCount = 0;
		}
	}

	public void ClearRunningInfo()
	{
		IOPOT.Distancekm = 0.0;
		IOPOT.Distancemi = 0.0;
		CalorieDry = 0.0;
		CalorieWet = 0.0;
