	public void HoldProgram()
	{
		if (EmergencyStop)
		{
			StartProgramPic = "ReStartDeSW1";
			UpdateVoiceImage();
		}
		ProgramHold = true;
		if (IOPOTCommsActive | TestEStop)
		{
			HoldSpeed = Conversions.ToInteger(Interaction.GetSetting("Treadmill", "Speed", Conversions.ToString(checked(IndexProgram1 + 1)), "0"));
		}
		RemoteSpeedSelectG8(0);
		ControlChange("PersonEdit", "Enabled", "True");
		ProgramRemoteImage("ResetSw1");
	}

	private void RestartProgram()
	{
		ProgramHold = false;
		ControlChange("PersonEdit", "Enabled", "False");
		ProgramRemoteImage("ResetDeSw1");
		StartProgramPic = "HoldDeSW1";
		UpdateVoiceImage();
		checked
		{
			if (IOPOTCommsActive | TestEStop)
			{
				IOPOT.UpdateSpeed(IndexProgram1 + 1, ProgramHold, ProgramReset);
				ProgramMark = 0;
			}
			if (MachineSetup.InclineDisplayOnOff && (IOPOTCommsActive | TestEStop))
			{
				IOPOT.UpdateGradient(IndexProgram1 + 1, ProgramHold, ProgramReset);
			}
			RemoteSpeedSelectG8(HoldSpeed);
			if (!FlashTM.Enabled)
			{
				FlashTM.Enabled = true;
			}
		}
	}

