	private void GetFileDecending()
	{
		DirectoryInfo directoryInfo = new DirectoryInfo("C:\\" + SerialNo);
		FileInfo[] files = directoryInfo.GetFiles("*.*");
		DateTime t = new DateTime(1000L);
		string empty = string.Empty;
		FileInfo[] array = files;
		foreach (FileInfo fileInfo in array)
		{
			if (DateTime.Compare(fileInfo.LastWriteTime, t) > 0)
			{
				empty = fileInfo.Name;
				t = fileInfo.LastWriteTime;
			}
		}
	}

	private List<FileInfo> GetNewestFiles(string dirPath, int N)
	{
		List<FileInfo> list = new List<FileInfo>();
		DirectoryInfo directoryInfo = new DirectoryInfo(dirPath);
		try
		{
			FileInfo[] files = directoryInfo.GetFiles("*.*");
			Array.Sort(files, [SpecialName] (FileInfo x, FileInfo y) => y.LastWriteTime.CompareTo(x.LastWriteTime));
			if (files.Length >= N)
			{
				FileInfo[] array = new FileInfo[checked(N - 1 + 1)];
				Array.Copy(files, array, N);
				list.AddRange(array);
			}
			else
			{
				list.AddRange(files);
			}
		}
		catch (Exception ex)
		{
			ProjectData.SetProjectError(ex);
			Exception ex2 = ex;
			ProjectData.ClearProjectError();
		}
		return list;
	}

	public string Check_exe_Cleanup(string Drive, string SerialNo)
	{
		if (!RestartRequired & !Restarting)
		{
			if (Functions.FileExist(Drive + "\\0\\", "Version.bak"))
			{
				Functions.DeleteFile(Drive + "\\0\\", "Version.bak");
				Functions.DirDelete(Drive, "0");
			}
			if (Functions.FileExist(Drive + "\\" + SerialNo + "\\", "Version.bak"))
			{
				Functions.DeleteFile(Drive + "\\" + SerialNo + "\\", "Version.bak");
			}
		}
		string result = default(string);
		return result;
	}

