	public string RamCheck(string File, string Ext, Version FileVersionNo, bool VersionCheck)
	{
		string text = "";
		string result = "";
		int driveType = 1;
		string expression = Functions.CheckForDrives(driveType);
		string[] array = Strings.Split(expression, ",");
		int num = Conversions.ToInteger(array.GetValue(Microsoft.VisualBasic.Information.LBound(array)));
		USB = false;
		checked
		{
			if (num == 0)
			{
				int num2 = Microsoft.VisualBasic.Information.UBound(array);
				for (int i = 0; i <= num2; i += 2)
				{
					USB = true;
					text = array[i];
					string text2 = array[i + 1];
					string serialNumberFromDriveLetter = Functions.GetSerialNumberFromDriveLetter(text);
				}
				string text3 = Functions.CheckFileName(text + "\\", File, Ext, FileVersionNo, VersionCheck);
				if (Functions.FileExist(text + "\\", File + Ext))
				{
					result = text;
					USB = true;
				}
			}
			if (num > 0)
			{
				switch (num)
				{
				case 1:
					Interaction.SaveSetting("Recording", "Running", "RAM", NoStick);
					KeyError = false;
					break;
				case 2:
					Interaction.SaveSetting("Recording", "Running", "RAM", StickProblem);
					if (!KeyError)
					{
						WriteMachineHistory();
						KeyError = true;
					}
					break;
				case 3:
					Interaction.SaveSetting("Recording", "Running", "RAM", UnknownProblem);
					break;
				}
				USB = false;
			}
			else
			{
				Interaction.SaveSetting("Recording", "Running", "RAM", "");
			}
			return result;
		}
	}

