	private void CleanSwOn()
	{
		if ((EmergencyStop & DoorClosedIn & DoorClosedOut & !CleanError & IOPOTCommsActive & !IOPOT.LearnAcc) | (EmergencyStop & DoorClosedIn & DoorClosedOut & !CleanError & IOPOTCommsActive & !MachineSetup.InclineDisplayOnOff) | (EmergencyStop & !MachineSetup.DoorSensorsOnOff & !CleanError & IOPOTCommsActive & !MachineSetup.InclineDisplayOnOff) | (EmergencyStop & !MachineSetup.DoorSensorsOnOff & !CleanError & IOPOTCommsActive & !IOPOT.LearnAcc) | TestEStop)
		{
			if (!RLY816Startup)
			{
