	private void WaterDepthMeasureAdjust()
	{
		if (!Lift)
		{
			double num = 0.1;
			if ((USBOPTORLY816.FillPump & USBOPTORLY816.MotorSwitch[3] & !Conversions.ToBoolean(Interaction.GetSetting("Dtread", "Display", "RLY82Startup", "True"))) | (USBOPTORLY816.FillPump & USBOPTORLY816.MotorSwitch[3] & TreadmillFloatSw) | (USBOPTORLY816.FillPump & TestEStop & TreadmillFloatSw) | (TestEStop & USBOPTORLY816.FillPump & !EmergencyEmpty & (WaterDepthMeasure < Conversion.Val(WaterDepthInd.Text))))
			{
				if (!Conversions.ToBoolean(Interaction.GetSetting("Dtread", "Display", "RLY82Startup", "True")) & !ADC1Stop & (ADC1 > 5))
				{
					WaterDepthMeasure = WaterDepthMeasureADC1;
				}
				else
				{
					WaterDepthMeasure += num;
