	private void SetPumpErrorTime()
	{
		checked
		{
			if (MachineSetup.FloatSwOnOff)
			{
				if (USBOPTORLY816.FillPump | USBOPTORLY816.EmptyPump)
				{
					if (!PumpCheckTMEnabled)
					{
						float num = (float)Math.Abs(Conversion.Val(Interaction.GetSetting("Health", "Person", "WaterDepthHold", "0")));
						float num2 = Conversions.ToSingle(Interaction.GetSetting("Health", "Person", "WaterDepthMeasure", "0"));
						if (!EmergencyEmpty)
						{
							WaterDepthChange = (int)Math.Round(num + Math.Abs(num2));
						}
						else
						{
							WaterDepthChange = (int)Math.Round(num2 + Math.Abs(FloatSwDepth));
						}
						if (WaterDepthChange > 0)
						{
							PumpCheckTMInterval = (int)Math.Round((double)(int)Math.Round((double)Math.Abs(WaterDepthChange) / 0.1 * (double)WaterDepthCheckTMInterval) * 2.5);
						}
						else
						{
							PumpCheckTMInterval = 50000;
						}
						PumpCheckTMon();
					}
				}
				else
				{
					PumpCheckTMOff();
				}
			}
			else if (USBOPTORLY816.FillPump | USBOPTORLY816.EmptyPump)
			{
				if (!Lift)
				{
					if ((WaterDepthMeasure > WaterDepthError + 1.0) | (WaterDepthMeasure < WaterDepthError - 1.0))
					{
						WaterDepthError = WaterDepthMeasure;
						PumpCheckTMOff();
						return;
					}
					PumpCheckTMInterval = 30000;
					if (!PumpCheckTMEnabled)
					{
						PumpCheckTMon();
					}
				}
				else
				{
					PumpCheckTMInterval = (int)Math.Round(Math.Abs(WaterDepthMeasure - Conversion.Val(WaterDepthInd.Text) + 2.0) * 1000.0);
					if (!PumpCheckTMEnabled)
					{
						PumpCheckTMon();
					}
				}
			}
			else
			{
				PumpCheckTMOff();
			}
		}
	}

