		WaterDepthMeasureAdjust();
		Interaction.SaveSetting("Dtread", "Display", "Stage2", "20");
		WaterDepthTimePerMilimeter();
		Interaction.SaveSetting("Dtread", "Display", "Stage2", "21");
		FillEmptyControl();
		Interaction.SaveSetting("Dtread", "Display", "Stage2", "22");
		WaterDepthIndicatorSet();
		Interaction.SaveSetting("Dtread", "Display", "Stage2", "23");
		SetPumpErrorTime();
		if ((WaterDepthMeasure > 0.0) & ProgramRun)
		{
			CleanReset = true;
		}
		if (WDOnOff)
		{
			WaterDepthCheckTMon();
		}
		if (Operators.CompareString(RemoteControl, "MAIN", TextCompare: false) == 0)
		{
			Functions.RegUpdate("Dtread", "Treadmill", "SendD", WriteDisplayPara(), "Save");
		}
	}

