	private void LiveDepthTM_Tick(object sender)
	{
		int num = 5;
		Interaction.SaveSetting("Dtread", "Display", "Stage1", "15");
		checked
		{
			if (!Conversions.ToBoolean(Interaction.GetSetting("Dtread", "Display", "RLY82Startup", "True")))
			{
				if (!Lift)
				{
					CalDepth = Conversions.ToInteger(Interaction.GetSetting("DTread", "RLY82", "WaterRange", "318"));
					CalDepthZero = Conversions.ToInteger(Interaction.GetSetting("DTread", "RLY82", "WaterZero", "253"));
					ADC1 = Conversions.ToInteger(Interaction.GetSetting("Dtread", "RLY82", "ADC1", "0"));
					double num3 = default(double);
					if ((ADC1 < 1024) & (ADC1 >= 0))
					{
						AverageADC1 = AverageADC1 + "," + ADC1;
						Array array = Strings.Split(AverageADC1, ",");
						if (Microsoft.VisualBasic.Information.UBound(array) > num)
						{
							AverageADC1 = "";
							int num2 = num;
							for (int i = 1; i <= num2; i++)
							{
								AverageADC1 += Conversions.ToString(array.GetValue(i));
								if (i < num)
								{
									AverageADC1 += ",";
								}
								num3 += Conversions.ToDouble(array.GetValue(i));
							}
							int num4 = ((num3 != 0.0) ? ((int)Math.Round(num3 / (double)num)) : 0);
							if (num3 > 0.0)
							{
								WaterDepthMeasureADC1 = (double)CalDepthSet / (double)CalDepth * (double)(num4 - CalDepthZero) / 10.0;
								if (!ADC1Stop & (ADC1 > 5))
								{
									WaterDepthMeasure = WaterDepthMeasureADC1;
									WaterDepthIndicatorSet();
								}
							}
						}
					}
					CalDepth = Conversions.ToInteger(Interaction.GetSetting("DTread", "RLY82", "TankRange", "318"));
					CalDepthZero = Conversions.ToInteger(Interaction.GetSetting("DTread", "RLY82", "TankZero", "253"));
					ADC2 = Conversions.ToInteger(Interaction.GetSetting("Dtread", "RLY82", "ADC2", "0"));
					if ((ADC2 < 1024) & (ADC2 >= 0))
					{
						AverageADC2 = AverageADC2 + "," + ADC2;
						Array array = Strings.Split(AverageADC2, ",");
						if (Microsoft.VisualBasic.Information.UBound(array) > num)
						{
							AverageADC2 = "";
							int num5 = num;
							for (int i = 1; i <= num5; i++)
							{
								AverageADC2 += Conversions.ToString(array.GetValue(i));
								if (i < num)
								{
									AverageADC2 += ",";
								}
								num3 += Conversions.ToDouble(array.GetValue(i));
							}
							int num4 = ((num3 != 0.0) ? ((int)Math.Round(num3 / (double)num)) : 0);
							if (num3 > 0.0)
							{
								WaterDepthMeasureADC2 = (double)CalDepthSet / (double)CalDepth * (double)(num4 - CalDepthZero) / 10.0;
								if (!ADC2Stop & (ADC2 > 5))
								{
									ControlChange("TankTrack", "Height", Conversions.ToString((int)Math.Round(Math.Round(80.0 - WaterDepthMeasureADC2 * (5.0 / 64.0), 0))));
								}
							}
						}
					}
					if (!MachineSetup.FloatSwOnOff)
					{
						if (WaterDepthMeasure > (double)FloatSwDepth)
						{
							TreadmillFloatSw = true;
						}
						else if ((USBOPTORLY816.EmptyPump & USBOPTORLY816.MotorSwitch[4] & (WaterDepthMeasure <= (double)FloatSwDepth)) | (EmergencyEmpty & USBOPTORLY816.MotorSwitch[4] & TreadmillFloatSw & (WaterDepthMeasure <= (double)FloatSwDepth)) | (TestEStop & TreadmillFloatSw & (WaterDepthMeasure <= (double)FloatSwDepth)))
						{
							TreadmillFloatSw = false;
							WaterDepthMeasure = FloatSwDepth;
						}
						PressureDetectorChamber();
					}
				}
				else
				{
					WaterDepthMeasure = (Conversions.ToDouble(Interaction.GetSetting("Dtread", "RLY82", "Pulse", "400")) - 400.0) / 10.0;
					WaterDepthIndicatorSet();
					ControlAChange("WaterDepth", "MoveCountInd", "Text", Interaction.GetSetting("Dtread", "RLY82", "Pulse", "400"));
				}
			}
			if (MachineSetup.ChamberTempOnOff & (Conversions.ToInteger(Interaction.GetSetting("Health", "Setup", "PortRLY82", "0")) > 0))
			{
				ControlAChange("WaterDepth", "ChamberTemp", "Visible", "True");
				TemperatureChamber();
			}
			else
			{
				ControlAChange("WaterDepth", "ChamberTemp", "Visible", "False");
			}
			if (MachineSetup.TankTempOnOff & (Conversions.ToInteger(Interaction.GetSetting("Health", "Setup", "PortRLY82", "0")) > 0))
			{
				ControlAChange("WaterTemp", "TankTemp", "Visible", "True");
				TemperatureTank();
			}
			else
			{
				ControlAChange("WaterTemp", "TankTemp", "Visible", "False");
			}
			Interaction.SaveSetting("Dtread", "Display", "Stage1", "16");
		}
	}

	private void TemperatureChamber()
	{
		double num = 4.94;
		double num2 = 2.048;
		double num3 = 1023.0;
		double num4 = num3 / num2;
		double num5 = 5.0 / num * 10.0;
		double num6 = num4 * (num5 / 1000.0);
		double value = 0.0;
		string text = "0.0";
		int num7 = 5;
		ADC8 = Conversions.ToInteger(Interaction.GetSetting("Dtread", "RLY82", "ADC8", "0"));
		AverageADC8 = AverageADC8 + "," + ADC8;
		Array array = Strings.Split(AverageADC8, ",");
		double num9 = default(double);
		if (Microsoft.VisualBasic.Information.UBound(array) > num7)
		{
			AverageADC8 = "";
			int num8 = num7;
			for (int i = 1; i <= num8; i = checked(i + 1))
			{
				AverageADC8 += Conversions.ToString(array.GetValue(i));
				if (i < num7)
				{
					AverageADC8 += ",";
				}
				num9 += Conversions.ToDouble(array.GetValue(i));
			}
		}
		double num10;
		if (num9 == 0.0)
		{
			num10 = 0.0;
			return;
		}
		num10 = num9 / (double)num7;
		if (num10 > 0.0)
		{
			value = num10 / num6;
		}
		text = ((Math.Round(value, 1) != Math.Round(value, 0)) ? Math.Round(value, 1).ToString() : (Math.Round(value, 1) + ".0"));
		ControlAChange("WaterDepth", "ChamberTemp", "Text", text + Conversions.ToString(Strings.Chr(176)) + "C");
	}

	private void TemperatureTank()
	{
		double num = 4.94;
		double num2 = 2.048;
		double num3 = 1023.0;
		double num4 = num3 / num2;
		double num5 = 5.0 / num * 10.0;
		double num6 = num4 * (num5 / 1000.0);
		double value = 0.0;
		string text = "0.0";
		int num7 = 5;
		ADC7 = Conversions.ToInteger(Interaction.GetSetting("Dtread", "RLY82", "ADC7", "0"));
		AverageADC7 = AverageADC7 + "," + ADC7;
		Array array = Strings.Split(AverageADC7, ",");
		double num9 = default(double);
		if (Microsoft.VisualBasic.Information.UBound(array) > num7)
		{
			AverageADC7 = "";
			int num8 = num7;
			for (int i = 1; i <= num8; i = checked(i + 1))
			{
				AverageADC7 += Conversions.ToString(array.GetValue(i));
				if (i < num7)
				{
					AverageADC7 += ",";
				}
				num9 += Conversions.ToDouble(array.GetValue(i));
			}
		}
		double num10;
		if (num9 == 0.0)
		{
			num10 = 0.0;
			return;
		}
		num10 = num9 / (double)num7;
		if (num10 > 0.0)
		{
			value = num10 / num6;
		}
		text = ((Math.Round(value, 1) != Math.Round(value, 0)) ? Math.Round(value, 1).ToString() : (Math.Round(value, 1) + ".0"));
		if (!TankTempFlag)
		{
			ControlAChange("WaterTemp", "TankTemp", "Text", text + Conversions.ToString(Strings.Chr(176)) + "C");
		}
		Interaction.SaveSetting("Dtread", "WaterTemp", "TankTemp", text + Conversions.ToString(Strings.Chr(176)) + "C");
		if (Conversions.ToDouble(Interaction.GetSetting("Dtread", "WaterTemp", "TankTemp", "0")) < Conversions.ToDouble(Interaction.GetSetting("Dtread", "WaterTemp", "TankTempSet", "0")))
		{
			Interaction.SaveSetting("Dtread", "WaterTemp", "TankTempHeater", "True");
		}
		else
		{
			Interaction.SaveSetting("Dtread", "WaterTemp", "TankTempHeater", "False");
		}
	}

