	private void CleanOpTm_Tick(object sender, EventArgs e)
	{
		if (((Operators.CompareString(Interaction.GetSetting("DTread", "Aqua", "CleanOnOff", "False"), "True", TextCompare: false) == 0) & CleanOn & EmergencyStop & DoorClosedIn & DoorClosedOut) | ((Operators.CompareString(Interaction.GetSetting("DTread", "Aqua", "CleanOnOff", "False"), "True", TextCompare: false) == 0) & CleanOn & EmergencyStop & !MachineSetup.DoorSensorsOnOff) | (CleanOn & TestEStop))
		{
			if (!CleanOp)
			{
				CleanOp = true;
				PreEmptyMaxTime = new TimeSpan(0, 0, 5, 0);
				PreFillMaxTime = new TimeSpan(0, 0, 2, 0);
				EmptyMaxTime = new TimeSpan(0, 0, 8, 0);
				CleanTime = DateAndTime.Now.Add(PreEmptyMaxTime);
				CleanWorkIndex = 1;
				CleanWorkIndexDone = 0;
				Clean0 = false;
				Clean1 = false;
				CleanEmpty = false;
				if (JetOn)
				{
					DoBoxChange("RemoteJetOnOff");
				}
				StartProgramPic = "HoldDeSW1";
				ControlChange("ProgramStart", "Enabled", "False");
				ProgramRemoteImage("ResetDeSw1");
				ControlChange("PersonEdit", "Enabled", "False");
				RemoteJetImage = "JetPowerOffDe";
				JetOnOffSw.Enabled = false;
				CleaningRun();
				ControlAChange("Clean", "CleanOnOff", "Enabled", "True");
				ProgramRemoteImage("CNPowerOn");
				return;
			}
			switch (CleanWorkIndex)
			{
			case 1:
				if ((DateTime.Compare(CleanTime, DateAndTime.Now) >= 0) & !PumpCheck & !Clean0)
				{
					if (!Clean0)
					{
						ControlLevel = 1;
						Clean0 = true;
						CleanWorkChange(PreEmpty);
						ControlAChange("WaterDepth", "WaterDepthInd", "Text", (FloatSwDepth - 1f).ToString());
						Interaction.SaveSetting("Health", "Person", "WaterDepthInd", WaterDepthInd.Text);
						Interaction.SaveSetting("Health", "Person", "WaterDepthHold", WaterDepthInd.Text);
						if (!WDOnOff & !WaterDepthSwChange)
						{
							WaterDepthSwChange = true;
							DoBoxChange("WaterDepthSw");
						}
					}
				}
				else if ((DateTime.Compare(CleanTime, DateAndTime.Now) >= 0) & !PumpCheck & TreadmillFloatSw)
				{
					if (!Clean0)
					{
					}
				}
				else if ((DateTime.Compare(CleanTime, DateAndTime.Now) >= 0) & !PumpCheck & !TreadmillFloatSw)
				{
					CleanWorkIndex = 2;
					Clean0 = false;
					CleanTime = DateAndTime.Now.Add(PreFillMaxTime);
				}
				else
				{
					CleanWorkChange(PreErr);
					CleanError = true;
					Clean0 = false;
					ControlAChange("Clean", "CleanOnOff", "Enabled", "False");
					ProgramRemoteImage("CNPowerOnDe");
					CleaningOff();
				}
				break;
			case 2:
				if ((DateTime.Compare(CleanTime, DateAndTime.Now) >= 0) & !PumpCheck & !TreadmillFloatSw)
				{
					if (!Clean1)
					{
						ControlLevel = 0;
						Clean1 = true;
						CleanWorkChange(Filling);
						if (!MachineSetup.InclineDisplayOnOff)
						{
							ControlAChange("WaterDepth", "WaterDepthInd", "Text", "2");
						}
						else
						{
							ControlAChange("WaterDepth", "WaterDepthInd", "Text", "5");
						}
						Interaction.SaveSetting("Health", "Person", "WaterDepthInd", WaterDepthInd.Text);
						Interaction.SaveSetting("Health", "Person", "WaterDepthHold", WaterDepthInd.Text);
						if (!WDOnOff & !WaterDepthSwChange)
						{
							WaterDepthSwChange = true;
							DoBoxChange("WaterDepthSw");
						}
					}
				}
				else if ((DateTime.Compare(CleanTime, DateAndTime.Now) >= 0) & !PumpCheck & Clean1)
				{
					CleanWorkIndex = 3;
					Clean1 = false;
					CleanTime = DateAndTime.Now.Add(PreFillMaxTime);
				}
				else
				{
					CleanWorkChange(FillErr1);
					CleanError = true;
					Clean1 = false;
					ControlAChange("Clean", "CleanOnOff", "Enabled", "False");
					ProgramRemoteImage("CNPowerOnDe");
					CleaningOff();
				}
				break;
			case 3:
				if (((DateTime.Compare(CleanTime, DateAndTime.Now) >= 0) & TreadmillFloatSw & !JetOn & !PumpCheck & !ProgramReset) | ((DateTime.Compare(CleanTime, DateAndTime.Now) >= 0) & TestEStop & !ProgramReset & !JetOn & !PumpCheck))
				{
					if (Operators.CompareString(CleanWork.Text, BeltOn, TextCompare: false) != 0 && !CleanBelt)
					{
						CleanBelt = true;
						ControlLevel = 0;
						StartProgram();
						CleanWorkChange(BeltOn);
					}
					break;
				}
				if (!TreadmillFloatSw & !CleanEmpty & !TestEStop)
				{
					CleanWorkChange(Fill + " " + Err2);
					CleanError = true;
					ResetProgram();
					ControlAChange("Clean", "CleanOnOff", "Enabled", "False");
					ProgramRemoteImage("CNPowerOnDe");
					break;
				}
				if ((Conversion.Val(DurationInd.Text) >= Conversion.Val(SetDuration.Text) - 2.0) & !CleanEmpty)
				{
					CleanEmpty = true;
					ControlAChange("WaterDepth", "WaterDepthInd", "Text", (FloatSwDepth - 1f).ToString());
					Interaction.SaveSetting("Health", "Person", "WaterDepthInd", WaterDepthInd.Text);
					Interaction.SaveSetting("Health", "Person", "WaterDepthHold", WaterDepthInd.Text);
				}
				if (ProgramReset)
				{
					CleanWorkIndex = 4;
					CleanBelt = false;
					CleanTime = DateAndTime.Now.Add(EmptyMaxTime);
					ControlAChange("Clean", "CleanOnOff", "Enabled", "False");
					ProgramRemoteImage("CNPowerOnDe");
				}
				break;
			case 4:
				if (((DateTime.Compare(CleanTime, DateAndTime.Now) >= 0) & TreadmillFloatSw & !PumpCheck) | ((DateTime.Compare(CleanTime, DateAndTime.Now) >= 0) & TestEStop & !PumpCheck & (ControlLevel == 0)))
				{
					CleanWorkChange(Emptying);
					ControlLevel = 1;
					ControlAChange("Clean", "CleanOnOff", "Enabled", "False");
					ProgramRemoteImage("CNPowerOnDe");
					CleanEmpty = false;
				}
				else if (((DateTime.Compare(CleanTime, DateAndTime.Now) >= 0) & TreadmillFloatSw) | PumpCheck)
				{
					if (!CleanEnd)
					{
						CleanEnd = true;
						CleanWorkChange(Empty + " " + Err);
						CleanError = true;
						ResetProgram();
						ControlAChange("Clean", "CleanOnOff", "Enabled", "False");
						ProgramRemoteImage("CNPowerOnDe");
						CleanEmpty = false;
					}
					else
					{
						CleaningOff();
					}
				}
				else
				{
					WaterDepthMeasure = FloatSwDepth;
					CleanWorkChange(Done);
					ControlLevel = 0;
					CleanError = false;
					CleanEnd = false;
					CleanEmpty = false;
					ControlAChange("Clean", "CleanOnOff", "Enabled", "False");
					ProgramRemoteImage("CNPowerOnDe");
				}
				break;
			}
		}
		else
		{
			if (!EmergencyStop)
			{
				CleanWorkChange(ESTOP);
			}
			else if (!DoorClosedIn & MachineSetup.DoorSensorsOnOff)
			{
				CleanWorkChange(DoorIn);
				CleanError = true;
			}
			else if (!DoorClosedOut & MachineSetup.DoorSensorsOnOff)
			{
				CleanWorkChange(DoorOut);
				CleanError = true;
			}
			else if (!CleanOn)
			{
				CleanWorkChange(EarlyOff);
			}
			CleanError = true;
			Clean0 = false;
			CleaningOff();
		}
	}

	private void CleaningOff()
	{
		WriteMachineHistory();
		ControlLevel = 0;
		CleanOnFlash.Dispose();
		CleanOpTm.Dispose();
		CleanDone = true;
		CleanWorkIndexDone = 0;
		CleanWorkIndex = 0;
		CleanOp = false;
		CleanEnd = false;
		CleanBelt = false;
		ControlAChange("Clean", "CleanOnOff", "Enabled", "True");
		ProgramRemoteImage("CNPowerOff");
		ControlAChange("WaterDepth", "WaterDepthInd", "Text", "0");
		Interaction.SaveSetting("Health", "Person", "WaterDepthInd", WaterDepthInd.Text);
		Interaction.SaveSetting("Health", "Person", "WaterDepthHold", WaterDepthInd.Text);
		ControlChange("ProgramStart", "Enabled", "True");
		StartProgramPic = "StartSW";
		ControlChange("PersonEdit", "Enabled", "True");
		ProgramRemoteImage("Edit1");
		JetOnOffSw.Enabled = true;
		ProgramRemoteImage("JetPowerOff");
		if (WDOnOff & !WaterDepthSwChange)
		{
			WaterDepthSwChange = true;
			DoBoxChange("WaterDepthSw");
		}
		CleanOp = false;
		CleanSwOff();
		MaxGradientSet = CleanMaxGradientHold;
		MaxSpeedSet = CleanMaxSpeedHold;
		NewSpeed(CleanSpeedHold, NewProgram: true);
		NewGradient(CleanGradientHold, NewProgram: true);
		DurationTimeSet(CleanDurationHold);
	}

