	private void ProgramControlDataTM_Tick(object sender)
	{
		Interaction.SaveSetting("Dtread", "Display", "Stage12", "120");
		ProgramControlDataTMOff();
		checked
		{
			if (PCDCounter > 0)
			{
				PCDCounter--;
				if (PCDCounter == 0)
				{
					UpdateVersionProgram = false;
				}
			}
			else if (!ProgramRun && ((Conversions.ToInteger(SerialNo) > Conversions.ToInteger("1350")) | (Conversions.ToInteger(SerialNo) == 0)))
			{
				Version();
				ProgramControlDataOneDrive();
				ProgramControlDataUSB();
				ProgramControlDataGoogle();
				ProgramControlDataPublic();
			}
			ProgramControlDataTMon();
			Interaction.SaveSetting("Dtread", "Display", "Stage12", "121");
		}
	}

