	private void ShortTimerRunControl()
	{
		if ((Operators.CompareString(Conversions.ToString(TimerLegend.Tag), "TimerRun", TextCompare: false) == 0) & !ProgramRun)
		{
			RemoteProgramStart();
		}
		if (ProgramRun & (ControlLevel == 0))
		{
			if ((Conversions.ToInteger(ShortTimerStop.Text) == 0) & (Conversions.ToInteger(ShortTimerStart.Text) == 0))
			{
				TimerStartStopDelay = false;
			}
			else if ((Operators.CompareString(Conversions.ToString(TimerLegend.Tag), "Timer", TextCompare: false) == 0) & !TimerStartStopDelay)
			{
				TimerStartStopDelay = true;
			}
			else if ((Operators.CompareString(Conversions.ToString(TimerLegend.Tag), "TimerRun", TextCompare: false) == 0) & !TimerStartStopDelay)
			{
				TimerStartStopDelay = true;
			}
			else if (Operators.CompareString(Conversions.ToString(TimerLegend.Tag), "TimerPause", TextCompare: false) == 0)
			{
				TimerStartStopDelay = false;
			}
		}
	}

