	private void ShortTimerControl()
	{
		if (ProgramRun & (ControlLevel == 0))
		{
			if ((Conversions.ToInteger(ShortTimerStop.Text) == 0) & (Conversions.ToInteger(ShortTimerStart.Text) == 0))
			{
				TimerLegend.Tag = "Timer";
				ImageControlChange("TimerBox", "TimerLegend", "TimerLegend", "Timer");
			}
			else if ((Operators.CompareString(Conversions.ToString(TimerLegend.Tag), "TimerRun", TextCompare: false) == 0) & TimerStartStopDelay & ProgramHold)
			{
				TimerLegend.Tag = "TimerPauseDe";
				ImageControlChange("TimerBox", "TimerLegend", "TimerLegend", "TimerPauseDe");
				ResetButtonsTMon();
			}
			else if ((Operators.CompareString(Conversions.ToString(TimerLegend.Tag), "Timer", TextCompare: false) == 0) & !TimerStartStopDelay & !ProgramHold)
			{
				if (Conversions.ToInteger(ShortTimerStop.Text) > 0)
				{
					TimerLegend.Tag = "TimerRunDe";
					ImageControlChange("TimerBox", "TimerLegend", "TimerLegend", "TimerRunDe");
					ResetButtonsTMon();
				}
			}
			else if ((Operators.CompareString(Conversions.ToString(TimerLegend.Tag), "Timer", TextCompare: false) == 0) & !TimerStartStopDelay & ProgramHold)
			{
				if (Conversions.ToInteger(ShortTimerStart.Text) > 0)
				{
					TimerLegend.Tag = "TimerRunDe";
					ImageControlChange("TimerBox", "TimerLegend", "TimerLegend", "TimerRunDe");
					ResetButtonsTMon();
				}
			}
			else if ((Operators.CompareString(Conversions.ToString(TimerLegend.Tag), "TimerPause", TextCompare: false) == 0) & !TimerStartStopDelay & !ProgramHold)
			{
				if ((Conversions.ToInteger(ShortTimerStop.Text) > 0) | (Conversions.ToInteger(ShortTimerStart.Text) > 0))
				{
					TimerLegend.Tag = "TimerRunDe";
					ImageControlChange("TimerBox", "TimerLegend", "TimerLegend", "TimerRunDe");
					ResetButtonsTMon();
				}
			}
			else if (Operators.CompareString(Conversions.ToString(TimerLegend.Tag), "TimerRunDe", TextCompare: false) == 0)
			{
				TimerLegend.Tag = "TimerRun";
				ImageControlChange("TimerBox", "TimerLegend", "TimerLegend", "TimerRun");
			}
			else if (Operators.CompareString(Conversions.ToString(TimerLegend.Tag), "TimerPauseDe", TextCompare: false) == 0)
			{
				TimerLegend.Tag = "TimerPause";
				ImageControlChange("TimerBox", "TimerLegend", "TimerLegend", "TimerPause");
			}
			else if (!TimerStartStopDelay & (Operators.CompareString(Conversions.ToString(TimerLegend.Tag), "TimerPause", TextCompare: false) == 0) & ProgramHold)
			{
				TimerLegend.Tag = "TimerRunDe";
				ImageControlChange("TimerBox", "TimerLegend", "TimerLegend", "TimerRunDe");
				ResetButtonsTMon();
			}
			else if (TimerStartStopDelay & (Operators.CompareString(Conversions.ToString(TimerLegend.Tag), "TimerRun", TextCompare: false) == 0) & !ProgramHold)
			{
				TimerLegend.Tag = "TimerPauseDe";
				ImageControlChange("TimerBox", "TimerLegend", "TimerLegend", "TimerPause");
				ResetButtonsTMon();
			}
		}
		else
		{
			if (ControlLevel != 0)
			{
				return;
			}
			if (((Conversions.ToInteger(ShortTimerStop.Text) > 0) & !TimerStartStopDelay) | ((Conversions.ToInteger(ShortTimerStart.Text) > 0) & !TimerStartStopDelay))
			{
				if (Operators.CompareString(Conversions.ToString(TimerLegend.Tag), "TimerRun", TextCompare: false) != 0)
				{
					TimerLegend.Tag = "TimerRun";
					ImageControlChange("TimerBox", "TimerLegend", "TimerLegend", "TimerRun");
				}
			}
			else if (Operators.CompareString(Conversions.ToString(TimerLegend.Tag), "TimerDe", TextCompare: false) == 0)
			{
				TimerLegend.Tag = "Timer";
				ImageControlChange("TimerBox", "TimerLegend", "TimerLegend", "Timer");
			}
			else if (Operators.CompareString(Conversions.ToString(TimerLegend.Tag), "Timer", TextCompare: false) != 0)
			{
				TimerLegend.Tag = "TimerDe";
				ImageControlChange("TimerBox", "TimerLegend", "TimerLegend", "TimerDe");
				ResetButtonsTMon();
			}
		}
	}

