	public void RemoteLightsOnOff()
	{
		if (!NoChanges & (ControlLevel == 0))
		{
			DisplayOn = true;
			if (Operators.CompareString(RemoteControl, "REMOTE", TextCompare: false) != 0)
			{
				if (!LightsOn & EmergencyStop)
				{
					LightsOn = true;
					ProgramRemoteImage("LightOffDe");
					LightsOnOffTM.Interval = 800;
					LightsOnOffTM.Enabled = true;
					return;
				}
				if (!LightsOn)
				{
					ProgramRemoteImage("LightOffDe");
				}
				else
				{
					ProgramRemoteImage("LightOnDe");
				}
				LightsOn = false;
				LightsOnOffTM.Interval = 800;
				LightsOnOffTM.Enabled = true;
			}
			else if (Operators.CompareString(RemoteControl, "REMOTE", TextCompare: false) == 0)
			{
				Functions.RegUpdate("Dtread", "Treadmill", "SendC", Functions.RegUpdate("Dtread", "Treadmill", "SendC", "", "Get") + ",RLT", "Save");
			}
		}
		else if (!NoChangesTM.Enabled)
		{
			NoChangesTM.Enabled = true;
		}
	}

