		{
			if ((!ProgramRun | ((Operators.CompareString(RemoteControl, "REMOTE", TextCompare: false) != 0) & ProgramRun) | (ProgramRun & EngPass)) && ControlLevel == 0)
			{
				ItemName = "SpeedMetersPerMin";
				MyProject.Forms.KeyPadEnter.SetLocation(SpeedInd.Left, checked(SpeedInd.Top - MyProject.Forms.KeyPadEnter.Height));
				MyProject.Forms.KeyPadEnter.Button30.Visible = true;
				RunKeyPad();
