	private void RemoteSpeedMetersPerMin()
	{
		float num = Conversions.ToSingle(Speed_mph.Text);
		if (Math.Round(num, 0) - (double)num != 0.0)
		{
		}
		num = ((Operators.CompareString(mphLabel.Text, MilesPerHour, TextCompare: false) == 0) ? ((float)(Math.Round((double)num * 1.60934, 0) * 10.0)) : ((Operators.CompareString(mphLabel.Text, MetersPerMin, TextCompare: false) != 0) ? ((float)Math.Round(num * 60f * 60f / 1000f * 10f, 0)) : ((float)Math.Round(num * 60f / 1000f * 10f, 0))));
		checked
		{
			if (num <= (float)DisplayLevels)
			{
				short num2 = (short)(IndexProgram1 + 1);
				for (short num3 = num2; num3 <= 60; num3 = (short)unchecked(num3 + 1))
				{
					Interaction.SaveSetting("Treadmill", "Speed", num3.ToString(), num.ToString());
				}
				SpeedSelectG8ColourCheck((int)Math.Round(num));
				NewSpeed(SpeedProgramSet, NewProgram: false);
				if (ProgramRun)
				{
					IOPOT.UpdateSpeed(IndexProgram1 + 1, ProgramHold, ProgramReset);
				}
			}
		}
	}

	private void RemoteSpeedkmh()
	{
		float num = Conversions.ToSingle(Speed_kmh.Text);
		float num2 = (float)(Math.Round(num, 0) - (double)num);
		if (Math.Round(num, 0) - (double)num != 0.0)
		{
			num = (float)Math.Round(num * 10f, 0);
		}
		checked
		{
			if (num <= (float)DisplayLevels)
			{
				short num3 = (short)(IndexProgram1 + 1);
				for (short num4 = num3; num4 <= 60; num4 = (short)unchecked(num4 + 1))
				{
					Interaction.SaveSetting("Treadmill", "Speed", num4.ToString(), num.ToString());
				}
				SpeedSelectG8ColourCheck((int)Math.Round(num));
				NewSpeed(SpeedProgramSet, NewProgram: false);
				if (ProgramRun)
				{
					IOPOT.UpdateSpeed(IndexProgram1 + 1, ProgramHold, ProgramReset);
				}
			}
		}
	}

