			string setting = Interaction.GetSetting("Machine", "Passed", "MpgOrMm", MilesPerHour);
			if (Operators.CompareString(setting, MilesPerHour, TextCompare: false) == 0)
			{
				MphOrMm(MetersPerMin);
			}
			else if (Operators.CompareString(setting, MetersPerMin, TextCompare: false) == 0)
			{
				MphOrMm(MetersPerSec);
			}
			else
			{
