	private void MphOrMm(string Label)
	{
		if (Operators.CompareString(Label, MetersPerMin, TextCompare: false) == 0)
		{
			ControlAChange("SpeedInd", "mphLabel", "Text", MetersPerMin);
			ControlAChange("DistanceInd", "MilesLabel", "Text", Meterstxt);
			ControlBChange("SpeedProgram", "MaxSpeed", "mihLabelSP", "Text", MetersPerMin);
			Interaction.SaveSetting("Machine", "Passed", "MpgOrMm", MetersPerMin);
		}
		else if (Operators.CompareString(Label, MetersPerSec, TextCompare: false) == 0)
		{
			ControlAChange("SpeedInd", "mphLabel", "Text", MetersPerSec);
			ControlAChange("DistanceInd", "MilesLabel", "Text", Meterstxt);
			ControlBChange("SpeedProgram", "MaxSpeed", "mihLabelSP", "Text", MetersPerSec);
			Interaction.SaveSetting("Machine", "Passed", "MpgOrMm", MetersPerSec);
		}
		else
		{
			ControlAChange("SpeedInd", "mphLabel", "Text", MilesPerHour);
			ControlAChange("DistanceInd", "MilesLabel", "Text", Milestxt);
			ControlBChange("SpeedProgram", "MaxSpeed", "mihLabelSP", "Text", MilesPerHour);
			Interaction.SaveSetting("Machine", "Passed", "MpgOrMm", MilesPerHour);
		}
	}

