	private void SpeedSelectG8_Click(object sender, EventArgs e)
	{
		if ((!NoChanges & (ControlLevel == 0) & ProgramRun & !ProgramHold) | (!NoChanges & (ControlLevel == 0) & !ProgramRun & !ProgramHold) | (!NoChanges & (ControlLevel == 0) & RemoteProgramRun & !ProgramHold) | (!NoChanges & (ControlLevel == 0) & !ProgramRun & (Operators.CompareString(((Button)sender).Name, "SpeedSelect" + Conversions.ToString(0), TextCompare: false) == 0)) | (!NoChanges & (ControlLevel == 0) & !RemoteProgramRun & (Operators.CompareString(((Button)sender).Name, "SpeedSelect" + Conversions.ToString(0), TextCompare: false) == 0)))
		{
			DisplayOn = true;
			byte b = 0;
			do
			{
				checked
				{
					if (Operators.CompareString(((Button)sender).Name, "SpeedSelect" + Conversions.ToString(b), TextCompare: false) == 0)
					{
						if (Operators.CompareString(RemoteControl, "REMOTE", TextCompare: false) != 0)
						{
							RemoteSpeedSelectG8((int)Math.Round(Conversion.Val(base.Controls["SpeedProgram"].Controls["SpeedSelectG8"].Controls["SpeedSelect" + Conversions.ToString(b)].Text) * 10.0));
							break;
						}
						if (Operators.CompareString(RemoteControl, "REMOTE", TextCompare: false) == 0)
						{
							Functions.RegUpdate("Dtread", "Treadmill", "SendC", Functions.RegUpdate("Dtread", "Treadmill", "SendC", "", "Get") + ", RSSG" + Conversions.ToString(b * 10), "Save");
						}
						SpeedSelectG8Colour(b);
					}
					b = (byte)unchecked((uint)(b + 1));
				}
			}
			while ((uint)b <= 10u);
		}
		else if (!NoChangesTM.Enabled)
		{
			NoChangesTM.Enabled = true;
		}
	}

	private void RemoteSpeedSelectG8(int Index)
	{
		RSSGCancell = Index.ToString();
		if ((ProgramRun & ProgramHold) && Index > 0)
		{
			HoldSpeed = Index;
		}
		SpeedSelectG8ColourCheck(Index);
		checked
		{
			byte b = (byte)(IndexProgram1 + 1);
			byte b2 = b;
			while (unchecked((uint)b2) <= 60u)
			{
				Interaction.SaveSetting("Treadmill", "Speed", b2.ToString(), Index.ToString());
				b2 = (byte)unchecked((uint)(b2 + 1));
			}
			NewSpeed(SpeedProgramSet, NewProgram: false);
			if ((IOPOTCommsActive & ProgramRun) | (TestEStop & ProgramRun))
			{
				IOPOT.UpdateSpeed(IndexProgram1 + 1, ProgramHold, ProgramReset);
			}
			else if (!ProgramReset)
			{
				ZeroIndicators();
			}
		}
	}

	private void SpeedSelectG8ColourCheck(int Speed)
	{
		if ((double)Speed < Conversion.Val(base.Controls["SpeedProgram"].Controls["SpeedSelectG8"].Controls["SpeedSelect" + Conversions.ToString(1)].Text) * 10.0)
		{
			SpeedSelectG8Colour(0);
		}
		else if ((double)Speed < Conversion.Val(base.Controls["SpeedProgram"].Controls["SpeedSelectG8"].Controls["SpeedSelect" + Conversions.ToString(2)].Text) * 10.0)
		{
			SpeedSelectG8Colour(1);
		}
		else if ((double)Speed < Conversion.Val(base.Controls["SpeedProgram"].Controls["SpeedSelectG8"].Controls["SpeedSelect" + Conversions.ToString(3)].Text) * 10.0)
		{
			SpeedSelectG8Colour(2);
		}
		else if ((double)Speed < Conversion.Val(base.Controls["SpeedProgram"].Controls["SpeedSelectG8"].Controls["SpeedSelect" + Conversions.ToString(4)].Text) * 10.0)
		{
			SpeedSelectG8Colour(3);
		}
		else if ((double)Speed < Conversion.Val(base.Controls["SpeedProgram"].Controls["SpeedSelectG8"].Controls["SpeedSelect" + Conversions.ToString(5)].Text) * 10.0)
		{
			SpeedSelectG8Colour(4);
		}
		else if ((double)Speed < Conversion.Val(base.Controls["SpeedProgram"].Controls["SpeedSelectG8"].Controls["SpeedSelect" + Conversions.ToString(6)].Text) * 10.0)
		{
			SpeedSelectG8Colour(5);
		}
		else if ((double)Speed < Conversion.Val(base.Controls["SpeedProgram"].Controls["SpeedSelectG8"].Controls["SpeedSelect" + Conversions.ToString(7)].Text) * 10.0)
		{
			SpeedSelectG8Colour(6);
		}
		else if ((double)Speed < Conversion.Val(base.Controls["SpeedProgram"].Controls["SpeedSelectG8"].Controls["SpeedSelect" + Conversions.ToString(8)].Text) * 10.0)
		{
			SpeedSelectG8Colour(7);
		}
		else if ((double)Speed < Conversion.Val(base.Controls["SpeedProgram"].Controls["SpeedSelectG8"].Controls["SpeedSelect" + Conversions.ToString(9)].Text) * 10.0)
		{
			SpeedSelectG8Colour(8);
		}
		else if ((double)Speed < Conversion.Val(base.Controls["SpeedProgram"].Controls["SpeedSelectG8"].Controls["SpeedSelect" + Conversions.ToString(10)].Text) * 10.0)
		{
			SpeedSelectG8Colour(9);
		}
		else
		{
			SpeedSelectG8Colour(10);
		}
	}

	private void SpeedSelectG8Colour(int Index)
	{
		double num = ((DisplayLevels <= 0) ? 1.0 : Math.Round((double)DisplayLevels / 10.0, 1));
		Interaction.SaveSetting("Treadmill", "Speed", "RSSS", Index.ToString());
		byte b = 0;
		do
		{
			SelectG8Colour("SpeedSelect" + b, "SpeedSelectG8", "SpeedProgram", "False");
			if (num >= (double)(int)b || ((double)(int)b - num > 0.0 && (double)(int)b - num < 1.0))
			{
				ControlBChange("SpeedProgram", "SpeedSelectG8", "SpeedSelect" + b, "Visible", "True");
			}
			else
			{
				ControlBChange("SpeedProgram", "SpeedSelectG8", "SpeedSelect" + b, "Visible", "False");
			}
			if ((double)(int)b > num && (double)(int)b < num + 1.0)
			{
				ControlBChange("SpeedProgram", "SpeedSelectG8", "SpeedSelect" + b, "Text", Conversions.ToString(num));
			}
			checked
			{
				b = (byte)unchecked((uint)(b + 1));
			}
		}
		while ((uint)b <= 10u);
		SelectG8Colour("SpeedSelect" + Index, "SpeedSelectG8", "SpeedProgram", "True");
	}

