				RGSGCancell = Index.ToString();
				GradientSelectG8ColourCheck(Index);
				byte b = (byte)(IndexProgram1 + 1);
				byte b2 = b;
				while (unchecked((uint)b2) <= 60u)
				{
					Interaction.SaveSetting(Setting: Conversions.ToString((Index <= 111) ? Index : 111), AppName: "Treadmill", Section: "GradientPlus", Key: b2.ToString());
					b2 = (byte)unchecked((uint)(b2 + 1));
				}
				NewGradient(GradientProgramSet, NewProgram: false);
				if ((IOPOTCommsActive & ProgramRun) | (TestEStop & ProgramRun))
				{
					IOPOT.UpdateGradient(IndexProgram1 + 1, ProgramHold, ProgramReset);
				}
			}
			catch (Exception ex)
			{
				ProjectData.SetProjectError(ex);
				Exception ex2 = ex;
				ProjectData.ClearProjectError();
			}
		}
