	private void SelectG8Colour(string ControlName, string ControlContainer, string ControlContainerA, string SetColor)
	{
		try
		{
			if (base.Controls[ControlContainerA].Controls[ControlContainer].Controls[ControlName].InvokeRequired)
			{
				SetControl3Callback method = SelectG8Colour;
				Invoke(method, ControlName, ControlContainer, ControlContainerA, SetColor);
			}
			else if (Operators.CompareString(SetColor, "False", TextCompare: false) == 0)
			{
				base.Controls[ControlContainerA].Controls[ControlContainer].Controls[ControlName].BackColor = Color.DarkViolet;
			}
			else
			{
				base.Controls[ControlContainerA].Controls[ControlContainer].Controls[ControlName].BackColor = Color.OrangeRed;
			}
		}
		catch (Exception ex)
		{
			ProjectData.SetProjectError(ex);
			Exception ex2 = ex;
			ProjectData.ClearProjectError();
		}
	}

