	public void ReadDisplayRemoteData()
	{
		string drive = LanMapDrive + ":";
		string direct = "\\RMC";
		string path = "\\RemoteDisplay.txt";
		string text = "";
		text = Functions.ReadRemoteFile(drive, direct, path, CheckExist: false);
		if (RemoteOK)
		{
			RemoteData(text);
		}
	}

	private void RemoteRead_Tick(object sender, EventArgs e)
	{
		RemoteRead.Dispose();
		if (WIFI.WiFiOk)
		{
			if (Operators.CompareString(RemoteControl, "REMOTE", TextCompare: false) == 0)
			{
				if ((object)Functions.RegUpdate("Dtread", "Treadmill", "DemandD", "", "Get") != "")
				{
					RemoteData(Functions.RegUpdate("Dtread", "Treadmill", "DemandD", "", "Get"));
				}
				if ((object)Functions.RegUpdate("Dtread", "Treadmill", "DemandB", "", "Get") != "")
				{
					RemoteButtons(Functions.RegUpdate("Dtread", "Treadmill", "DemandB", "", "Get"));
				}
			}
			else if ((object)Functions.RegUpdate("Dtread", "Treadmill", "DemandC", "", "Get") != "")
			{
				RemoteDemand(Functions.RegUpdate("Dtread", "Treadmill", "DemandC", "", "Get"));
			}
		}
		else
		{
			RemoteIndColourChange("Red");
		}
	}

	public void RemoteData(string message)
	{
		Functions.RegUpdate("Dtread", "Treadmill", "DemandD", "", "Save");
		checked
		{
			if ((Operators.CompareString(message, "Failed", TextCompare: false) != 0) & (Operators.CompareString(message, "", TextCompare: false) != 0))
			{
				Array array = Strings.Split(message, "!");
				int num = Microsoft.VisualBasic.Information.UBound(array);
				int num2 = num;
				bool flag = default(bool);
				for (int i = 0; i <= num2; i++)
				{
					if (!((i == 0) | ((i > 0) & SerialNoEqual & ProgramAtth)))
					{
						continue;
					}
					switch (i)
					{
					case 0:
						if (Operators.CompareString(Interaction.GetSetting("DTread", "Aqua", "SerialNo", "1350"), Strings.Mid(Conversions.ToString(array.GetValue(i)), 2, Strings.Len(Conversions.ToString(array.GetValue(i)))), TextCompare: false) != 0)
						{
							SerialNoEqual = false;
						}
						else
						{
							SerialNoEqual = true;
						}
						break;
					case 1:
						if (Operators.CompareString(RemoteStartImage, Strings.Mid(Conversions.ToString(array.GetValue(i)), 2, Strings.Len(Conversions.ToString(array.GetValue(i)))), TextCompare: false) != 0)
						{
							ProgramRemoteImage(Strings.Mid(Conversions.ToString(array.GetValue(i)), 2, Strings.Len(Conversions.ToString(array.GetValue(i)))));
						}
						break;
					case 2:
						if (Operators.CompareString(RemoteEditImage, Strings.Mid(Conversions.ToString(array.GetValue(i)), 2, Strings.Len(Conversions.ToString(array.GetValue(i)))), TextCompare: false) != 0)
						{
							ProgramRemoteImage(Strings.Mid(Conversions.ToString(array.GetValue(i)), 2, Strings.Len(Conversions.ToString(array.GetValue(i)))));
						}
						break;
					case 3:
						Speed_kmhChange(Strings.Mid(Conversions.ToString(array.GetValue(i)), 2, Strings.Len(Conversions.ToString(array.GetValue(i)))));
						break;
					case 4:
						Speed_mphChange(Strings.Mid(Conversions.ToString(array.GetValue(i)), 2, Strings.Len(Conversions.ToString(array.GetValue(i)))));
						break;
					case 5:
						Distance_kmChange(Strings.Mid(Conversions.ToString(array.GetValue(i)), 2, Strings.Len(Conversions.ToString(array.GetValue(i)))));
						break;
					case 6:
						Distance_miChange(Strings.Mid(Conversions.ToString(array.GetValue(i)), 2, Strings.Len(Conversions.ToString(array.GetValue(i)))));
						break;
					case 7:
						if (!InfoEnterTM.Enabled)
						{
							SetDurationChange(Strings.Mid(Conversions.ToString(array.GetValue(i)), 2, Strings.Len(Conversions.ToString(array.GetValue(i)))));
						}
						break;
					case 8:
						DurationIndChange(Strings.Mid(Conversions.ToString(array.GetValue(i)), 2, Strings.Len(Conversions.ToString(array.GetValue(i)))));
						break;
					case 9:
						if (!InfoEnterTM.Enabled)
						{
							ControlAChange("WaterDepth", "WaterDepthInd", "Text", Strings.Mid(Conversions.ToString(array.GetValue(i)), 2, Strings.Len(Conversions.ToString(array.GetValue(i)))));
						}
						break;
					case 10:
						WaterDepthActualChange(Strings.Mid(Conversions.ToString(array.GetValue(i)), 2, Strings.Len(Conversions.ToString(array.GetValue(i)))));
						break;
					case 11:
						WaterTempIndChange(Strings.Mid(Conversions.ToString(array.GetValue(i)), 2, Strings.Len(Conversions.ToString(array.GetValue(i)))));
						break;
					case 12:
						SCLabelChange(MaxSpeedtxt + " " + Strings.Mid(Conversions.ToString(array.GetValue(i)), 2, Strings.Len(Conversions.ToString(array.GetValue(i)))) + " " + KilometersPerHour);
						break;
					case 13:
						MaxSpeedIndkmChange(Strings.Mid(Conversions.ToString(array.GetValue(i)), 2, Strings.Len(Conversions.ToString(array.GetValue(i)))));
						break;
					case 14:
						MaxSpeedIndMilesChange(Strings.Mid(Conversions.ToString(array.GetValue(i)), 2, Strings.Len(Conversions.ToString(array.GetValue(i)))));
						break;
					case 15:
						ICLabelChange(MaxInclinetxt + " " + Strings.Mid(Conversions.ToString(array.GetValue(i)), 2, Strings.Len(Conversions.ToString(array.GetValue(i)))) + " %");
						break;
					case 16:
						InclinePercentageChange(Strings.Mid(Conversions.ToString(array.GetValue(i)), 2, Strings.Len(Conversions.ToString(array.GetValue(i)))));
						break;
					case 17:
						InclineDegChange(Strings.Mid(Conversions.ToString(array.GetValue(i)), 2, Strings.Len(Conversions.ToString(array.GetValue(i)))));
						break;
					case 18:
						InclineActualChange(Strings.Mid(Conversions.ToString(array.GetValue(i)), 2, Strings.Len(Conversions.ToString(array.GetValue(i)))));
						break;
					case 19:
						CleanWorkChange(Strings.Mid(Conversions.ToString(array.GetValue(i)), 2, Strings.Len(Conversions.ToString(array.GetValue(i)))));
						break;
					case 20:
						SpeedSelectG8Colour(Conversions.ToInteger(Strings.Mid(Conversions.ToString(array.GetValue(i)), 2, Strings.Len(Conversions.ToString(array.GetValue(i))))));
						break;
					case 21:
						GradientSelectG8Colour(Conversions.ToInteger(Strings.Mid(Conversions.ToString(array.GetValue(i)), 2, Strings.Len(Conversions.ToString(array.GetValue(i))))));
						break;
					case 22:
						if (Operators.CompareString(Interaction.GetSetting("DTread", "Aqua", "Incline", "False"), Strings.Mid(Conversions.ToString(array.GetValue(i)), 2, Strings.Len(Conversions.ToString(array.GetValue(i)))), TextCompare: false) != 0)
						{
							if (Operators.CompareString(Interaction.GetSetting("DTread", "Aqua", "Incline", "False"), "False", TextCompare: false) == 0)
							{
								Interaction.SaveSetting("DTread", "Aqua", "Incline", "True");
								flag = true;
							}
							else
							{
								Interaction.SaveSetting("DTread", "Aqua", "Incline", "False");
								flag = true;
							}
						}
						break;
					case 23:
						if (Operators.CompareString(Strings.Mid(Conversions.ToString(array.GetValue(i)), 2, Strings.Len(Conversions.ToString(array.GetValue(i)))), "True", TextCompare: false) == 0)
						{
							Interaction.SaveSetting("DTread", "Aqua", "Jet", "True");
						}
						else
