	private void RemoteIndColourChange(string SetColor)
	{
		if (RemoteInd.InvokeRequired)
		{
			SetControlCallback method = RemoteIndColourChange;
			Invoke(method, SetColor);
			return;
		}
		switch (SetColor)
		{
		case "Transparent":
			RemoteInd.ForeColor = Color.Transparent;
			break;
		case "Red":
			RemoteInd.ForeColor = Color.Red;
			break;
		case "Control":
			RemoteInd.ForeColor = Color.FromArgb(128, 255, 255);
			break;
		}
	}

