	public void RemoteButtons(string Message)
	{
		int num = 0;
		int num2 = 0;
		Functions.RegUpdate("Dtread", "Treadmill", "DemandB", "", "Save");
		Array array = Strings.Split(Message, ",");
		int num3 = Microsoft.VisualBasic.Information.UBound(array);
		MainProgramSerialNo = Conversions.ToString(array.GetValue(0));
		if (Operators.CompareString(MainProgramSerialNo, SerialNo, TextCompare: false) == 0)
		{
			RemoteOK = true;
		}
		else
		{
			RemoteOK = false;
		}
		checked
		{
			if (RemoteOK)
			{
				ProgramMaxSpeed = Conversions.ToInteger(array.GetValue(1));
				if ((ProgramNumSpeed != Conversions.ToInteger(array.GetValue(3))) | (MaxSpeedSet != Conversions.ToSingle(array.GetValue(2))))
				{
					MaxSpeedSet = Conversions.ToSingle(array.GetValue(2));
					NewSpeed(Conversions.ToInteger(array.GetValue(3)), NewProgram: false);
				}
				ProgramMaxGradient = Conversions.ToDouble(array.GetValue(4));
				if ((ProgramNumGradient != Conversions.ToInteger(array.GetValue(6))) | (MaxGradientSet != Conversions.ToSingle(array.GetValue(5))))
				{
					int num4 = Conversions.ToInteger(array.GetValue(5));
					int num5 = Conversions.ToInteger(array.GetValue(6));
					MaxGradientSet = Conversions.ToSingle(array.GetValue(5));
					NewGradient(Conversions.ToInteger(array.GetValue(6)), NewProgram: false);
				}
				int num6 = num3 - 2;
				for (num = 7; num <= num6; num += 2)
				{
					num2++;
					if (num2 < 61)
					{
						if (Operators.CompareString(Conversions.ToString(array.GetValue(num)), "Coral", TextCompare: false) == 0)
						{
							ButtonColourChange("SpeedProgram", "Button" + num2, "Coral");
						}
						if (Operators.CompareString(Conversions.ToString(array.GetValue(num)), "Yellow", TextCompare: false) == 0)
						{
							ButtonColourChange("SpeedProgram", "Button" + num2, "Yellow");
						}
						if (Operators.CompareString(Conversions.ToString(array.GetValue(num)), "Control", TextCompare: false) == 0)
						{
							ButtonColourChange("SpeedProgram", "Button" + num2, "Control");
						}
						if (ProgramNumSpeed == 0)
						{
							int num7 = (int)Math.Round(SpeedMaxHeightCal / (float)ProgramMaxSpeed / 16f * MaxSpeedSet * Conversions.ToSingle(array.GetValue(num + 1)) + SpeedBaseHeight);
							ControlAChange("SpeedProgram", "Button" + Conversions.ToString(num2), "Top", (SpeedNewAdjust - num7).ToString());
							ControlAChange("SpeedProgram", "Button" + Conversions.ToString(num2), "Height", num7.ToString());
						}
					}
					else if (num2 < 121)
					{
						if (Operators.CompareString(Conversions.ToString(array.GetValue(num)), "Coral", TextCompare: false) == 0)
						{
							ButtonColourChange("GradientProgram", "Button" + num2, "Coral");
						}
						if (Operators.CompareString(Conversions.ToString(array.GetValue(num)), "Yellow", TextCompare: false) == 0)
						{
							ButtonColourChange("GradientProgram", "Button" + num2, "Yellow");
						}
						if (Operators.CompareString(Conversions.ToString(array.GetValue(num)), "Control", TextCompare: false) == 0)
						{
							ButtonColourChange("GradientProgram", "Button" + num2, "Control");
						}
						if (ProgramNumGradient == 0)
						{
							int num8 = (int)Math.Round((float)(int)Math.Round((double)GradientMaxHeightCal / ProgramMaxGradient / 16.0 * (double)MaxGradientSet) * Conversions.ToSingle(array.GetValue(num + 1)) + GradientBaseHeight);
							ControlAChange("GradientProgram", "Button" + Conversions.ToString(num2), "Top", (GradientNewAdjust - num8).ToString());
							ControlAChange("GradientProgram", "Button" + Conversions.ToString(num2), "Height", num8.ToString());
						}
					}
				}
			}
			Thread.Sleep(10);
		}
	}

