	private void WaterDepthIndChange(string Setting, string Data)
	{
		try
		{
			if (WaterDepthInd.InvokeRequired)
			{
				SetControl1Callback method = WaterDepthIndChange;
				Invoke(method, Setting, Data);
				return;
			}
			if (Operators.CompareString(Setting, "TextAlign", TextCompare: false) == 0)
			{
				if (Operators.CompareString(Data, "Left", TextCompare: false) != 0)
				{
					if (Operators.CompareString(Data, "Center", TextCompare: false) == 0)
					{
						WaterDepthInd.TextAlign = ContentAlignment.TopCenter;
					}
				}
				else
				{
					WaterDepthInd.TextAlign = (ContentAlignment)0;
				}
			}
			if (Operators.CompareString(Setting, "ContentAlign", TextCompare: false) == 0)
			{
				if (Operators.CompareString(Data, "Middle", TextCompare: false) == 0)
				{
					WaterDepthInd.TextAlign = ContentAlignment.MiddleCenter;
				}
			}
		}
		catch (Exception ex)
		{
			ProjectData.SetProjectError(ex);
			Exception ex2 = ex;
			ProjectData.ClearProjectError();
		}
	}

	private void SetMemorystick()
	{
		try
		{
			PluggedInQuery = new WqlEventQuery
			{
				QueryString = "SELECT * FROM Win32_VolumeChangeEvent WHERE EventType = 2"
			};
			PluggedInWatcher = new ManagementEventWatcher(PluggedInQuery);
			PluggedInWatcher.Start();
			PluggedOutQuery = new WqlEventQuery
			{
				QueryString = "SELECT * FROM Win32_VolumeChangeEvent WHERE EventType = 3"
			};
			PluggedOutWatcher = new ManagementEventWatcher(PluggedOutQuery);
			PluggedOutWatcher.Start();
		}
		catch (Exception ex)
		{
			ProjectData.SetProjectError(ex);
			Exception ex2 = ex;
			Interaction.MsgBox(ex2.Message);
			ProjectData.ClearProjectError();
		}
	}

