	private void OnChanged(object source, FileSystemEventArgs e)
	{
		WatcherChangeTypes changeType = e.ChangeType;
		string mainDirName = Functions.GetMainDirName();
		string text = "C:\\Users\\" + mainDirName + "\\Onedrive";
		string text2 = "\\" + SerialNo + "\\HydroTrain.jmf";
		string text3 = Functions.GoogleDriveCheck();
		string text4 = Functions.PublicDriveCheck();
		switch (changeType)
		{
		case WatcherChangeTypes.Created:
		{
			string fullPath2 = e.FullPath;
			if (Operators.CompareString(fullPath2, text + text2, TextCompare: false) == 0)
			{
				UpdateVersionProgram = false;
				PCDCounter = 3;
			}
			else if (Operators.CompareString(fullPath2, text3 + text2, TextCompare: false) == 0)
			{
				UpdateVersionProgram = false;
				PCDCounter = 3;
			}
			else if (Operators.CompareString(fullPath2, text4 + text2, TextCompare: false) == 0)
			{
				UpdateVersionProgram = false;
				PCDCounter = 3;
			}
			else if (Operators.CompareString(fullPath2, LanMapDrive + ":\\RMC\\RemoteDisplay.txt", TextCompare: false) != 0 && Operators.CompareString(fullPath2, LanMapDrive + ":\\RMC\\RemoteButtons.txt", TextCompare: false) != 0)
			{
			}
			break;
		}
		case WatcherChangeTypes.Deleted:
		{
			string fullPath = e.FullPath;
			if (Operators.CompareString(fullPath, LanMapDrive + ":\\Public\\RMC\\Remote.txt", TextCompare: false) != 0 && Operators.CompareString(fullPath, "C:\\Users\\Public\\RMC\\RemoteDisplay.txt", TextCompare: false) != 0 && Operators.CompareString(fullPath, "C:\\Users\\Public\\RMC\\RemoteButtons.txt", TextCompare: false) != 0)
			{
			}
			break;
		}
		case WatcherChangeTypes.Changed:
			ProgramControlDataOneDrive();
			break;
		}
	}

	private void OnRenamed(object source, RenamedEventArgs e)
	{
		WatcherChangeTypes changeType = e.ChangeType;
	}

	private void OnError(object source, ErrorEventArgs e)
	{
		Console.WriteLine("The FileSystemWatcher has detected an error");
		if (e.GetException() is InternalBufferOverflowException)
		{
			Console.WriteLine("The file system watcher experienced an internal buffer overflow: " + e.GetException().Message);
		}
	}

