		{
			ButtonProgramStart();
		}
	}

	public void RemoteDemand(string FileStream)
	{
		Array array = Strings.Split(FileStream, ",");
		if (Microsoft.VisualBasic.Information.UBound(array) >= 1000)
		{
			return;
		}
		int num = Microsoft.VisualBasic.Information.UBound(array);
		int num2 = num;
		checked
		{
			for (int i = 0; i <= num2; i++)
			{
				switch (Conversions.ToString(array.GetValue(i)))
				{
				case "PS":
					DoBoxChange("RemoteProgramStart");
					continue;
				case "EDIT":
					DoBox2Change("RemoteProgramEdit1");
					continue;
				case "SPM":
					DoBoxChange("SpeedProgramManual");
					continue;
				case "SPU":
					DoBoxChange("SpeedProgramUp_Control");
					continue;
				case "SPD":
					DoBoxChange("SpeedProgramDN_Control");
					continue;
				case "GPM":
					DoBoxChange("GradientProgramManual");
					continue;
				case "GPU":
					DoBoxChange("GradientProgramUp_Control");
					continue;
				case "GPD":
					DoBoxChange("GradientProgramDN_Control");
					continue;
				case "RSU":
					DoBoxChange("RemoteSpeedUp");
					continue;
				case "RSD":
					DoBoxChange("RemoteSpeedDown");
					continue;
				case "RGU":
					DoBoxChange("RemoteGradientUp");
					continue;
				case "RGD":
					DoBoxChange("RemoteGradientDown");
					continue;
				case "WDS":
					DoBoxChange("WaterDepthSw");
					continue;
				case "RWDD":
					DoBoxChange("RemoteWaterDepthDown");
					continue;
				case "RWDU":
					DoBoxChange("RemoteWaterDepthUp");
					continue;
				case "WDSL":
					ControlAChange("WaterDepth", "WaterDepthInd", "Text", "0");
					DoBoxChange("RemoteWaterDepthSetting");
					continue;
				case "RJ":
					DoBoxChange("RemoteJetOnOff");
					continue;
				case "RL":
					DoBoxChange("RemoteLightOnOff");
					continue;
				case "RC":
					DoBoxChange("RemoteCineOnOff");
					continue;
				case "COOR":
					DoBoxChange("CleanOnOffRemote");
					continue;
				case "LIST":
					DoBoxChange("List");
					continue;
				case "CLOSELIST":
					DoBoxChange("CloseList");
					continue;
				case "NIL":
					continue;
				}
				if (Operators.CompareString(Strings.Mid(Conversions.ToString(array.GetValue(i)), 1, 4), "RWDS", TextCompare: false) == 0)
				{
					ControlAChange("WaterDepth", "WaterDepthInd", "Text", Strings.Mid(Conversions.ToString(array.GetValue(i)), 5, Strings.Len(Conversions.ToString(array.GetValue(i))) - 4));
					DoBoxChange("RemoteWaterDepthSetting");
				}
				if (Operators.CompareString(Strings.Mid(Conversions.ToString(array.GetValue(i)), 1, 4), "RDTS", TextCompare: false) == 0)
				{
					DoBox2Change(Conversions.ToString(array.GetValue(i)));
				}
				if (Operators.CompareString(Strings.Mid(Conversions.ToString(array.GetValue(i)), 1, 4), "RSSG", TextCompare: false) == 0)
				{
					DoBox2Change(Conversions.ToString(array.GetValue(i)));
				}
				if (Operators.CompareString(Strings.Mid(Conversions.ToString(array.GetValue(i)), 1, 4), "RGSG", TextCompare: false) == 0)
				{
					DoBox2Change(Conversions.ToString(array.GetValue(i)));
				}
				if (Operators.CompareString(Strings.Mid(Conversions.ToString(array.GetValue(i)), 1, 4), "SID", TextCompare: false) == 0)
				{
					DoBox2Change(Conversions.ToString(array.GetValue(i)));
				}
				if (Operators.CompareString(Strings.Mid(Conversions.ToString(array.GetValue(i)), 1, 5), "PNAME", TextCompare: false) == 0)
				{
					DoBox2Change(Conversions.ToString(array.GetValue(i)));
				}
				if (Operators.CompareString(Strings.Mid(Conversions.ToString(array.GetValue(i)), 1, 5), "DNAME", TextCompare: false) == 0)
				{
					DoBox2Change(Conversions.ToString(array.GetValue(i)));
				}
				if (Operators.CompareString(Strings.Mid(Conversions.ToString(array.GetValue(i)), 1, 3), "DOB", TextCompare: false) == 0)
				{
					DoBox2Change(Conversions.ToString(array.GetValue(i)));
				}
				if (Operators.CompareString(Strings.Mid(Conversions.ToString(array.GetValue(i)), 1, 3), "REF", TextCompare: false) == 0)
				{
					DoBox2Change(Conversions.ToString(array.GetValue(i)));
				}
				if (Operators.CompareString(Strings.Mid(Conversions.ToString(array.GetValue(i)), 1, 3), "SEX", TextCompare: false) == 0)
				{
					DoBox2Change(Conversions.ToString(array.GetValue(i)));
				}
				if (Operators.CompareString(Strings.Mid(Conversions.ToString(array.GetValue(i)), 1, 2), "ID", TextCompare: false) == 0)
				{
					DoBox2Change(Conversions.ToString(array.GetValue(i)));
				}
				if (Operators.CompareString(Strings.Mid(Conversions.ToString(array.GetValue(i)), 1, 5), "BREED", TextCompare: false) == 0)
				{
					DoBox2Change(Conversions.ToString(array.GetValue(i)));
				}
				if (Operators.CompareString(Strings.Mid(Conversions.ToString(array.GetValue(i)), 1, 9), "IMPORTANT", TextCompare: false) == 0)
				{
					DoBox2Change(Conversions.ToString(array.GetValue(i)));
				}
				if (Operators.CompareString(Strings.Mid(Conversions.ToString(array.GetValue(i)), 1, 6), "WEIGHT", TextCompare: false) == 0)
				{
					DoBox2Change(Conversions.ToString(array.GetValue(i)));
				}
				if (Operators.CompareString(Strings.Mid(Conversions.ToString(array.GetValue(i)), 1, 6), "HEIGHT", TextCompare: false) == 0)
				{
					DoBox2Change(Conversions.ToString(array.GetValue(i)));
				}
				if (Operators.CompareString(Strings.Mid(Conversions.ToString(array.GetValue(i)), 1, 7), "TRAINER", TextCompare: false) == 0)
				{
					DoBox2Change(Conversions.ToString(array.GetValue(i)));
				}
				Thread.Sleep(50);
			}
			Functions.RegUpdate("Dtread", "Treadmill", "DemandC", "", "Save");
		}
	}

	public void ToDo(string DoIt)
	{
		switch (DoIt)
		{
		case "WriteMachineHistory":
			WriteMachineHistory();
			break;
		case "RemoteProgramStart":
			RemoteProgramStart();
			break;
		case "SpeedProgramManual":
			SpeedProgramManual();
			break;
		case "SpeedProgramUp_Control":
			SpeedProgramUp_Control();
			break;
		case "SpeedProgramDN_Control":
			SpeedProgramDN_Control();
			break;
		case "GradientProgramDN_Control":
			GradientProgramDN_Control();
			break;
		case "GradientProgramManual":
			GradientProgramManual();
			break;
		case "GradientProgramUp_Control":
			GradientProgramUp_Control();
			break;
		case "RemoteSpeedUp":
			RemoteSpeedUp();
			break;
		case "RemoteSpeedDown":
			RemoteSpeedDown();
			break;
		case "RemoteGradientUp":
			RemoteGradientUp();
			break;
		case "RemoteGradientDown":
			RemoteGradientDown();
			break;
		case "RemoteWaterDepthDown":
			RemoteWaterDepthDown();
			break;
		case "RemoteWaterDepthUp":
			RemoteWaterDepthUp();
			break;
		case "WaterDepthSw":
			WaterDepthSw();
			break;
		case "RemoteJetOnOff":
			RemoteJetOnOff();
			break;
		case "RemoteLightsOnOff":
			RemoteLightsOnOff();
			break;
		case "RemoteCineOnOff":
			RemoteCineOnOff();
			break;
		case "CleanOnOffRemote":
			CleanOnOffRemote();
			break;
		case "RemoteWaterDepthSetting":
			RemoteWaterDepthSetting();
			break;
		case "RemoteSpeedMetersPerMin":
			RemoteSpeedMetersPerMin();
			break;
		case "RemoteSpeedkmh":
			RemoteSpeedkmh();
			break;
		case "List":
			ListView();
			break;
		case "CloseList":
			if (MyProject.Forms.NameListSort.Visible)
			{
				CloseList();
			}
			break;
		case "ShortTimerControl":
			ShortTimerControl();
			break;
		case "TimerBoxCycleControl":
			TimerBoxCycleControl();
			break;
		}
	}

