	public void DoBoxChange(string text)
	{
		try
		{
			if (DoBox.InvokeRequired)
			{
				SetDataCallback method = DoBoxChange;
				Invoke(method, text);
			}
			else
			{
				DoBox.Text = text;
				ToDo(text);
			}
		}
		catch (Exception ex)
		{
			ProjectData.SetProjectError(ex);
			Exception ex2 = ex;
			ProjectData.ClearProjectError();
		}
	}

	public void DoBox2Change(string text)
	{
		try
		{
			if (DoBox2.InvokeRequired)
			{
				SetDataCallback method = DoBox2Change;
				try
				{
					Invoke(method, text);
					return;
				}
				catch (Exception ex)
				{
					ProjectData.SetProjectError(ex);
					Exception ex2 = ex;
					ProjectData.ClearProjectError();
					return;
				}
			}
			DoBox2.Text = text;
			ToDo2(text);
		}
		catch (Exception ex3)
		{
			ProjectData.SetProjectError(ex3);
			Exception ex4 = ex3;
			ProjectData.ClearProjectError();
		}
	}

