			{
				RemoteProgramEdit(Conversions.ToInteger(Strings.Mid(ToDoBox, 18, Strings.Len(ToDoBox) - 17)));
			}
			if (Operators.CompareString(Strings.Mid(ToDoBox, 1, 4), "RDTS", TextCompare: false) == 0)
