	public void ControlXChange(string ControlName, string Setting, string DataA, string DataB)
	{
		try
		{
			if (base.Controls[ControlName].InvokeRequired)
			{
				SetControlACallback method = ControlXChange;
				Invoke(method, ControlName, Setting, DataA, DataB);
				return;
			}
			switch (Setting)
			{
			case "Text":
				base.Controls[ControlName].Text = DataA;
				break;
			case "Visible":
				if (Operators.CompareString(DataA, "False", TextCompare: false) == 0)
				{
					base.Controls[ControlName].Visible = false;
				}
				else
				{
					base.Controls[ControlName].Visible = true;
				}
				break;
			case "Enabled":
				if (Operators.CompareString(DataA, "False", TextCompare: false) == 0)
				{
					base.Controls[ControlName].Enabled = false;
				}
				else
				{
					base.Controls[ControlName].Enabled = true;
				}
				break;
			case "BackgroundImageLayout":
				if (Operators.CompareString(DataA, "Zoom", TextCompare: false) == 0)
				{
					base.Controls[ControlName].BackgroundImageLayout = ImageLayout.Zoom;
				}
				else
				{
					base.Controls[ControlName].BackgroundImageLayout = ImageLayout.Stretch;
				}
				break;
			case "ForeColor":
				if (Operators.CompareString(DataA, "Red", TextCompare: false) == 0)
				{
					base.Controls[ControlName].ForeColor = Color.Red;
				}
				else
				{
					base.Controls[ControlName].ForeColor = Color.FromArgb(128, 255, 255);
				}
				break;
			case "Tag":
				base.Controls[ControlName].Tag = DataA;
				break;
			case "Height":
				base.Controls[ControlName].Height = Conversions.ToInteger(DataA);
				break;
			case "Width":
				base.Controls[ControlName].Width = Conversions.ToInteger(DataA);
				break;
			case "Top":
				base.Controls[ControlName].Top = Conversions.ToInteger(DataA);
				break;
			case "Left":
				base.Controls[ControlName].Left = Conversions.ToInteger(DataA);
				break;
			case "Font":
				base.Controls[ControlName].Font = new Font(DataA, Conversions.ToInteger(DataB));
				break;
			case "Focus":
				base.Controls[ControlName].Select();
				break;
			}
		}
		catch (Exception ex)
		{
			ProjectData.SetProjectError(ex);
			Exception ex2 = ex;
			ProjectData.ClearProjectError();
		}
	}

