	public void ControlAChange(string ControlAName, string ControlName, string Setting, string Data)
	{
		try
		{
			if (base.Controls[ControlAName].Controls[ControlName].InvokeRequired)
			{
				SetControl3Callback method = ControlAChange;
				Invoke(method, ControlAName, ControlName, Setting, Data);
				return;
			}
			switch (Setting)
			{
			case "Text":
				base.Controls[ControlAName].Controls[ControlName].Text = Data;
				base.Controls[ControlAName].Controls[ControlName].Refresh();
				break;
			case "Color":
				switch (Data)
				{
				case "OrangeRed":
					base.Controls[ControlAName].Controls[ControlName].ForeColor = Color.OrangeRed;
					break;
				case "Green":
					base.Controls[ControlAName].Controls[ControlName].ForeColor = Color.Green;
					break;
				case "Standard":
					base.Controls[ControlAName].Controls[ControlName].ForeColor = Color.FromArgb(128, 255, 255);
					break;
				default:
					base.Controls[ControlAName].Controls[ControlName].ForeColor = Color.White;
					break;
				}
				break;
			case "Visible":
				if (Operators.CompareString(Data, "False", TextCompare: false) == 0)
				{
					base.Controls[ControlAName].Controls[ControlName].Visible = false;
				}
				else
				{
					base.Controls[ControlAName].Controls[ControlName].Visible = true;
				}
				break;
			case "Enabled":
				if (Operators.CompareString(Data, "False", TextCompare: false) == 0)
				{
					base.Controls[ControlAName].Controls[ControlName].Enabled = false;
				}
				else
				{
					base.Controls[ControlAName].Controls[ControlName].Enabled = true;
				}
				break;
			case "BackgroundImageLayout":
				if (Operators.CompareString(Data, "Zoom", TextCompare: false) == 0)
				{
					base.Controls[ControlAName].Controls[ControlName].BackgroundImageLayout = ImageLayout.Zoom;
				}
				else
				{
					base.Controls[ControlAName].Controls[ControlName].BackgroundImageLayout = ImageLayout.Stretch;
				}
				break;
			case "Height":
				base.Controls[ControlAName].Controls[ControlName].Height = Conversions.ToInteger(Data);
				break;
			case "Width":
				base.Controls[ControlAName].Controls[ControlName].Width = Conversions.ToInteger(Data);
				break;
			case "Top":
				base.Controls[ControlAName].Controls[ControlName].Top = Conversions.ToInteger(Data);
				break;
			case "Left":
				base.Controls[ControlAName].Controls[ControlName].Left = Conversions.ToInteger(Data);
				break;
			case "Font":
				base.Controls[ControlAName].Controls[ControlName].Font = new Font(base.Controls[ControlAName].Controls[ControlName].Font.FontFamily, Conversions.ToInteger(Data));
				break;
			case "Focus":
				base.Controls[ControlAName].Controls[ControlName].Select();
				break;
			case "SelectedItem":
				switch (ControlName)
				{
				case "DOBDay":
					if (Conversions.ToInteger(Data) <= 9 && (object)Data != "Day")
					{
						MyProject.Forms.Information.DOBDay.SelectedItem = "0" + Data.ToString();
					}
					else
					{
						MyProject.Forms.Information.DOBDay.SelectedItem = Data;
					}
					break;
				case "RefDay":
					if (Conversions.ToInteger(Data) <= 9 && (object)Data != "Day")
					{
						MyProject.Forms.Information.RefDay.SelectedItem = "0" + Data.ToString();
					}
					else
					{
						MyProject.Forms.Information.RefDay.SelectedItem = Data;
					}
					break;
				case "DOBMonth":
					if (Conversions.ToInteger(Data) <= 9 && (object)Data != "Month")
					{
						MyProject.Forms.Information.DOBMonth.SelectedItem = "0" + Data.ToString();
					}
					else
					{
						MyProject.Forms.Information.DOBMonth.SelectedItem = Data;
					}
					break;
				case "RefMonth":
					if (Conversions.ToInteger(Data) <= 9 && (object)Data != "Month")
					{
						MyProject.Forms.Information.RefMonth.SelectedItem = "0" + Data.ToString();
					}
					else
					{
						MyProject.Forms.Information.RefMonth.SelectedItem = Data;
					}
					break;
				case "DOBYear":
					MyProject.Forms.Information.DOBYear.SelectedItem = Data;
					break;
				case "RefYear":
					MyProject.Forms.Information.RefYear.SelectedItem = Data;
					break;
				}
				break;
			case "BringToFront":
				base.Controls[ControlAName].Controls[ControlName].BringToFront();
				break;
			}
		}
		catch (Exception ex)
		{
			ProjectData.SetProjectError(ex);
			Exception ex2 = ex;
			ProjectData.ClearProjectError();
		}
	}

	public void ControlBChange(string ControlBName, string ControlAName, string ControlName, string Setting, string Data)
	{
		try
		{
			if (base.Controls[ControlBName].Controls[ControlAName].Controls[ControlName].InvokeRequired)
			{
				SetControl4Callback method = ControlBChange;
				Invoke(method, ControlBName, ControlAName, ControlName, Setting, Data);
				return;
			}
			switch (Setting)
			{
			case "Text":
				base.Controls[ControlBName].Controls[ControlAName].Controls[ControlName].Text = Data;
				break;
			case "Visible":
				if (Operators.CompareString(Data, "False", TextCompare: false) == 0)
				{
					base.Controls[ControlBName].Controls[ControlAName].Controls[ControlName].Visible = false;
				}
				else
				{
					base.Controls[ControlBName].Controls[ControlAName].Controls[ControlName].Visible = true;
				}
				break;
			case "Enabled":
				if (Operators.CompareString(Data, "False", TextCompare: false) == 0)
				{
					base.Controls[ControlBName].Controls[ControlAName].Controls[ControlName].Enabled = false;
				}
				else
				{
					base.Controls[ControlBName].Controls[ControlAName].Controls[ControlName].Enabled = true;
				}
				break;
			case "BackgroundImageLayout":
				if (Operators.CompareString(Data, "Zoom", TextCompare: false) == 0)
				{
					base.Controls[ControlBName].Controls[ControlAName].Controls[ControlName].BackgroundImageLayout = ImageLayout.Zoom;
				}
				else
				{
					base.Controls[ControlBName].Controls[ControlAName].Controls[ControlName].BackgroundImageLayout = ImageLayout.Stretch;
				}
				break;
			case "Height":
				base.Controls[ControlBName].Controls[ControlAName].Controls[ControlName].Height = Conversions.ToInteger(Data);
				break;
			case "Width":
				base.Controls[ControlBName].Controls[ControlAName].Controls[ControlName].Width = Conversions.ToInteger(Data);
				break;
			case "Top":
				base.Controls[ControlBName].Controls[ControlAName].Controls[ControlName].Top = Conversions.ToInteger(Data);
				break;
			case "Left":
				base.Controls[ControlBName].Controls[ControlAName].Controls[ControlName].Left = Conversions.ToInteger(Data);
				break;
			case "Font":
				base.Controls[ControlBName].Controls[ControlAName].Controls[ControlName].Font = new Font(base.Controls[ControlBName].Controls[ControlAName].Controls[ControlName].Font.FontFamily, Conversions.ToInteger(Data));
				break;
			case "Focus":
				base.Controls[ControlBName].Controls[ControlAName].Controls[ControlName].Select();
				break;
			}
		}
		catch (Exception ex)
		{
			ProjectData.SetProjectError(ex);
			Exception ex2 = ex;
			ProjectData.ClearProjectError();
		}
	}

