	[MethodImpl(MethodImplOptions.NoInlining | MethodImplOptions.NoOptimization)]
	private void ProgramClose()
	{
		switch (SelectionEnd)
		{
		case 1:
			PCExit = true;
			WriteMachineHistory();
			Application.Exit();
			CloseVersion.SetValue("Open", "0");
			ProjectData.EndApp();
			break;
		case 2:
			PCShutDown = true;
			WriteMachineHistory();
			Process.Start("shutdown.exe", "/s /t 00 /f");
			Application.Exit();
			CloseVersion.SetValue("Open", "0");
			ProjectData.EndApp();
			break;
		case 3:
			PCRestart = true;
			WriteMachineHistory();
			Process.Start("shutdown.exe", "/r /t 00 /f");
			Application.Exit();
			CloseVersion.SetValue("Open", "0");
			ProjectData.EndApp();
			break;
		}
	}

