	private void KeyPressDouble()
	{
		if (!EmergencyEmptyRemoteOne)
		{
			EmergencyEmptyRemoteTM.Enabled = true;
			EmergencyEmptyRemoteOne = true;
		}
		else if (!EmergencyEmptyRemoteTwo)
