	public void ConveyorDirection()
	{
		if (!NoChanges & (ControlLevel == 0))
		{
			if ((!ProgramRun | (ProgramRun & ProgramHold)) && ((ProgramNumSpeed == 0) & (Conversions.ToInteger(Speed_mph.Text) == 0)))
			{
				if (!SpeedProgramReverse)
				{
					SpeedProgramReverse = true;
					FlashReverse.Enabled = true;
				}
				else
				{
					SpeedProgramReverse = false;
				}
				TitleSpeedProgram(0);
			}
			DisplayOn = true;
		}
		else if (!NoChangesTM.Enabled)
		{
			NoChangesTM.Enabled = true;
		}
	}

