		ControlAChange("TrainingDuration", "DebugEng", "Visible", EngDebug.ToString());
		Interaction.SaveSetting("Treadmill", "Health", "Debug", EngDebug.ToString());
	}

	public void EngineerPass(bool Pass)
	{
		if (Pass)
		{
			if (Operators.CompareString(Interaction.GetSetting("DTread", "File", "SerialFile0", "0"), "92AA83C74A63F", TextCompare: false) == 0)
			{
				EngPass = false;
				ControlAChange("TrainingDuration", "PassEng", "Visible", "False");
				HandleCounter = false;
				MyProject.Forms.SetupDepth.Hide();
			}
			else
			{
				EngPass = true;
				base.TopMost = false;
				ControlAChange("TrainingDuration", "PassEng", "Visible", "True");
			}
		}
		else if (Operators.CompareString(Interaction.GetSetting("DTread", "File", "SerialFile0", "0"), "10FF92A83C72B", TextCompare: false) == 0)
		{
			Interaction.SaveSetting("DTread", "File", "SerialFile0", "92AA83C74A63F");
			EngPass = false;
			MyProject.Forms.SetupDepth.Hide();
			ControlAChange("TrainingDuration", "PassEng", "Visible", "False");
			HandleCounter = false;
		}
		else
		{
			Interaction.SaveSetting("DTread", "File", "SerialFile0", "10FF92A83C72B");
			EngPass = true;
			base.TopMost = false;
			EngPassTime = Conversions.ToDate(DateAndTime.Now.ToLongDateString());
			Interaction.SaveSetting("DTread", "File", "SerialFileEng", Conversions.ToString(EngPassTime));
			ControlAChange("TrainingDuration", "PassEng", "Visible", "True");
		}
	}

	public void ShowBoards(string Board)
	{
		switch (Board)
		{
		case "IOPOT":
			IOPOT.Show();
			IOPOT.WindowState = FormWindowState.Normal;
			IOPOT.Visible = true;
			IOPOT.Location = checked(new Point((int)Math.Round((double)base.Width / 2.0 - (double)IOPOT.Width / 2.0), (int)Math.Round((double)base.Height / 3.0 - (double)IOPOT.Height / 2.0)));
			if (!EngDebug)
			{
			}
			break;
		case "MACHINE":
			MyProject.Forms.MachineSetup.Show();
			MyProject.Forms.MachineSetup.WindowState = FormWindowState.Normal;
			MyProject.Forms.MachineSetup.Visible = true;
			break;
		case "RLY88":
