			RLY08.WindowState = FormWindowState.Normal;
			RLY08.Visible = true;
			if (EngDebug)
			{
				RLY08.TopMost = false;
			}
			break;
		case "RLY82":
			RLY82.Show();
			RLY82.WindowState = FormWindowState.Normal;
			RLY82.Visible = true;
			if (EngDebug)
			{
				RLY82.TopMost = false;
			}
			break;
		case "USBISS":
			USBISS.Show();
			USBISS.WindowState = FormWindowState.Normal;
			USBISS.Visible = true;
			if (EngDebug)
			{
				USBISS.TopMost = false;
			}
			break;
		case "I2CPOT":
			MyProject.Forms.I2CPot.Show();
			MyProject.Forms.I2CPot.WindowState = FormWindowState.Normal;
			MyProject.Forms.I2CPot.Visible = true;
			if (EngDebug)
			{
				MyProject.Forms.I2CPot.TopMost = false;
			}
			break;
		case "POT8":
			POT8.Show();
			POT8.WindowState = FormWindowState.Normal;
			POT8.Visible = true;
			if (EngDebug)
			{
				POT8.TopMost = false;
