			MyProject.Forms.Speaker.Show();
			MyProject.Forms.Speaker.WindowState = FormWindowState.Normal;
			MyProject.Forms.Speaker.Visible = true;
			if (EngDebug)
			{
				MyProject.Forms.Speaker.TopMost = false;
