		case "VOICE":
			MyProject.Forms.VoiceRecognizer.Show();
			MyProject.Forms.VoiceRecognizer.WindowState = FormWindowState.Normal;
			MyProject.Forms.VoiceRecognizer.Visible = true;
			if (EngDebug)
			{
				MyProject.Forms.VoiceRecognizer.TopMost = false;
			}
			break;
		case "LEVEL":
			ZeroLevel();
			break;
		case "LEVELX":
