			ProgramRemoteImage("HoldDeSW1");
		}
		StartProgramPicHold = "HoldDeSW1";
		StartProgramPicDe = "HoldSW1";
	}

	public void ProgramSandBox()
	{
		if (MachineSetup.VoiceControlOnOff & NewSpeech)
		{
			ProgramRemoteImage("SandBoxVoice");
		}
		else
		{
			ProgramRemoteImage("SandBox");
		}
		StartProgramPicHold = "SandBox";
	}
}
